def v19_prefs(uid: int) -> dict:
    """تنظیمات شخصی کاربر (mute و ...)."""
    try:
        s = DATA.setdefault("v19", {})
        prefs = s.setdefault("prefs", {})
        p = prefs.setdefault(user_key(int(uid)), {})
        p.setdefault("mute", False)
        return p
    except Exception:
        return {"mute": False}


def anti_abuse_cfg(chat_id: int) -> dict:
    """تنظیمات ضد اذیت گروه با merge روی پیش‌فرض‌ها."""
    try:
        cfg_all = DATA.setdefault("v19", {}).setdefault("cfg", {})
        key = group_key(int(chat_id)) if int(chat_id) else "global"
        cfg = cfg_all.setdefault(key, {})
        merged = dict(ANTI_ABUSE_DEFAULTS)
        merged.update({k: v for k, v in cfg.items() if k in ANTI_ABUSE_DEFAULTS})
        merged["stall"] = bool(merged["stall"])
        merged["welcome"] = bool(merged["welcome"])
        merged["quiet_on"] = bool(merged["quiet_on"])
        merged["rmin"] = max(1, min(15, int(merged["rmin"])))
        merged["smin"] = max(3, min(60, int(merged["smin"])))
        if merged["smin"] <= merged["rmin"]:
            merged["smin"] = merged["rmin"] + 3
        merged["qfrom"] = max(0, min(23, int(merged["qfrom"])))
        merged["qto"] = max(0, min(23, int(merged["qto"])))
        try:
            merged["rlvl"] = max(0, min(2, int(merged["rlvl"])))
        except Exception:
            merged["rlvl"] = 1
        cfg.clear()
        cfg.update(merged)
        return merged
    except Exception:
        return dict(ANTI_ABUSE_DEFAULTS)


def chat_cfg(chat_id: int) -> dict:
    """تنظیمات پنل/امکانات هر چت."""
    try:
        all_cfg = DATA.setdefault("v20", {}).setdefault("gcfg", {})
        cfg = all_cfg.setdefault(group_key(int(chat_id)), {})
        merged = dict(CHAT_CFG_DEFAULTS)
        merged.update({k: v for k, v in cfg.items() if k in CHAT_CFG_DEFAULTS})
        merged["stale_h"] = max(1, min(72, int(merged["stale_h"])))
        merged["pmax"] = max(1, min(24, int(merged["pmax"])))
        merged["daily_goal"] = max(5, min(500, int(merged["daily_goal"])))
        for b in ("back", "delcmd", "stale", "teams", "daily", "welcome", "levelup", "ads"):
            merged[b] = bool(merged[b])
        cfg.clear()
        cfg.update(merged)
        return merged
    except Exception:
        return dict(CHAT_CFG_DEFAULTS)


def save_chat_cfg(chat_id: int, cfg: dict) -> None:
    DATA.setdefault("v20", {}).setdefault("gcfg", {})[group_key(int(chat_id))] = dict(cfg)


