def nav_is_panel(data: str) -> bool:
    """آیا این کالبک یک «پنل» باز می‌کند (و باید روی پشته برود)؟"""
    d = str(data or "")
    if d == "NAV|BACK" or d == "H|HOME" or d == "H|CLOSE":
        return False
    return any(d.startswith(p) for p in _NAV_PANEL_PREFIXES)


def nav_push(uid: int, data: str) -> None:
    """ثبت باز شدن یک پنل روی مسیر کاربر (خصوصی)."""
    try:
        stack = NAV_STACKS.setdefault(int(uid), [])
        if stack and stack[-1][0] == str(data):
            return
        stack.append([str(data), time.time()])
        del stack[:-NAV_MAX_DEPTH]
    except Exception:
        pass


def nav_clear(uid: int) -> None:
    """پاک کردن مسیر (برگشت به خانه)."""
    try:
        NAV_STACKS.pop(int(uid), None)
    except Exception:
        pass


def nav_pop(uid: int) -> str | None:
    """یک قدم به عقب: پنلِ فعلی را برمی‌دارد و کالبکِ پنلِ قبلی را می‌دهد."""
    try:
        stack = NAV_STACKS.get(int(uid)) or []
        now = time.time()
        while stack and now - float(stack[-1][1]) > NAV_STALE_SEC:
            stack.pop()
        if not stack:
            return None
        stack.pop()              # پنل فعلی
        if not stack:
            NAV_STACKS.pop(int(uid), None)
            return None
        return str(stack[-1][0])  # پنل قبلی — به‌عنوان فعلیِ جدید باقی می‌ماند
    except Exception:
        return None


def nav_footer(home: bool = True) -> list:
    """ردیف ناوبری کامل (۸.۰): ⬅️ برگشت به منوی قبل + 🏠 منوی اصلی."""
    row = [btn("⬅️ برگشت", "NAV|BACK")]
    if home:
        row.append(btn("🏠 منوی اصلی", "H|HOME"))
    return row


async def nav_back_handler(update: Update, context: ContextTypes.DEFAULT_TYPE,
                            query, uid: int) -> tuple[str, str]:
    """اجرای دکمه‌ی برگشت — کالبکِ مقصد و پیشوندش را برمی‌گرداند."""
    prev = nav_pop(int(uid))
    await safe_answer_query(query)
    if not prev:
        nav_clear(int(uid))
        return "H|HOME", "H"
    return prev, str(prev).split("|")[0]


def nav_retarget(query, new_data: str) -> bool:
    """تغییر مقصد کالبک‌کوئری به‌صورت ایمن (نمایشگاه ۱۰.۰).

    ریشه‌ی باگ تاریخی «همه‌ی دکمه‌های برگشت خطا می‌دادند» همین‌جا بود:
    python-telegram-bot آبجکت‌های واقعیِ رسیده از تلگرام را **فروزن** می‌کند
    (TelegramObject.__setattr__ خطای AttributeError می‌دهد). قبلاً با
    ``query.data = data`` سعی در تغییر مقصد داشتیم که روی PTB واقعی
    همیشه می‌شکست — تست‌های فیک نمی‌دیدندش!

    سه لایه‌ی دفاعی:
      ۱) انتساب عادی (آبجکت‌های غیرفروزن — تست‌ها)
      ۲) object.__setattr__ (دور زدن گارد فروزن — PTB 20..22+، «data»
         در __slots__ است و این مسیر رسمی/ایمن است)
      ۳) شکست کامل → False (روتر خودش مسیر جایگزین را می‌رود)
    """
    try:
        query.data = new_data  # noqa: SLF001 — عمدی: آبجکت غیرفروزن
        return True
    except Exception:
        pass
    try:
        object.__setattr__(query, "data", str(new_data))
        return True
    except Exception:
        return False


def card(title: str, *lines: str) -> str:
    body = "\n".join(str(x) for x in lines if str(x).strip())
    return f"<b>{escape(title)}</b>\n━━━━━━━━━━━━━━━━━━\n{body}"


def breadcrumb(*parts: str) -> str:
    return " › ".join(f"<b>{escape(p)}</b>" for p in parts if p)


def fmt_num(n) -> str:
    try:
        return f"{int(n):,}".replace(",", "،")
    except Exception:
        return str(n)


def progress_bar(current: float, total: float, width: int = 10) -> str:
    try:
        total = max(1, float(total))
        frac = max(0.0, min(1.0, float(current) / total))
    except Exception:
        frac = 0.0
    filled = int(round(frac * width))
    return "█" * filled + "░" * (width - filled)


async def safe_answer_query(query, text: str | None = None, show_alert: bool = False) -> None:
    """پاسخ به کلیک — هرگز EXCEPTION بیرون نمی‌دهد (ضد دکمه‌ی مرده)."""
    try:
        await query.answer(text=text, show_alert=show_alert)
    except Exception:
        pass


async def safe_edit(query, text: str, markup=None) -> None:
    try:
        await query.edit_message_text(
            text,
            parse_mode=ParseMode.HTML,
            reply_markup=markup,
            disable_web_page_preview=True,
        )
        return
    except Exception as exc:
        msg = getattr(exc, "message", "") or str(exc)
        if "not modified" in str(msg).lower() or "message is not modified" in str(msg).lower():
            return
    try:
        await query.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
    except Exception:
        pass


async def safe_delete(message) -> None:
    try:
        await message.delete()
    except Exception:
        pass


# ================================================================
#  محافظ اسپم (Rate Guard)
# ================================================================
RATE_MAX_CLICKS = max(1, int(os.getenv("APEX_RATE_MAX", "16") or 16))
RATE_WINDOW = 15.0
_rate_clicks: dict[int, list] = {}
_rate_warned: set = set()


def rate_check(uid: int) -> bool:
    """محافظ کلیک سریع — سقف و پنجره از پنل مدیریت قابل تنظیم است (۶.۲)."""
    try:
        cfg = syscfg()
        if not cfg.get("rate_enabled", True):
            return True
        rmax = int(cfg.get("rate_max", RATE_MAX_CLICKS))
        rwin = float(cfg.get("rate_window", RATE_WINDOW))
    except Exception:
        rmax, rwin = RATE_MAX_CLICKS, RATE_WINDOW
    now = time.time()
    hist = _rate_clicks.setdefault(int(uid), [])
    hist[:] = [t for t in hist if now - t < rwin]
    if len(hist) >= rmax:
        return False
    hist.append(now)
    return True


def rate_forget(uid: int) -> None:
    _rate_clicks.pop(int(uid), None)
    _rate_warned.discard(int(uid))


# ================================================================
#  پنل‌های فعال (محدودسازی تعداد پنل باز هر کاربر + انقضا)
# ================================================================
_active_panels: dict[int, dict] = {}


def panel_register(uid: int, chat_id: int, message_id: int, tag: str = "") -> None:
    """ثبت پنل فعال برای رفرش خودکار."""
    try:
        uid = int(uid)
        cfg = chat_cfg(chat_id)
        panels = _active_panels.setdefault(uid, {})
        if len(panels) >= int(cfg.get("pmax", 6)):
            oldest = min(panels.items(), key=lambda kv: kv[1].get("ts", 0))[0]
            panels.pop(oldest, None)
        panels[str(message_id)] = {"ts": time.time(), "tag": str(tag)}
        # ثبت در registry برای رفرش خودکار گروه
        if int(chat_id) < 0:  # فقط گروه‌ها
            reg = DATA.setdefault("_panel_registry", {})
            reg[f"{chat_id}_{message_id}"] = {
                "ts": time.time(),
                "chat_id": int(chat_id),
                "message_id": int(message_id),
                "uid": int(uid),
                "tag": str(tag),
            }
    except Exception:
        pass


def panel_stale(uid: int, message_id: int) -> bool:
    """آیا این پنل برای این کاربر منقضی شده؟ (ساعت‌ها از ثبت گذشته)"""
    try:
        info = _active_panels.get(int(uid), {}).get(str(int(message_id)))
        if not info:
            return False
        cfg_h = 12
        # از تنظیمات چت خصوصی کاربر هم می‌توان استفاده کرد؛ پیش‌فرض ۱۲ ساعت
        return (time.time() - float(info.get("ts", 0))) > cfg_h * 3600
    except Exception:
        return False


# ================================================================
#  🎬 منوی زنده (۶.۵) — رجیستری انیمیشن منوی خصوصی
#  تلگرام به هیچ باتی اجازه‌ی CSS/HTML روی دکمه‌ها نمی‌دهد؛ نزدیک‌ترین
#  معادلِ واقعیِ «انیمیشن آیکون‌ها»، تعویض نرم فریم‌ها با ویرایش دوره‌ای
#  همان پیام است. این رجیستری می‌گوید منوی کدام کاربر هنوز «خانه» است.
# ================================================================
_home_live: dict[int, dict] = {}   # uid -> {"chat_id", "msg_id", "frame", "due"}


def home_live_mark(uid: int, chat_id: int, message_id: int) -> None:
    """ثبت منوی اصلی کاربر برای انیمیشن زنده (فقط چت خصوصی — شناسه‌ی مثبت)."""
    try:
        if int(chat_id) < 0 or not message_id:
            return
        interval = max(3, min(60, int(syscfg().get("home_anim_interval", 5))))
        _home_live[int(uid)] = {
            "chat_id": int(chat_id),
            "msg_id": int(message_id),
            "frame": 1,
            "due": time.time() + interval,
        }
    except Exception:
        pass


def home_live_drop(uid: int) -> None:
    """حذف کاربر از موتور منوی زنده (وقتی از منوی اصلی خارج شد)."""
    try:
        _home_live.pop(int(uid), None)
    except Exception:
        pass


def home_live_is_tracked(uid: int, chat_id: int, message_id: int) -> bool:
    """آیا این پیامِ خصوصی، همان پیام منوی زنده‌ی این کاربر است؟"""
    try:
        info = _home_live.get(int(uid))
        return bool(info and int(info.get("msg_id", 0)) == int(message_id)
                    and int(info.get("chat_id", 0)) == int(chat_id))
    except Exception:
        return False


async def platform_mode_primer(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """🖥📱 (۹.۰) پرایمر موتور نمایش تطبیقی — اولین هندلرِ هر آپدیت.

    قبل از هر پردازشی، حالت نمایش کاربرِ در حال تعامل روی رندر ست
    می‌شود: چت خصوصی → انتخاب شخصی کاربر («خودکار» = موبایل-امن)؛
    گروه → همیشه موبایل-امن (چون همه با هم یک پنل را می‌بینند).
    هیچ پاسخی تولید نمی‌کند و هرگز خطا نمی‌دهد.
    """
    try:
        u = update.effective_user
        if u is not None and not getattr(u, "is_bot", False):
            chat = getattr(update, "effective_chat", None)
            ctype = str(getattr(chat, "type", "private") or "private")
            if ctype == "private":
                RENDER_MODE.set(user_display_mode(int(u.id)))
            else:
                RENDER_MODE.set(_DM_MOBILE)
    except Exception:
        pass


async def home_live_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """🎬 نگهبان منوی زنده — قبل از همه‌ی هندلرها اجرا می‌شود.

    به محض این‌که کاربر با دکمه‌ای غیر از «منوی اصلی» از خانه خارج شود،
    انیمیشن همان پیام متوقف می‌شود تا موتور هرگز صفحه‌ی فعلی کاربر را
    نپرد و با سیستم تک‌پیام در تضاد نیفتد.
    """
    try:
        q = update.callback_query
        if q is None or q.message is None or q.from_user is None:
            return
        chat = q.message.chat
        if chat is None or chat.type != "private":
            return
        data = str(q.data or "")
        if data in ("H|HOME", "H|MORE"):
            return  # این دو خودشان منوی اصلی را برمی‌گردانند
        if home_live_is_tracked(int(q.from_user.id), int(chat.id), int(q.message.message_id)):
            home_live_drop(int(q.from_user.id))
    except Exception:
        pass


# ================================================================
#  🧹 سیستم تک‌پیام (UI Ledger) — «همه‌چی با یک پیام پیش بره»
#  هر دستور جدید، پیام‌های قبلیِ ربات را در همان چت پاک می‌کند؛
#  هم در PV و هم در گروه. پیام‌های ارسالی ربات خودکار ردیابی می‌شوند
#  و کارت سوالِ در انتظار Reply هرگز پاک نمی‌شود.
# ================================================================
UI_LEDGER_CAP = 8            # سقف پیام‌های ردیابی‌شده در هر چت (ضد انباشت)
UI_TAG_PANEL = "panel"       # منو/پنل — با دستور بعدی پاک می‌شود
UI_TAG_TURN = "turn"         # کارت نوبت — با کارت نوبت بعدی جایگزین می‌شود
UI_TAG_QUESTION = "question"  # کارت سوال/حکم — تا وقتی Reply نخورده محافظت می‌شود
UI_LEDGER: dict[str, list] = {}   # chat_id -> [[message_id, tag], ...]


def _ui_ledger_sync() -> None:
    """همگام‌سازی لجر با DATA تا بعد از ری‌استارت هم ادامه داشته باشد."""
    try:
        DATA["_ui_ledger"] = {k: v for k, v in UI_LEDGER.items() if v}
    except Exception:
        pass


def _ui_ledger_load() -> None:
    """بازیابی لجر پس از ری‌استارت (ضد crash)."""
    try:
        saved = DATA.get("_ui_ledger", {})
        if isinstance(saved, dict):
            for k, v in saved.items():
                if isinstance(v, list):
                    UI_LEDGER[str(k)] = [[int(e[0]), str(e[1]) if len(e) > 1 else UI_TAG_PANEL]
                                         for e in v if isinstance(e, (list, tuple)) and len(e) >= 1]
    except Exception:
        pass


def ui_is_protected(chat_id: int, message_id: int) -> bool:
    """آیا این پیام نباید پاک شود؟
    ۱) کارت سوال/حکمی که منتظر Reply است؛
    ۲) پنل اصلی بازی وقتی لابی باز است یا کارت نوبت منتظر انتخاب موضوع/هدف است.
    """
    try:
        game = active_game(int(chat_id))
        if game:
            if isinstance(game.get("reply_prompt"), dict):
                rp = game["reply_prompt"]
                if int(rp.get("message_id", -1)) == int(message_id) and time.time() < float(rp.get("expires", 0)):
                    return True
            if (str(game.get("phase")) in ("lobby", "topic", "target")
                    and int(game.get("_panel_msg_id", 0) or 0) == int(message_id)):
                return True
    except Exception:
        pass
    return False


def _ui_registry_forget(chat_id: int, message_id: int) -> None:
    """حذف پیامِ پاک‌شده از رجیستری رفرش خودکار گروه."""
    try:
        reg = DATA.get("_panel_registry")
        if isinstance(reg, dict):
            reg.pop(f"{int(chat_id)}_{int(message_id)}", None)
    except Exception:
        pass


async def _ui_delete_quiet(bot, chat_id: int, message_id: int) -> None:
    """حذف بی‌صدا — هر خطایی نادیده گرفته می‌شود."""
    try:
        await bot.delete_message(int(chat_id), int(message_id))
    except Exception:
        pass


async def ui_after_send(bot, chat_id: int, message_id: int) -> None:
    """بعد از هر ارسال: ثبت در لجر + مدیریت سقف (قدیمی‌ترین غیرمحافظت‌شده پاک می‌شود)."""
    try:
        cid = str(int(chat_id))
        lst = UI_LEDGER.setdefault(cid, [])
        mid = int(message_id)
        if not any(e[0] == mid for e in lst):
            lst.append([mid, UI_TAG_PANEL])
        # سقف: بیش از UI_LEDGER_CAP پیام در یک چت انباشته نشود
        while len(lst) > UI_LEDGER_CAP:
            victim = None
            for e in lst:
                if not ui_is_protected(chat_id, e[0]):
                    victim = e
                    break
            if victim is None:
                break
            lst.remove(victim)
            await _ui_delete_quiet(bot, chat_id, victim[0])
            _ui_registry_forget(chat_id, victim[0])
        _ui_ledger_sync()
    except Exception:
        pass


def ui_retag(chat_id: int, message_id: int, tag: str) -> None:
    """تغییر برچسب پیام (مثلاً turn/question) برای پاک‌سازی هوشمندتر."""
    try:
        cid = str(int(chat_id))
        mid = int(message_id)
        for e in UI_LEDGER.get(cid, []):
            if e[0] == mid:
                e[1] = str(tag)
                _ui_ledger_sync()
                return
        UI_LEDGER.setdefault(cid, []).append([mid, str(tag)])
        _ui_ledger_sync()
    except Exception:
        pass


def ui_hold(chat_id: int, message_id: int) -> None:
    """پیام مهم (همگانی/پاسخ پشتیبانی/DM ادمین) از چرخه‌ی پاک‌سازی خارج می‌شود."""
    try:
        cid = str(int(chat_id))
        mid = int(message_id)
        UI_LEDGER[cid] = [e for e in UI_LEDGER.get(cid, []) if e[0] != mid]
        _ui_ledger_sync()
    except Exception:
        pass


def ui_forget(chat_id: int, message_id: int) -> None:
    """حذف یک پیام از لجر (مثلاً بعد از TTL خودکار)."""
    ui_hold(chat_id, message_id)


async def ui_sweep_chat(bot, chat_id: int) -> None:
    """🧹 پاک‌سازی همه‌ی پیام‌های ردیابی‌شده‌ی این چت — به‌جز کارت سوالِ در انتظار."""
    try:
        cid = str(int(chat_id))
        lst = UI_LEDGER.pop(cid, [])
        keep = []
        for e in lst:
            if ui_is_protected(chat_id, e[0]):
                keep.append(e)
                continue
            await _ui_delete_quiet(bot, chat_id, e[0])
            _ui_registry_forget(chat_id, e[0])
        if keep:
            UI_LEDGER[cid] = keep
        _ui_ledger_sync()
    except Exception:
        pass


async def ui_sweep_tags(bot, chat_id: int, tags) -> None:
    """پاک‌سازی انتخابی — فقط پیام‌هایی با برچسب‌های مشخص (مثلاً کارت‌های نوبت/سوال)."""
    try:
        cid = str(int(chat_id))
        want = set(tags)
        lst = UI_LEDGER.get(cid, [])
        rest = []
        for e in lst:
            if e[1] in want and not ui_is_protected(chat_id, e[0]):
                await _ui_delete_quiet(bot, chat_id, e[0])
                _ui_registry_forget(chat_id, e[0])
            else:
                rest.append(e)
        UI_LEDGER[cid] = rest
        _ui_ledger_sync()
    except Exception:
        pass


async def ui_notice(bot, chat_id: int, text: str, ttl: int = 45, **kw) -> None:
    """📢 اعلان موقت — بعد از ttl ثانیه خودش پاک می‌شود (ضد انباشت در گروه)."""
    try:
        m = await bot.send_message(chat_id, text, **kw)
    except Exception:
        return

    async def _later():
        try:
            await asyncio.sleep(int(ttl))
            await _ui_delete_quiet(bot, chat_id, m.message_id)
            ui_forget(chat_id, m.message_id)
        except Exception:
            pass
    try:
        asyncio.get_running_loop().create_task(_later())
    except Exception:
        pass


async def ui_command_sweeper(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """🧹 فراتر از همه‌ی هندلرها (گروه -95): با هر دستورِ جدید،
    پیام‌های قبلیِ ربات در همان چت پاک می‌شوند (هم PV و هم گروه)
    و در PV خودِ پیام دستور هم بلافاصله پاک می‌شود — تجربه‌ی «تک‌پیام»."""
    msg = update.message
    chat = update.effective_chat
    if msg is None or chat is None or not (msg.text or "").startswith("/"):
        return
    cid = int(chat.id)
    # ۱) همه‌ی پیام‌های قبلیِ ردیابی‌شده‌ی ربات در این چت پاک شوند
    await ui_sweep_chat(context.bot, cid)
    # ۲) گروه: حذفِ خود دستور توسط گیتِ -88 (delcmd) انجام می‌شود؛
    #    در PV همین‌جا پاک می‌شود تا همیشه فقط یک پیام زنده بماند
    if chat.type == "private":
        await safe_delete(msg)


