# ================================================================
# 🎬 فریم‌های انیمیشن منوی زنده (۶.۵) — تلگرام CSS روی دکمه‌ها نمی‌پذیرد؛
# «پالس/چرخش» واقعی با تعویض نرم آیکون‌ها بین دو فریم ساخته می‌شود.
# (۶.۶) رنگِ واقعی دکمه‌ها (style) در هر دو فریم ثابت می‌ماند.
HOME_ICON_ANIM = {
    "games":    ("🎮", "🕹️"),
    "profile":  ("🪪", "🆔"),
    "progress": ("🏆", "🥇"),
    "social":   ("👥", "🫂"),
    "shop":     ("🛍", "🛒"),
    "notify":   ("🔔", "📣"),
    "settings": ("⚙️", "🔧"),
    "help":     ("🎓", "📖"),
    "admin":    ("🛡", "🚨"),
}
HOME_ANIM_SPIN = "◐◓◑◒"   # نبضِ زنده‌ی منو — با هر فریم می‌چرخد


def _anim_icon(key: str, frame: int) -> str:
    """آیکون فریم n — رنگ واقعی دکمه جداگانه در private_home_markup ست می‌شود."""
    pair = HOME_ICON_ANIM.get(key)
    if not pair:
        return ""
    return str(pair[int(frame) % 2])


def private_home_text(uid: int, frame: int = 0) -> str:
    """صفحه‌ی اصلی ربات — زیبا، جذاب، با طراحی حرفه‌ای."""
    u = get_user(uid)
    level = int(u.get("level", 1))
    xp = int(u.get("xp", 0))
    coins = int(u.get("coins", 0))
    games = int(u.get("games", 0))
    wins = int(u.get("wins", 0))
    floor_xp = (level - 1) * 100
    xp_in_level = xp - floor_xp
    g = gender_icon(uid)
    name = escape(str(u.get("name") or "بازیکن"))
    rank_name, rank_icon, rank_row = rank_for_xp(xp)
    lv_tier, lv_code = level_tier(level)
    daily_streak = int(u.get("daily_streak", 0))
    ach_count = len(u.get("achievements", []))
    ach_total = len(ACHIEVEMENTS_BASE) + len(ACHIEVEMENTS_V11)
    unread = unread_notifications(uid)
    is_v = is_vip(int(uid))
    is_ver = is_verified(int(uid))
    rep = int(u.get("reputation", 0))
    elo = int(u.get("elo_rating", 1000))
    title_owned = str(u.get("title", "") or "")
    title_disp = TITLES_SHOP.get(title_owned, {}).get("name", "") if title_owned else title_for(xp)
    badge_owned = str(u.get("badge", "") or "")
    badge_disp = BADGES_SHOP.get(badge_owned, {}).get("name", "") if badge_owned else ""
    try:
        sid = current_season_id()
        season_xp = int(u.get("season_xp", 0))
    except Exception:
        sid, season_xp = "", 0
    try:
        ev_list = active_events()
        ev_line = ""
        if ev_list:
            ev_names = [str(e[1].get("title", "")) for e in ev_list[:2]]
            ev_line = "\n\n" + " · ".join(f"📢 {escape(n)}" for n in ev_names if n)
    except Exception:
        ev_line = ""
    notify_badge = f" 🔴{unread}" if unread else ""
    vip_badge = " 👑" if is_v else ""
    verified_badge = " ✅" if is_ver else ""
    # --- رندر اومگا تطبیقی (۹.۰): کارت شناسایی نسل ۴ ---
    text = (
        f"{og_top()}\n"
        + og_head(g, name + vip_badge + verified_badge + notify_badge,
                  f"{title_disp} {badge_disp}".strip()) + "\n"
        f"{og_sep()}\n"
        f"{og_row('🔥 سطح', pnum(level) + ' · ' + lv_tier)}\n"
        f"{pbar(xp_in_level, 100, 14)}\n"
        f"{og_row(rank_icon + ' رنک', rank_name)}\n"
        f"{og_sep('⋆')}\n"
        + og_row("🪙 سکه", pnum(coins)) + "\n"
        + og_row("🎮 بازی", pnum(games)) + "\n"
        + og_row("🏆 برد", pnum(wins)) + "\n"
        + og_row("🎖 دستاورد", f"{pnum(ach_count)}/{pnum(ach_total)} {pbar(ach_count, max(1, ach_total), 8, pct=False)}") + "\n"
        + og_row("📅 استریک", f"{pnum(daily_streak)} روز") + "\n"
        + og_row("👍 اعتبار", pnum(rep)) + "\n"
        + og_row("⭐ ایلو", pnum(elo))
    )
    if sid:
        text += "\n" + og_row("🌐 فصل " + str(sid), f"{pnum(season_xp)} XP")
    text += f"\n{og_close()}"
    if ev_line:
        text += ev_line
    text += tip_footer()
    # 🎬 ۶.۵ — نبض منوی زنده: وقتی انیمیشن روشن است، نشانگر چرخان می‌چرخد
    try:
        if syscfg().get("home_anim", True):
            text += f"\n{HOME_ANIM_SPIN[int(frame) % 4]} 🎬 منوی زنده"
    except Exception:
        pass
    return text


def private_home_markup(uid: int, frame: int = 0) -> InlineKeyboardMarkup:
    """منوی اصلی نسل ۸ (۷.۰) — شبکه‌ی ۲ستونی + رنگین‌کمانِ کامل.

    (۷.۰) به‌خواسته‌ی کاربر: چیدمان شبکه‌ایِ دوستونه برگشت — دیگر هیچ
    دکمه‌ای تمام‌عرض نیست؛ در عوض همه‌ی دکمه‌ها «رنگِ واقعی» (Bot API 9.4)
    + مربعِ رنگِ هویتی خود را از موتور رنگ معنایی می‌گیرند. ادمین‌ها
    یک ردیفِ دوتاییِ قرمزِ هم‌ترازِ شبکه می‌بینند: 🛡 پنل مدیریت +
    📊 تحلیل‌ها. نگاشت رنگ: بازی‌ها=آبی، پیشرفت/فروشگاه=سبز، اعلان‌ها=
    قرمز، پروفایل/تنظیمات/راهنما=آبی؛ مربع‌ها هویتِ کامل ۸ رنگ را می‌سازند.
    (۶.۵) پالس زنده‌ی آیکون‌ها حفظ شد — رنگ‌ها در هر دو فریم ثابت‌اند.
    (۶.۴) دسترسی مستقیم ادمین به ستون فرمان حفظ شد.
    """
    unread = unread_notifications(uid)
    f = int(frame) % 2
    notify_label = f"{_anim_icon('notify', f)} اعلان‌ها ({unread})" if unread else f"{_anim_icon('notify', f)} اعلان‌ها"
    rows = [
        # 🌈 شبکه‌ی ۲ستونی — هر بخش با رنگِ هویتیِ خودش (نه تمام‌عرض)
        [btn(f"{_anim_icon('games', f)} بازی‌ها", "H|GAMES", "primary"),
         btn(f"{_anim_icon('profile', f)} پروفایل", "H|PROFILE", "primary")],
        [btn(f"{_anim_icon('progress', f)} پیشرفت", "H|PROGRESS", "success"),
         btn(f"{_anim_icon('social', f)} اجتماعی", "H|SOCIAL", "primary")],
        [btn(f"{_anim_icon('shop', f)} فروشگاه", "S|HOME", "success"),
         btn(notify_label, "NT|HOME", "danger")],
        [btn(f"{_anim_icon('settings', f)} تنظیمات", "US|HOME", "primary"),
         btn(f"{_anim_icon('help', f)} راهنما", "H|HELP", "primary")],
    ]
    # 🛡 ستون فرمان ادمین — ردیفِ دوتاییِ قرمز، هم‌تراز شبکه (نه تمام‌عرض)
    if has_permission(int(uid), "admin"):
        rows.append([
            btn(f"{_anim_icon('admin', f)} پنل مدیریت", "A|HOME", "danger"),
            btn("📊 تحلیل‌ها", "A|ANALYTICS", "danger"),
        ])
    return kb(rows)


