async def show_private_home(update: Update, context: ContextTypes.DEFAULT_TYPE, uid: int, fresh_message: bool = False) -> None:
    chat = update.effective_chat
    if chat is None:
        return
    text = private_home_text(uid)
    markup = private_home_markup(uid)
    if fresh_message and update.message is not None:
        m = await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
        panel_register(uid, int(chat.id), m.message_id, "home")
        # 🎬 ۶.۵ — ثبت برای انیمیشن زنده (فقط چت خصوصی)
        home_live_mark(uid, int(chat.id), int(m.message_id))
    else:
        try:
            m2 = await context.bot.send_message(int(chat.id), text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
            if m2 is not None:
                panel_register(uid, int(chat.id), int(m2.message_id), "home")
                home_live_mark(uid, int(chat.id), int(m2.message_id))
        except Exception:
            pass


async def show_group_menu(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, uid: int) -> None:
    """منوی گروه — پنل کامل با طراحی جعبه‌ای و دکمه‌های غنی."""
    game = active_game(chat_id)
    if game and str(game.get("status")) == "active":
        await game_show_panel(update, context, game, uid)
        return
    g = get_group(int(chat_id))
    games_count = int(g.get("created_games", 0))
    league_name = "🥉 برنز"
    try:
        _, league_name = group_league_for(int(chat_id))
    except Exception:
        pass
    adult_on = bool(g.get("adult_mode", False))
    theme_info = ""
    try:
        theme = theme_night_get(int(chat_id))
        if theme:
            theme_info = f"\n│  🌟 تم شب: <b>{theme['name']}</b>"
    except Exception:
        pass
    # آمار بازیکنان فعال گروه
    group_players = 0
    try:
        group_players = sum(1 for u in DATA.get("users", {}).values()
                            if isinstance(u, dict) and int(chat_id) in [int(x) for x in u.get("stats_ext", {}).get("groups_played_in", [])])
    except Exception:
        pass
    # تعداد بازیکنان آنلاین (فعال در ۱ ساعت اخیر)
    online_count = 0
    try:
        now = now_ts()
        online_count = sum(1 for u in DATA.get("users", {}).values()
                          if isinstance(u, dict) and (now - int(u.get("last_active", 0))) < 3600
                          and int(chat_id) in [int(x) for x in u.get("stats_ext", {}).get("groups_played_in", [])])
    except Exception:
        pass
    # اطلاعات مسابقات خصوصی فعال
    lines = [
        ds_top(),
        f"│  ⚔️ <b>{BOT_NAME}</b>",
        "│  <i>مرکز فرمان گروه — جرئت و حقیقت</i>",
        ds_sep(),
        ds_row("🎮 بازی‌های گروه", pnum(games_count)),
        ds_row("🏆 لِگ گروه", league_name),
        ds_row("👥 بازیکنان", pnum(group_players)),
    ]
    if online_count:
        lines.append(ds_row("🟢 آنلاین", pnum(online_count)))
    lines.append(ds_row("🔞 حالت +۱۸", "روشن 🔥" if adult_on else "خاموش"))
    if theme_info:
        lines.append(theme_info.strip())
    lines += [
        ds_sep("⋆"),
        "│  🎯 بازی فعالی نیست — وقتشه یه بازی خفن شروع کنی!",
        "│  💡 دستور /apex یا دکمه‌ی زیر",
        ds_close(),
    ]
    text = "\n".join(lines)
    # 🌍 دکمه‌ی تنظیمات برای همه نمایش داده می‌شود (کنترل مجوز در لحظه‌ی کلیک انجام می‌شود)
    rows = [
        [btn("🎮 ساخت لابی", "L|CREATE"), btn("⚡ بازی سریع", "L|QUICK")],
        [btn("🔞 +۱۸ روشن/خاموش", "L|ADULT"), btn("🌟 تم شب", "L|THEME")],
        [btn("📊 آمار گروه", "L|STATS"), btn("🏆 رتبه‌بندی", "L|TOP")],
        [btn("📜 قوانین", "L|RULES"), btn("❓ راهنما", "H|GUIDE")],
        [btn("⚙️ تنظیمات گروه", "L|SETTINGS")],
    ]
    # اگر از callback صدا زده شده، پیام را ویرایش کن
    if update.callback_query:
        await safe_edit(update.callback_query, text, kb(rows))
    else:
        try:
            await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=kb(rows))
        except Exception:
            pass


