def active_game(chat_id: int) -> dict | None:
    g = get_group(chat_id)
    gid = g.get("active_game")
    if not gid:
        return None
    game = DATA.get("games", {}).get(str(gid))
    if isinstance(game, dict) and str(game.get("status")) == "active":
        return game
    return None


def touch_game(game: dict) -> None:
    game["last_activity"] = now_ts()


def make_game(chat_id: int, leader: int, name: str) -> dict:
    gid = f"g{chat_id}_{now_ts()}_{random.randint(100, 999)}"
    group = get_group(chat_id)
    game = {
        "id": gid,
        "chat_id": int(chat_id),
        "leader_id": int(leader),
        "leader_name": str(name),
        "players": [int(leader)],
        "ready": [],
        "status": "active",
        "phase": "lobby",
        "round": 0,
        "turn_number": 0,
        "turn_index": 0,
        "turn_order": [],
        "current_questioner": None,
        "round_scores": {},
        "used_content": [],
        "v7_used_prompts_global": [],
        "v7_used_penalties": [],
        "pending_penalties": {},
        "names": {str(leader): str(name)},
        "settings": dict(group.get("settings", {})),
        "started_at": 0,
        "last_activity": now_ts(),
        "invite_token": gid,
        "lobby_locked": False,
    }
    with LOCK:
        DATA["games"][gid] = game
        group["active_game"] = gid
    return game


def lobby_text(game: dict) -> str:
    """لابی بازی — طراحی جعبه‌ای حرفه‌ای."""
    players = game.get("players", [])
    ready = [int(x) for x in game.get("ready", [])]
    group = get_group(int(game["chat_id"]))
    mn = int(group.get("min_players", 2))
    mx = int(group.get("max_players", 20))
    adult_on = bool(group.get("adult_mode", False))
    # لیست بازیکنان
    player_lines = []
    for uid in players:
        mark = "✅" if uid in ready else "⏳"
        try:
            u = get_user(int(uid))
            level = int(u.get("level", 1))
            _, rank_icon, _ = rank_for_xp(int(u.get("xp", 0)))
            vip = "👑" if int(u.get("vip_until", 0)) > now_ts() else ""
            ver = "✅" if u.get("verified") else ""
            player_lines.append(f"│  {mark} {mention_user(uid, name_of(uid, game))} 🔥{level} {rank_icon} {vip}{ver}")
        except Exception:
            player_lines.append(f"│  {mark} {mention_user(uid, name_of(uid, game))}")
    ready_pct = (len(ready) * 100 // len(players)) if players else 0
    # اطلاعات تم شب
    theme_info = ""
    try:
        theme = theme_night_get(int(game["chat_id"]))
        if theme:
            theme_info = f"\n│  🌟 تم شب: <b>{theme['name']}</b>"
    except Exception:
        pass
    # اطلاعات لِگ گروه
    league_info = ""
    try:
        _, league_name = group_league_for(int(game["chat_id"]))
        league_info = f"\n│  🏆 لِگ: <b>{league_name}</b>"
    except Exception:
        pass
    lines = [
        ds_top(),
        "│  ⚔️ <b>لابی بازی</b>",
        "│  <i>در انتظار قهرمان‌ها...</i>",
        ds_sep(),
        f"│  👑 سرگروه: {mention_user(int(game['leader_id']), game.get('leader_name') or name_of(int(game['leader_id'])))}",
        ds_row("👥 بازیکنان", f"{pnum(len(players))}/{pnum(mx)}"),
        ds_row("🔞 حالت +۱۸", "روشن 🔥" if adult_on else "خاموش"),
    ]
    if theme_info:
        lines.append("│  🌟 تم شب: <b>" + theme_info.split("<b>", 1)[-1].split("</b>", 1)[0] + "</b>")
    if league_info:
        lines.append("│  🏆 لِگ: <b>" + league_info.split("<b>", 1)[-1].split("</b>", 1)[0] + "</b>")
    lines.append(ds_sep())
    for pl in player_lines:
        lines.append(pl)
    lines += [
        ds_sep("⋆"),
        ds_row("📊 آمادگی", f"{pnum(len(ready))}/{pnum(len(players))} ({ready_pct}٪)"),
        f"│  {pbar(len(ready), max(1, len(players)), 14, pct=False)}",
        ds_row("🚦 حداقل بازیکن", pnum(mn)),
        ds_close(),
    ]
    return "\n".join(lines)


def lobby_markup(game: dict, uid: int = 0) -> InlineKeyboardMarkup:
    """دکمه‌های لابی — 🌍 جهانی و مشترک بین همه‌ی اعضا.

    FIX بحرانی: پیام‌های گروهی در تلگرام فقط «یک» کیبورد مشترک دارند که
    همه‌ی اعضا یکسان می‌بینند؛ رندر وابسته به کاربر باعث می‌شد اعضای غیر
    سازنده هیچ دکمه‌ی پیوستنی نبینند و لابی عملاً قفل می‌شد. حالا کیبورد
    برای همه یکسان است و مجوزها «در لحظه‌ی کلیک» در lobby_callback چک
    می‌شوند (همان چک‌های موجود: عضویت، سرگروهی، ظرفیت و قفل).
    """
    players = [int(x) for x in game.get("players", [])]
    ready = [int(x) for x in game.get("ready", [])]
    group = get_group(int(game["chat_id"]))
    mn = max(2, int(group.get("min_players", 2)))
    mx = max(mn, int(group.get("max_players", 20)))
    locked = bool(game.get("lobby_locked"))
    rows = []
    # ردیف ۱ — پیوستن: همیشه برای همه قابل دیدن (کنترل ظرفیت/قفل در لحظه‌ی کلیک)
    if locked:
        rows.append([btn("🔒 لابی قفل است — سرگروه باید بازش کند", "L|NOP")])
    elif len(players) >= mx:
        rows.append([btn(f"👥 ظرفیت تکمیل است ({pnum(len(players))}/{pnum(mx)})", "L|NOP")])
    else:
        rows.append([btn(f"➕ پیوستن به بازی ({pnum(len(players))}/{pnum(mx)})", "L|JOIN")])
    # ردیف ۲ — آماده‌سازی / خروج (وضعیت آمادی هر نفر کنار اسمش در متن لابیست)
    rows.append([btn("✅ آماده‌ام / لغو آماده", "L|READYTOGGLE"), btn("🚪 خروج", "L|LEAVE")])
    # ردیف ۳ — شروع: همیشه قابل کلیک؛ کنترلِ حداقل بازیکن و سرگروهی در لحظه‌ی کلیک
    all_ready = len(ready) >= len(players) and len(players) >= 2
    if len(players) >= mn and all_ready:
        rows.append([btn("🚀 شروع بازی!", "L|START")])
    else:
        rows.append([btn(f"🚀 شروع بازی ({pnum(len(ready))}/{pnum(len(players))} آماده · حداقل {pnum(mn)} نفر)", "L|START")])
    # ردیف ۴ — ابزارهای سرگروه (کنترل مجوز در لحظه‌ی کلیک)
    rows.append([
        btn("🔐 قفل" if not locked else "🔓 باز کردن", "L|LOCK"),
        btn("🦵 اخراج", "L|KICK"),
        btn("👑 انتقال", "L|HOST"),
    ])
    # ردیف ۵ — لغو + تازه‌سازی دستی (راحتی کاربر وقتی موتور نبض خاموش است)
    rows.append([btn("🔄 تازه‌سازی", "L|REFRESH"), btn("❌ لغو بازی", "L|CANCEL")])
    return kb(rows)


async def lobby_refresh(update_or_none, context, game: dict, query=None, chat_id: int = 0) -> None:
    """به‌روزرسانی پنل لابی (ویرایش همان پیام)."""
    try:
        if query is not None:
            await safe_edit(query, lobby_text(game), lobby_markup(game))
            game["_panel_msg_id"] = int(query.message.message_id)
            panel_reset_timer(game)
            return
        cid = int(chat_id or game.get("chat_id", 0))
        if cid:
            m = await context.bot.send_message(cid, lobby_text(game), parse_mode=ParseMode.HTML,
                                           reply_markup=lobby_markup(game))
            game["_panel_msg_id"] = int(m.message_id)
            panel_reset_timer(game)
    except Exception as exc:
        audit("lobby_refresh_error", 0, int(game.get("chat_id", 0) or 0), repr(exc)[:200])


async def cmd_apex(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """ساخت لابی یا نمایش منوی گروه — با حذف پیام دستور قبلی."""
    msg = update.message
    user = update.effective_user
    chat = update.effective_chat
    if msg is None or user is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        if not onboarding_needed(int(user.id)):
            await show_private_home(update, context, int(user.id), fresh_message=True)
        else:
            await cmd_start(update, context)
        return
    uid = int(user.id)
    if is_banned(uid) and not is_admin(uid):
        await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
        return
    if onboarding_needed(uid):
        try:
            link = f"https://t.me/{(await context.bot.get_me()).username}?start=x"
            await msg.reply_text(
                "👤 اول باید یک بار ثبت‌نام کنی!\n"
                "به چت خصوصی من برو و /start بزن، بعد برگرد 👇",
                parse_mode=ParseMode.HTML,
                reply_markup=kb([[InlineKeyboardButton("📩 ثبت‌نام در چت خصوصی", url=link)]]),
            )
        except Exception:
            await msg.reply_text("👤 اول به چت خصوصی من /start بزن و ثبت‌نام کن.")
        return

    # حذف پیام /apex کاربر در گروه
    if chat_cfg(int(chat.id)).get("delcmd", True):
        await safe_delete(msg)

    game = active_game(int(chat.id))
    if game:
        if str(game.get("phase")) == "lobby":
            # ۶.۳ — لابی فعال: «پنل زنده» را تازه کن (ویرایش همان پیام)؛
            # اگر پیام پنل در دسترس نبود، پیام جدید + ردیابی برای رفرش خودکار.
            pmid = int(game.get("_panel_msg_id", 0) or 0)
            refreshed = False
            if pmid:
                try:
                    await context.bot.edit_message_text(
                        int(chat.id), pmid, lobby_text(game),
                        parse_mode=ParseMode.HTML,
                        reply_markup=lobby_markup(game),
                        disable_web_page_preview=True,
                    )
                    panel_reset_timer(game)
                    refreshed = True
                except Exception:
                    refreshed = False
            if not refreshed:
                m = await context.bot.send_message(int(chat.id), lobby_text(game),
                                                   parse_mode=ParseMode.HTML,
                                                   reply_markup=lobby_markup(game))
                game["_panel_msg_id"] = int(m.message_id)
                panel_reset_timer(game)
        else:
            # بازی فعال — نمایش پنل آگاه از فاز (۶.۳: دکمه‌ها زنده می‌مانند)
            await game_show_panel(update, context, game, uid)
        return

    # بازی فعالی نیست — منوی گروه
    await show_group_menu(update, context, int(chat.id), uid)
    # ثبت message_id پنل برای رفرش خودکار
    try:
        game = active_game(int(chat.id))
        if game:
            game["_panel_msg_id"] = 0  # منوی گروه، نه پنل لابی
    except Exception:
        pass


async def lobby_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None or query.message is None:
        return
    data = str(query.data or "")
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    chat = query.message.chat
    if chat.type not in ("group", "supergroup"):
        await safe_answer_query(query, "این دکمه فقط در گروه کار می‌کند.")
        return
    chat_id = int(chat.id)

    # اکشن‌های بدون نیاز به بازی فعال
    if action == "CREATE":
        game = active_game(chat_id)
        if game is not None and str(game.get("status")) == "active":
            await safe_answer_query(query, "⚠️ بازی فعالی وجود دارد! اول /apexend بزن.")
            return
        if onboarding_needed(uid):
            await safe_answer_query(query, "👤 اول در چت خصوصی من /start بزن و ثبت‌نام کن!", True)
            return
        try:
            await safe_delete(query.message)
        except Exception:
            pass
        # FIX: قبلاً اینجا cmd_apex(update, context) صدا زده می‌شد که در آپدیتِ کالبک
        # update.message == None است و بی‌صدا return می‌کرد؛ یعنی دکمه‌ی «ساخت لابی»
        # هیچ کاری نمی‌کرد. حالا لابی مستقیماً ساخته می‌شود.
        try:
            name = (query.from_user.first_name if query.from_user else None) or name_of(uid) or "بازیکن"
            game = make_game(chat_id, uid, name)
            group = get_group(chat_id)
            group["created_games"] = int(group.get("created_games", 0)) + 1
            analytics_bump("games_started")
            audit("lobby_create", uid, chat_id)
            save_data(force=True)
            m = await context.bot.send_message(
                chat_id, lobby_text(game),
                parse_mode=ParseMode.HTML,
                reply_markup=lobby_markup(game),
            )
            game["_panel_msg_id"] = int(m.message_id)
            # ⏱ ۶.۳ — شمارنده‌ی رفرش از همین لحظه شروع شود (اولین رفرش زنده
            # بعد از «فاصله‌ی تنظیمی» بیاید، نه بلافاصله)
            panel_reset_timer(game)
            try:
                panel_register(uid, chat_id, int(m.message_id), "lobby")
            except Exception:
                pass
        except Exception as exc:
            audit("lobby_create_error", uid, chat_id, repr(exc)[:200])
            await safe_answer_query(query, UX_MSG["error_generic"], True)
        return
    if action == "QUICK":
        # بازی سریع
        game = active_game(chat_id)
        if game is not None and str(game.get("status")) == "active":
            await safe_answer_query(query, "⚠️ بازی فعالی وجود دارد! اول /apexend بزن.")
            return
        if onboarding_needed(uid):
            await safe_answer_query(query, "👤 اول در چت خصوصی من /start بزن و ثبت‌نام کن!", True)
            return
        try:
            await safe_delete(query.message)
        except Exception:
            pass
        # FIX: قبلاً cmd_apexquick(update, context) صدا زده می‌شد که در آپدیتِ کالبک
        # update.message == None است و بی‌صدا return می‌کرد؛ یعنی دکمه‌ی «بازی سریع»
        # هیچ کاری نمی‌کرد. حالا بازی سریع مستقیماً و با شروع صحیح نوبت ساخته می‌شود.
        try:
            name = (query.from_user.first_name if query.from_user else None) or name_of(uid) or "بازیکن"
            game = quick_game_start(chat_id, uid, name)
            if game:
                group = get_group(chat_id)
                group["created_games"] = int(group.get("created_games", 0)) + 1
                analytics_bump("games_started")
                audit("quick_game_start", uid, chat_id)
                save_data(force=True)
                qm = await context.bot.send_message(
                    chat_id,
                    f"{ds_top('⚡')}\n"
                    "│  ⚡ <b>بازی سریع شروع شد!</b>\n"
                    f"{ds_sep()}\n"
                    f"👑 سرگروه: {mention_user(uid, name)}\n"
                    "🎮 بقیه می‌تونن با /apexjoin وارد بشن.\n"
                    "🎯 اولین نوبت شروع می‌شه!",
                    parse_mode=ParseMode.HTML,
                )
                # 🧹 تک‌پیام: کارت بازی سریع با اولین کارت نوبت جایگزین می‌شود
                ui_retag(chat_id, qm.message_id, UI_TAG_TURN)
                await game_send_turn_card(context, game)
            else:
                await safe_answer_query(query, UX_MSG["error_generic"], True)
        except Exception as exc:
            audit("quick_game_error", uid, chat_id, repr(exc)[:200])
            await safe_answer_query(query, UX_MSG["error_generic"], True)
        return
    if action == "RULES":
        await safe_answer_query(query)
        await safe_edit(query,
            f"{ds_top('📜')}\n"
            "│  📜 <b>قوانین بازی</b>\n"
            f"{ds_sep()}\n"
            "۱) /apex رو بفرست تا لابی ساخته بشه\n"
            "۲) بقیه با «پیوستن» وارد بشن و «آماده» بزنن\n"
            "۳) سرگروه «شروع بازی» رو بزنه\n"
            "۴) پرسشگر یک موضوع و هدف انتخاب می‌کنه\n"
            "۵) هدف با Reply به سوال جواب می‌ده\n"
            "۶) با /apexend بازی تمام می‌شه\n\n"
            "💡 برای راهنمای کامل: /apexrules",
            kb([
                [btn("🎮 ساخت لابی", "L|CREATE"), btn("⚡ بازی سریع", "L|QUICK")],
                [btn("⬅️ بازگشت", "H|HOME")],
            ]))
        return
    if action == "STATS":
        await safe_answer_query(query)
        g = get_group(int(chat_id))
        games_count = int(g.get("created_games", 0))
        league_name = "🥉 برنز"
        try:
            _, league_name = group_league_for(int(chat_id))
        except Exception:
            pass
        await safe_edit(query,
            f"📊 <b>آمار گروه</b>\n"
            f"━━━━━━━━━━━━━━━━━━\n"
            f"🎮 بازی‌های ساخته‌شده: <b>{fmt_num(games_count)}</b>\n"
            f"🏆 لِگ گروه: <b>{league_name}</b>",
            kb([
                [btn("🎮 ساخت لابی", "L|CREATE"), btn("⚡ بازی سریع", "L|QUICK")],
                [btn("⬅️ بازگشت", "H|HOME")],
            ]))
        return
    if action == "TOP":
        await safe_answer_query(query)
        await safe_edit(query,
            f"{ds_top('🏆')}\n"
            "│  🏆 <b>رتبه‌بندی گروه</b>\n"
            f"{ds_sep()}\n"
            "برای مشاهده‌ی رتبه‌بندی هفتگی:\n"
            "<code>/apextop</code>\n\n"
            "برای رتبه‌بندی کلی:\n"
            "<code>/apextop_all</code>",
            kb([
                [btn("🎮 ساخت لابی", "L|CREATE"), btn("⚡ بازی سریع", "L|QUICK")],
                [btn("⬅️ بازگشت", "H|HOME")],
            ]))
        return

    if action == "ADULT":
        # روشن/خاموش کردن +۱۸
        g = get_group(int(chat_id))
        # FIX: بررسی مجوز — طبق تریگر متنی «+18» و تنظیمات گروه، فقط سرگروهِ
        # بازی فعال، ادمین‌های تلگرامی گروه یا ادمین ربات اجازه‌ی تغییر دارند.
        # قبلاً is_leader محاسبه می‌شد ولی استفاده نمی‌شد و هر عضوی می‌توانست
        # حالت +۱۸ گروه را عوض کند.
        allowed = is_admin(uid) or is_moderator_in_group(uid, chat_id)
        if not allowed:
            active = active_game(chat_id)
            if active and uid == int(active.get("leader_id", 0)):
                allowed = True
            else:
                try:
                    member = await context.bot.get_chat_member(chat_id, uid)
                    allowed = member.status in ("administrator", "creator")
                except Exception:
                    allowed = False
        if not allowed:
            await safe_answer_query(query, "🔞 فقط سرگروه بازی یا ادمین‌های گروه می‌توانند حالت +۱۸ را تغییر دهند.", True)
            return
        g["adult_mode"] = not bool(g.get("adult_mode", False))
        save_data(force=True)
        audit("adult_mode_toggle", uid, chat_id, "on" if g.get("adult_mode") else "off")
        state = "روشن 🔥" if g.get("adult_mode") else "خاموش"
        await safe_answer_query(query, f"🔞 حالت +۱۸: {state}")
        # رفرش منوی گروه
        await show_group_menu(update, context, chat_id, uid)
        return
    if action == "THEME":
        # نمایش منوی تم شب
        await safe_answer_query(query)
        theme_lines = ["🌟 <b>تم شب گروه</b>", "━━━━━━━━━━━━━━━━━━", ""]
        current_theme = ""
        try:
            t = theme_night_get(int(chat_id))
            if t:
                current_theme = t.get("name", "")
        except Exception:
            pass
        theme_lines.append(f"📍 تم فعلی: <b>{current_theme or '—'}</b>\n")
        theme_lines.append("برای تغییر تم:")
        rows = []
        for key, info in THEME_NIGHTS.items():
            rows.append([btn(f"{info['icon']} {info['name']}", f"L|THEMESET|{key}")])
        rows.append([btn("🔴 خاموش", "L|THEMESET|off")])
        rows.append([btn("⬅️ بازگشت", "H|HOME")])
        await safe_edit(query, "\n".join(theme_lines), kb(rows))
        return
    if action == "THEMESET" and len(parts) > 2:
        theme_key = parts[2]
        if theme_key == "off":
            theme_night_set(int(chat_id), "")
            await safe_answer_query(query, "🔴 تم شب خاموش شد.")
        elif theme_key in THEME_NIGHTS:
            theme_night_set(int(chat_id), theme_key)
            info = THEME_NIGHTS[theme_key]
            await safe_answer_query(query, f"{info['icon']} {info['name']} فعال شد!")
        await show_group_menu(update, context, chat_id, uid)
        return
    if action == "SETTINGS":
        # نمایش تنظیمات گروه
        # FIX: بررسی مجوز — این دکمه فقط برای سرگروه/ادمین نمایش داده می‌شود،
        # اما خودِ هندلر هم باید بررسی کند (ضد ساخت کالبک دستی).
        if not (is_admin(uid) or is_moderator_in_group(uid, chat_id)):
            allowed = False
            try:
                member = await context.bot.get_chat_member(chat_id, uid)
                allowed = member.status in ("administrator", "creator")
            except Exception:
                allowed = False
            if not allowed:
                await safe_answer_query(query, "⚙️ فقط ادمین‌های گروه می‌توانند تنظیمات را ببینند.", True)
                return
        await safe_answer_query(query)
        g = get_group(int(chat_id))
        cfg = chat_cfg(int(chat_id))
        adult_on = bool(g.get("adult_mode", False))
        text = (
            "╭" + "━" * 22 + "╮\n"
            "│  ⚙️ <b>تنظیمات گروه</b>\n"
            "├" + "━" * 22 + "┤\n"
            f"│  🔞 +۱۸: <b>{'روشن 🔥' if adult_on else 'خاموش'}</b>\n"
            f"│  👥 سقف بازیکن: <b>{fmt_num(int(g.get('max_players', 20)))}</b>\n"
            f"│  🚦 حداقل بازیکن: <b>{fmt_num(int(g.get('min_players', 2)))}</b>\n"
            f"│  📢 خوش‌آمد: <b>{'✅' if cfg.get('welcome', True) else '❌'}</b>\n"
            f"│  🎉 جشن لول: <b>{'✅' if cfg.get('levelup', True) else '❌'}</b>\n"
            "╰" + "━" * 22 + "╯"
        )
        rows = [
            [btn("🔞 +۱۸ روشن/خاموش", "L|ADULT")],
            [btn("⬅️ بازگشت", "H|HOME")],
        ]
        await safe_edit(query, text, kb(rows))
        return

    # اکشن‌های نیاز به بازی فعال
    game = active_game(chat_id)
    if game is None:
        await safe_answer_query(query, "این لابی دیگر فعال نیست. با /apex جدید بساز. 🔄")
        try:
            await safe_edit(query, "🪦 این لابی بسته شده است. با /apex یک لابی تازه بساز.")
        except Exception:
            pass
        return

    players = [int(x) for x in game.get("players", [])]
    is_leader = uid == int(game.get("leader_id", 0))

    if action == "JOIN":
        if game.get("lobby_locked"):
            await safe_answer_query(query, "🔒 لابی قفل است!", True)
            return
        if uid in players:
            await safe_answer_query(query, "قبلاً داخل بازی هستی 🙂")
            return
        group = get_group(chat_id)
        maxp = int(group.get("max_players", 20))
        if len(players) >= maxp:
            await safe_answer_query(query, f"ظرفیت تکمیل است ({fmt_num(maxp)} نفر).", True)
            return
        # قفل مجازات: بازیکنِ در حال مجازات نمی‌تواند وارد شود
        if punishment_blocks_join(uid):
            await safe_answer_query(query, "⚖️ اول مجازاتت را تمام کن!", True)
            return
        game["players"].append(uid)
        game["names"][str(uid)] = query.from_user.first_name or name_of(uid)
        touch_game(game)
        save_data()
        await safe_answer_query(query, f"خوش آمدی {escape(query.from_user.first_name or '')} 🎉")
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "READYTOGGLE":
        # 🌍 دکمه‌ی جهانی آماده‌سازی — وضعیت هر کاربر در لحظه‌ی کلیک معکوس می‌شود
        if uid not in players:
            await safe_answer_query(query, "اول با دکمه‌ی «➕ پیوستن به بازی» وارد شو! 🙂", True)
            return
        ready_now = [int(x) for x in game.get("ready", [])]
        if uid in ready_now:
            game["ready"] = [x for x in ready_now if x != uid]
            await safe_answer_query(query, "لغو آماده‌باش ⏳")
        else:
            game["ready"] = ready_now + [uid]
            await safe_answer_query(query, "آماده‌باش ثبت شد ✅")
        touch_game(game)
        save_data()
        await lobby_refresh(None, context, game, query=query)
        return

    if uid not in players and action not in ("NOP",):
        await safe_answer_query(query, "تو داخل این بازی نیستی! اول پیوستن بزن.", True)
        return

    if action == "READY":
        if uid not in [int(x) for x in game.get("ready", [])]:
            game["ready"].append(uid)
        touch_game(game)
        save_data()
        await safe_answer_query(query, "آماده‌باش ثبت شد ✅")
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "UNREADY":
        game["ready"] = [int(x) for x in game.get("ready", []) if int(x) != uid]
        touch_game(game)
        save_data()
        await safe_answer_query(query, "لغو شد ⏳")
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "LEAVE":
        await lobby_remove_player(context, game, uid, query)
        return

    if action == "LOCK":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند لابی را قفل کند.", True)
            return
        game["lobby_locked"] = not bool(game.get("lobby_locked"))
        touch_game(game)
        save_data()
        await safe_answer_query(query, "🔒 لابی قفل شد" if game["lobby_locked"] else "🔓 لابی باز شد")
        await lobby_refresh(None, context, game, query=query)
        return

    # FIX: اخراج هدفمند — قبلاً شاخه‌ی «action == KICK» (نمایش لیست) قبل از
    # شاخه‌ی اخراجِ هدفدار بررسی می‌شد؛ در نتیجه دکمه‌ی هر بازیکن دوباره لیست را
    # نشان می‌داد و اخراج در حلقه‌ی بی‌نهایت گیر می‌کرد. حالا ابتدا اکشن هدفدار
    # بررسی می‌شود.
    if action == "KICKACT" or (action == "KICK" and len(data.split("|")) > 2):
        try:
            target = int(data.split("|")[2])
        except Exception:
            target = 0
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه!", True)
            return
        if target and target in [int(x) for x in game.get("players", [])]:
            await lobby_remove_player(context, game, target, query, kicked=True)
        return

    if action == "KICK":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند اخراج کند.", True)
            return
        others = [p for p in players if p != uid]
        if not others:
            await safe_answer_query(query, "کسی برای اخراج نیست.")
            return
        rows = []
        for p in others:
            rows.append([btn(f"🦵 {name_of(p, game)}", f"L|KICK|{p}")])
        rows.append([btn("⬅️ برگشت به لابی", "L|REFRESH")])
        await safe_answer_query(query)
        await safe_edit(query, "🦵 <b>چه کسی اخراج شود؟</b>\n(دکمه را بزن)", kb(rows))
        return

    if action == "HOST":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند سرگروهی را منتقل کند.", True)
            return
        others = [p for p in players if p != uid]
        if not others:
            await safe_answer_query(query, "کسی برای انتقال نیست.")
            return
        rows = []
        for p in others:
            rows.append([btn(f"👑 {name_of(p, game)}", f"L|HOSTX|{p}")])
        rows.append([btn("⬅️ برگشت به لابی", "L|REFRESH")])
        await safe_answer_query(query)
        await safe_edit(query, "👑 <b>سرگروهی به چه کسی منتقل شود؟</b>", kb(rows))
        return

    if action == "HOSTX":
        try:
            target = int(data.split("|")[2])
        except Exception:
            target = 0
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه!", True)
            return
        if target and target in players:
            game["leader_id"] = target
            game["leader_name"] = name_of(target, game)
            touch_game(game)
            save_data()
            await safe_answer_query(query, "سرگروهی منتقل شد 👑")
            await ui_notice(context.bot, chat_id,
                            f"👑 سرگروهی به {mention_user(target, name_of(target, game))} منتقل شد!",
                            ttl=60, parse_mode=ParseMode.HTML)
            await lobby_refresh(None, context, game, query=query)
        return

    if action == "CANCEL":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند بازی را لغو کند.", True)
            return
        game["status"] = "finished"
        game["finish_reason"] = "cancelled"
        get_group(chat_id)["active_game"] = None
        save_data(force=True)
        audit("lobby_cancel", uid, chat_id)
        await safe_answer_query(query, "بازی لغو شد ❌")
        await safe_edit(query, "❌ <b>بازی لغو شد.</b>\nبرای شروع دوباره: /apex")
        return

    if action == "REFRESH":
        await safe_answer_query(query)
        await lobby_refresh(None, context, game, query=query)
        return

    if action == "START":
        if not is_leader:
            await safe_answer_query(query, "فقط سرگروه می‌تواند بازی را شروع کند.", True)
            return
        group = get_group(chat_id)
        mn = max(2, int(group.get("min_players", 2)))
        if len(players) < mn:
            await safe_answer_query(query, f"حداقل {fmt_num(mn)} نفر لازم است!", True)
            return
        await game_start(context, game, query)
        return

    if action == "NOP":
        await safe_answer_query(query)
        return

    await safe_answer_query(query)


async def lobby_remove_player(context, game: dict, uid: int, query=None, kicked: bool = False) -> None:
    players = [int(x) for x in game.get("players", [])]
    if uid not in players:
        await safe_answer_query(query, "تو داخل بازی نیستی.")
        return
    players.remove(uid)
    game["players"] = players
    game["ready"] = [int(x) for x in game.get("ready", []) if int(x) != uid]
    chat_id = int(game.get("chat_id", 0))
    label = name_of(uid, game)
    if kicked:
        await ui_notice(context.bot, chat_id, f"🦵 {mention_user(uid, label)} از بازی اخراج شد.", ttl=60, parse_mode=ParseMode.HTML)
    else:
        await ui_notice(context.bot, chat_id, f"🚪 {mention_user(uid, label)} بازی را ترک کرد.", ttl=60, parse_mode=ParseMode.HTML)
    if not players:
        game["status"] = "finished"
        game["finish_reason"] = "empty"
        get_group(chat_id)["active_game"] = None
        save_data(force=True)
        await safe_answer_query(query, "بازی به دلیل نبود بازیکن بسته شد.")
        try:
            await safe_edit(query, "🪦 بازی به دلیل خالی شدن بسته شد.")
        except Exception:
            pass
        return
    if int(game.get("leader_id", 0)) == uid:
        game["leader_id"] = players[0]
        game["leader_name"] = name_of(players[0], game)
        await ui_notice(context.bot, chat_id,
                        f"👑 سرگروه جدید: {mention_user(players[0], game['leader_name'])}",
                        ttl=60, parse_mode=ParseMode.HTML)
    touch_game(game)
    save_data()
    await safe_answer_query(query, "خارج شدی 🚪" if not kicked else "اخراج شد 🦵")
    # ۶.۳ FIX: چک قدیمی status=="lobby" هرگز صادق نبود (در لابی status="active"
    # و phase="lobby" است) — پنل بعد از خروج/اخراج هرگز تازه نمی‌شد!
    if str(game.get("phase")) == "lobby" and query is not None:
        await lobby_refresh(None, context, game, query=query)


# ================================================================
#  موتور بازی — شروع، نوبت، سوال، جواب، پاداش
# ================================================================

def current_questioner(game: dict) -> int | None:
    """پرسشگر فعلی — اول از current_questioner، اگر نبود از turn_order/turn_index محاسبه کن."""
    try:
        cq = game.get("current_questioner")
        if cq is not None:
            return int(cq)
    except Exception:
        pass
    # Fallback: محاسبه از turn_order و turn_index
    try:
        order = [int(x) for x in game.get("turn_order", [])]
        alive = [p for p in order if p in [int(x) for x in game.get("players", [])]]
        if not alive:
            return None
        idx = int(game.get("turn_index", 0) or 0)
        if idx > 0:
            # turn_index already advanced, so current is idx-1
            return alive[(idx - 1) % len(alive)]
        return None
    except Exception:
        return None


def advance_turn(game: dict) -> int | None:
    """نوبت را یکی جلو می‌برد؛ None یعنی بازی تمام شده."""
    order = [int(x) for x in game.get("turn_order", [])]
    alive = [p for p in order if p in [int(x) for x in game.get("players", [])]]
    if not alive:
        return None
    idx = int(game.get("turn_index", 0) or 0) % len(alive)
    game["turn_index"] = idx + 1
    game["turn_number"] = int(game.get("turn_number", 0)) + 1
    # هر دورِ کامل، round زیاد می‌شود (موتور گرما)
    if (int(game.get("turn_number", 0)) % max(1, len(alive))) == 0:
        game["round"] = int(game.get("round", 0)) + 1
    game["current_questioner"] = alive[idx]
    game["phase"] = "topic"
    game.pop("reply_prompt", None)
    game.pop("selected_mode", None)
    game.pop("_panel_view", None)   # (۱۱.۰) نوبت جدید = نمای فرعی قبلی باطل
    touch_game(game)
    try:
        daily_tick(game, alive[idx])
    except Exception:
        pass
    return alive[idx]


def turn_announcement(game: dict, questioner: int) -> str:
    """اعلان نوبت پرسشگری — طراحی جعبه‌ای حرفه‌ای."""
    heat_info = game_heat_advanced(game)
    heat_name = heat_info.get("name", "🟢 آرام")
    intensity = heat_info.get("intensity", "سبک و دوستانه")
    round_num = int(game.get("round", 0)) + 1
    players_count = len(game.get("players", []))
    try:
        q_user = get_user(int(questioner))
        q_level = int(q_user.get("level", 1))
        q_xp = int(q_user.get("xp", 0))
        _, q_rank_icon, _ = rank_for_xp(q_xp)
        vip = "👑" if int(q_user.get("vip_until", 0)) > now_ts() else ""
        ver = "✅" if q_user.get("verified") else ""
    except Exception:
        q_level = 1
        q_rank_icon = "🌱"
        vip = ver = ""
    adult_on = bool(get_group(int(game.get("chat_id", 0))).get("adult_mode", False))
    lines = [
        og_top("🎤"),
        og_head("🎤", "چراغ خوشه‌ای روشن شد!",
               f"نوبت پرسشگری — همه به {escape(name_of(int(questioner), game))} نگاه کنن!"),
        og_sep(),
        f"┃  👤 {mention_user(int(questioner), name_of(int(questioner), game))} 🔥{pnum(q_level)} {q_rank_icon} {vip}{ver}",
        og_row("🎯 دور", pnum(round_num)),
        og_row("👥 بازیکن", pnum(players_count)),
        f"┃  🌡 گرما {'·' * 3} {heat_name} {og_gauge(heat_info.get('level', 1))}",
        f"┃  ▸ شدت: {intensity}",
        og_row("🔞 حالت +۱۸", "روشن 🔥" if adult_on else "خاموش"),
        og_sep("◈"),
        og_section("📋", "مراحل بازی"),
        "┃  ۱) یک موضوع انتخاب کن",
        "┃  ۲) بازیکن هدف رو انتخاب کن",
        "┃  ۳) سوال خودکار میاد",
        "┃  ۴) هدف با Reply جواب میده",
        og_sep("◈"),
        "┃  🎁 پاداش: +۵ تا +۸ ایکس‌پی و سکه — کارت‌های کمیاب بونوس ویژه دارند!",
        og_close("🎤"),
    ]
    return "\n".join(lines)


def turn_markup(game: dict, viewer_uid: int) -> InlineKeyboardMarkup:
    """دکمه‌های نوبت — +۱۸ در صدر، مودهای اصلی و بیشتر."""
    q = current_questioner(game)
    if q is None:
        return kb([[btn("📊 وضعیت بازی", "G|STATUS")]])
    if int(viewer_uid) == int(q):
        off = set(topics_off())
        adult_ok = get_group(int(game["chat_id"])).get("adult_mode", False)
        rows = []
        # ردیف ۱: +۱۸ در صدر اگر فعال باشه
        if adult_ok and "adult" not in off:
            rows.append([btn("🔞 +۱۸ 🔥", "G|MODE|adult")])
        # ردیف ۲: مودهای اصلی
        main_modes = [("truth", "🕵️ اعتراف"), ("dare", "🔥 جرئت"),
                      ("flirty", "💘 فلرت"), ("drama", "😈 جنجال")]
        pair = []
        for key, label in main_modes:
            if key in off:
                continue
            pair.append(btn(label, f"G|MODE|{key}"))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)
        # ردیف موضوعات بیشتر
        rows.append([btn("📋 موضوعات بیشتر", "G|MOREMODES")])
        rows.append([btn("🎲 رد کردن نوبت", "G|SKIP"), btn("📊 امتیازها", "G|SCORES")])
        is_leader = int(viewer_uid) == int(game.get("leader_id", 0))
        if is_leader or has_permission(int(viewer_uid), "admin"):
            rows.append([btn("🏁 پایان بازی", "G|END")])
    else:
        is_leader = int(viewer_uid) == int(game.get("leader_id", 0))
        rows = [
            [btn("📊 امتیازها", "G|SCORES")],
        ]
        if is_leader or has_permission(int(viewer_uid), "admin"):
            rows.append([btn("🏁 پایان بازی", "G|END")])
    return kb(rows)


async def game_send_turn_card(context, game: dict) -> None:
    """کارت نوبت جدید را در گروه می‌فرستد."""
    q = current_questioner(game)
    if q is None:
        return
    chat_id = int(game.get("chat_id", 0))
    try:
        m = await context.bot.send_message(
            chat_id,
            turn_announcement(game, int(q)),
            parse_mode=ParseMode.HTML,
            reply_markup=turn_markup(game, int(q)),
        )
        # 🧹 تک‌پیام: کارت نوبت جدید، کارت نوبت/سوالِ حل‌شده‌ی قبلی را پاک می‌کند
        await ui_sweep_tags(context.bot, chat_id, (UI_TAG_TURN, UI_TAG_QUESTION))
        ui_retag(chat_id, m.message_id, UI_TAG_TURN)
        # کارت نوبت جدید = پنل زنده‌ی بازی (محافظت‌شده تا انتخاب موضوع/هدف)
        game["phase"] = "topic"
        game["_panel_msg_id"] = int(m.message_id)
        # ⏱ ۶.۲ — شمارنده‌ی رفرش از همین لحظه شروع شود
        panel_reset_timer(game)
    except Exception as exc:
        audit("turn_send_error", 0, chat_id, repr(exc)[:200])


async def game_start(context, game: dict, query=None) -> None:
    """شروع بازی از لابی — پیام زیبا با جعبه."""
    chat_id = int(game.get("chat_id", 0))
    players = [int(x) for x in game.get("players", [])]
    random.shuffle(players)
    game["turn_order"] = players
    game["turn_index"] = 0
    game["turn_number"] = 0
    game["round"] = 0
    game["status"] = "active"
    game["phase"] = "topic"
    game["started_at"] = now_ts()
    game["round_scores"] = {str(p): 0 for p in players}
    for p in players:
        get_user(p)["games"] = int(get_user(p).get("games", 0)) + 1
    try:
        if chat_cfg(chat_id).get("teams", True) and len(players) >= 4:
            teams_build(chat_id, players)
    except Exception:
        pass
    save_data(force=True)
    audit("game_start", int(game.get("leader_id", 0)), chat_id)
    # ساخت لیست بازیکنان
    roster_lines = []
    for i, p in enumerate(players, 1):
        roster_lines.append(f"│  {pnum(i)}. {mention_user(p, name_of(p, game))}")
    roster = "\n".join(roster_lines)
    lines = [
        ds_top("🚀"),
        "│  🚀 <b>بازی شروع شد!</b>",
        "│  <i>قهرمان‌ها وارد میدان شدن</i>",
        ds_sep(),
        f"│  ▎👥 بازیکنان (<b>{pnum(len(players))}</b> نفر)",
        roster,
        ds_sep("⋆"),
        "│  🎯 ترتیب نوبت‌ها تصادفی شد",
        "│  🌡 شروع با گرما: <b>🟢 آرام</b>",
        f"│  📚 <b>{pnum(BANKS_TOTAL)}</b> سوال در انتظار شماست",
        ds_close("🚀"),
    ]
    text = "\n".join(lines)
    try:
        if query is not None:
            await safe_answer_query(query, "بازی شروع شد! 🚀")
            await safe_edit(query, text, kb([[btn("🎤 دیدن نوبت", "G|TURN")]]))
        else:
            # 🧹 تک‌پیام: قبل از اعلام شروع، پیام‌های قبلی ربات (لابی/منو) پاک می‌شوند
            await ui_sweep_chat(context.bot, chat_id)
            # سکانس سینمایی شمارش معکوس + اعلام شروع روی همان پیام
            await cinematic(context.bot, chat_id, countdown_frames(), delay=0.9,
                            final_text=text)
    except Exception:
        pass
    nxt = advance_turn(game)
    save_data(force=True)
    if nxt is not None:
        await game_send_turn_card(context, game)


def game_home_text(game: dict) -> str:
    """وضعیت بازی — طراحی جعبه‌ای حرفه‌ای."""
    q = current_questioner(game)
    heat_info = game_heat_advanced(game)
    heat_name = heat_info.get("name", "🟢 آرام")
    intensity = heat_info.get("intensity", "سبک و دوستانه")
    scores = game.get("round_scores", {})
    players = [int(x) for x in game.get("players", [])]
    top = sorted(players, key=lambda p: -int(scores.get(str(p), 0)))[:3]
    medals = ["🥇", "🥈", "🥉"]
    board_lines = []
    for i, p in enumerate(top):
        if int(scores.get(str(p), 0)) > 0:
            board_lines.append(podium_line(medals[i], mention_user(p, name_of(p, game)), scores.get(str(p), 0)))
    board = "\n".join(board_lines) if board_lines else "│  هنوز امتیازی ثبت نشده — اولین قهرمان کی می‌شه؟"
    started = int(game.get("started_at", 0))
    duration_min = (now_ts() - started) // 60 if started else 0
    game_stats = game.get("_question_stats", {})
    total_q = int(game_stats.get("total", 0))
    total_penalties = int(game_stats.get("penalties", 0))
    adult_on = bool(get_group(int(game.get("chat_id", 0))).get("adult_mode", False))
    theme_info = ""
    try:
        theme = theme_night_get(int(game["chat_id"]))
        if theme:
            theme_info = f"\n│  🌟 تم شب: <b>{theme['name']}</b>"
    except Exception:
        pass
    q_display = mention_user(int(q), name_of(int(q), game)) if q else "—"
    lines = [
        ds_top(),
        "│  🎮 <b>وضعیت بازی</b>",
        "│  <i>مرکز کنترل میدان نبرد</i>",
        ds_sep(),
        f"│  🎤 پرسشگر: {q_display}",
        ds_row("🔄 نوبت", pnum(int(game.get('turn_number', 0)) + 1)),
        ds_row("🎯 دور", pnum(int(game.get('round', 0)) + 1)),
        ds_row("🌡 گرما", f"{heat_name} — {intensity}"),
        ds_row("⏱ مدت", f"{pnum(duration_min)} دقیقه"),
        ds_row("📊 سوال", pnum(total_q)),
        ds_row("⚖️ حکم", pnum(total_penalties)),
        ds_row("🔞 +۱۸", "روشن 🔥" if adult_on else "خاموش"),
    ]
    if theme_info:
        lines.append(theme_info.strip())
    lines += [
        ds_sep("⋆"),
        "│  ▎🏆 <b>سکوی برترین‌ها</b>",
        board,
        ds_close(),
    ]
    return "\n".join(lines)


def game_home_markup(game: dict, viewer_uid: int) -> InlineKeyboardMarkup:
    return turn_markup(game, viewer_uid)


async def game_show_panel(update: Update, context: ContextTypes.DEFAULT_TYPE, game: dict, uid: int) -> None:
    """نمایش پنل بازی — اگر از دکمه صدا زده شده، پیام را ویرایش می‌کند.

    ۶.۳: نمای «آگاه از فاز» (همان موتور رفرش زنده) — در فاز لابی، نمای لابی
    با دکمه‌های پیوستن/آماده؛ در فاز موضوع، کارت نوبت با دکمه‌های موضوع و...
    دیگر هیچ فازی دکمه‌های خود را از دست نمی‌دهد.
    """
    chat_id = int(game.get("chat_id", 0))
    try:
        text, markup = _panel_views_for(game)
    except Exception:
        text, markup = game_home_text(game), game_home_markup(game, uid)
    if update.callback_query:
        await safe_edit(update.callback_query, text, markup)
        game["_panel_msg_id"] = int(update.callback_query.message.message_id)
        panel_reset_timer(game)
    else:
        try:
            m = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
            game["_panel_msg_id"] = int(m.message_id)
            panel_reset_timer(game)
        except Exception:
            pass


async def game_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None or query.message is None:
        return
    data = str(query.data or "")
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    chat = query.message.chat
    chat_id = int(chat.id)
    game = active_game(chat_id)
    if game is None:
        await safe_answer_query(query, "بازی فعالی در این گروه نیست. با /apex بساز. 🔄")
        return

    if action == "TURN" or action == "STATUS":
        await safe_answer_query(query)
        panel_subview_clear(game)   # (۱۱.۰) درخواست کارت نوبت = خروج از نمای فرعی
        panel_reset_timer(game)
        q = current_questioner(game)
        if q is None:
            await safe_edit(query, game_home_text(game), game_home_markup(game, uid))
            return
        await safe_edit(query, turn_announcement(game, int(q)), turn_markup(game, uid))
        return

    if action == "MOREMODES":
        # (۱۱.۰) نمای «موضوعات بیشتر» — دیگر هرگز با رفرش بلعیده نمی‌شود:
        # نما داخل بازی ثبت می‌شود و موتور نبض همان را رندر می‌کند.
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "فقط پرسشگر فعلی می‌تواند موضوع انتخاب کند.", True)
            return
        await safe_answer_query(query)
        panel_subview_set(game, "moremodes")
        panel_reset_timer(game)
        text, markup = moremodes_view(game)
        await safe_edit(query, text, markup)
        # (۱۱.۰) هش همین رندر ثبت شود تا موتور بعد از مهلت، ویرایش تکراری نزند
        try:
            game["_panel_hash"] = _panel_hash(text, markup)
        except Exception:
            pass
        return

    if action == "MODE":
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "فقط پرسشگر فعلی می‌تواند موضوع را انتخاب کند.", True)
            return
        mode = parts[2] if len(parts) > 2 else ""
        if mode not in MODE_LABELS:
            await safe_answer_query(query, "موضوع نامعتبر است.")
            return
        if mode == "adult":
            if not get_group(chat_id).get("adult_mode", False):
                await safe_answer_query(query, "حالت ۱۸+ در این گروه فعال نیست.", True)
                return
        game["selected_mode"] = mode
        game["phase"] = "target"
        panel_subview_clear(game)   # (۱۱.۰) انتخاب موضوع = خروج از نمای فرعی
        panel_reset_timer(game)
        touch_game(game)
        save_data()
        await safe_answer_query(query, f"{MODE_LABELS[mode]} انتخاب شد")
        await game_show_targets(query, game, mode)
        return

    if action == "SPIN":
        # 🍾 چرخش شیشه‌ی سرنوشت — انتخاب هدف تصادفی با انیمیشن سینمایی
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "فقط پرسشگر فعلی می‌تواند شیشه را بچرخاند.", True)
            return
        mode = parts[2] if len(parts) > 2 else str(game.get("selected_mode") or "truth")
        if mode not in MODE_LABELS:
            mode = "truth"
        players = [int(x) for x in game.get("players", [])]
        others = [p for p in players if p != int(q) and not punishment_blocks_turn(p)]
        others = [p for p in others if not (mode == "adult" and not adult_allowed(p))]
        if not others:
            await safe_answer_query(query, "هیچ هدفی برای چرخش باقی نمانده! 😅", True)
            return
        target = random.choice(others)
        await safe_answer_query(query, "🍾 شیشه چرخید!")
        try:
            await safe_delete(query.message)
        except Exception:
            pass
        await cinematic(context.bot, chat_id, spin_frames(escape(name_of(target, game))), delay=1.0)
        await game_ask_question(context, game, int(q), target, mode, None)
        return

    if action == "TARGET":
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "فقط پرسشگر فعلی می‌تواند هدف را انتخاب کند.", True)
            return
        try:
            target = int(parts[2])
        except Exception:
            target = 0
        if not target or target not in [int(x) for x in game.get("players", [])]:
            await safe_answer_query(query, "این بازیکن دیگر در بازی نیست.")
            return
        mode = str(game.get("selected_mode") or "truth")
        # محافظت بزرگسال
        if mode == "adult" and not adult_allowed(target):
            await safe_answer_query(query, "هدف، سن خود را تایید نکرده است! 🛡", True)
            return
        # قفل مجازات
        if punishment_blocks_turn(target):
            await safe_answer_query(query, "⚖️ این بازیکن در حال انجام مجازات است!", True)
            return
        await game_ask_question(context, game, int(q), target, mode, query)
        return

    if action == "SCORES":
        await safe_answer_query(query)
        await game_show_scores(query, game)
        return

    if action == "HELP":
        await safe_answer_query(query)
        await safe_edit(query,
            f"{ds_top()}\n"
            f"│  ℹ️ <b>راهنمای بازی</b>\n"
            f"│  <i>قانون‌های میدان — خوندنشونا لازمه!</i>\n"
            f"{ds_sep()}\n"
            f"│  ۱) پرسشگر یک موضوع انتخاب می‌کنه\n"
            f"│  ۲) سپس یک بازیکن هدف انتخاب می‌کنه\n"
            f"│  ۳) ربات سوال رو می‌فرسته\n"
            f"│  ۴) هدف با Reply به سوال جواب می‌ده\n"
            f"│  ۵) نوبت بعدی شروع می‌شه\n"
            f"{ds_sep('⋆')}\n"
            f"│  🌶 هرچه بازی جلوتر بره، سوال‌ها داغ‌تر می‌شن\n"
            f"│  🍾 با «چرخش شیشه» بذار شانس هدف رو انتخاب کنه\n"
            f"│  ☠️ گاهی به‌جای سوال، حکم صادر می‌شه\n"
            f"│  🎁 جواب دادن: +۵ تا +۸ ایکس‌پی و سکه",
            kb([[btn("⬅️ بازگشت", "G|TURN")]]))
        return

    if action == "SKIP":
        q = current_questioner(game)
        if q is None or int(q) != uid:
            await safe_answer_query(query, "👑 فقط پرسشگر فعلی می‌تواند نوبت را رد کند.", True)
            return
        game.pop("reply_prompt", None)
        nxt = advance_turn(game)
        panel_reset_timer(game)
        save_data(force=True)
        await safe_answer_query(query, "نوبت رد شد 🎲")
        if nxt is not None:
            await safe_edit(query, turn_announcement(game, int(nxt)), turn_markup(game, int(nxt)))
        return

    if action == "END":
        q = current_questioner(game)
        is_leader = uid == int(game.get("leader_id", 0))
        if not (is_leader or has_permission(int(uid), "admin")):
            await safe_answer_query(query, "فقط سرگروه می‌تواند بازی را تمام کند.", True)
            return
        await end_game_flow(context, game, query, reason="manual")
        return

    await safe_answer_query(query)


def targets_view(game: dict) -> tuple:
    """نمای «انتخاب هدف» — سازنده‌ی متن و دکمه‌ها (۶.۲: برای نمایش و رفرش خودکار)."""
    mode = str(game.get("selected_mode") or "truth")
    if mode not in MODE_LABELS:
        mode = "truth"
    q = current_questioner(game)
    players = [int(x) for x in game.get("players", [])]
    others = [p for p in players if p != q]
    # حذف بازیکنان قفل‌شده توسط مجازات از لیست هدف
    others = [p for p in others if not punishment_blocks_turn(p)]
    # دکمه‌های دوستونه بازیکنان
    rows = []
    pair = []
    for p in others:
        icon = gender_icon(p)
        try:
            pu = get_user(int(p))
            p_level = int(pu.get("level", 1))
            label = f"{icon} {name_of(p, game)} · 🔥{pnum(p_level)}"
        except Exception:
            label = f"{icon} {name_of(p, game)}"
        pair.append(btn(label, f"G|TARGET|{p}"))
        if len(pair) == 2:
            rows.append(pair)
            pair = []
    if pair:
        rows.append(pair)
    lines = [
        ds_top(),
        f"│  {MODE_LABELS.get(mode, mode)} — <b>انتخاب هدف</b>",
        "│  <i>حالا نوبت انتخاب قربانیه!</i>",
        ds_sep(),
        "│  😈 پرسشگر عزیز، روی بازیکن مورد نظرت بزن",
        "│  یا شیشه‌ی سرنوشت رو بچرخون و بذار بخت تصمیم بگیره!",
        ds_close(),
    ]
    rows.append([btn("🍾 چرخش شیشه (تصادفی)", f"G|SPIN|{mode}")])
    rows.append([btn("⬅️ بازگشت به موضوع‌ها", "G|TURN")])
    return "\n".join(lines), kb(rows)


async def game_show_targets(query, game: dict, mode: str) -> None:
    """نمایش لیست اهداف — کارت بازیکنان + چرخش شیشه‌ی سرنوشت."""
    text, markup = targets_view(game)
    await safe_edit(query, text, markup)


# ================================================================
#  (۱۱.۰) نمای‌های فرعی پنل گروه — موضوعات بیشتر / امتیازها
#  ریشه‌ی باگ «دکمه‌ی موضوعات بیشتر کار نمی‌کند» همین‌جا بود: موتور رفرش
#  هیچ اطلاعی از نمای فرعی نداشت و ظرف ~۱ ثانیه کارت نوبت را روی آن
#  بازنویسی می‌کرد. حالا نما داخل خودِ بازی ثبت می‌شود و موتور هم همان
#  را رندر می‌کند — تا وقتی کاربر خودش با دکمه از آن خارج شود.
# ================================================================
MODE_SUBVIEW_TTL = 120            # عمر نمای فرعی (ثانیه) — بعدش خودکار برمی‌گردد
MODE_MAIN_KEYS = {"truth", "dare", "flirty", "drama"}   # مودهای کارت اصلی
MODE_CATEGORIES = [                # دسته‌بندی زیبای «موضوعات بیشتر»
    ("🧠", "ذهن و خیال", ("mind", "wouldyou", "dream", "future")),
    ("💔", "احساسات", ("relation", "regret", "memory")),
    ("🤫", "رازها و جنجال", ("secret", "scenario", "cringe")),
]


def panel_subview_set(game: dict, view_id: str) -> None:
    """ثبت نمای فرعی فعال — موتور نبض از این پس همان را رندر می‌کند (۱۱.۰)."""
    try:
        game["_panel_view"] = {
            "id": str(view_id),
            "ts": time.time(),
            "phase": str(game.get("phase", "")),
        }
    except Exception:
        pass


def panel_subview_clear(game: dict) -> None:
    """خروج از نمای فرعی — بازگشت به نمای فاز."""
    try:
        game.pop("_panel_view", None)
    except Exception:
        pass


def panel_subview_active(game: dict) -> str | None:
    """نمای فرعیِ معتبر را برمی‌گرداند (با انقضا و بطلان خودکار)."""
    try:
        sv = game.get("_panel_view")
        if not isinstance(sv, dict):
            return None
        vid = str(sv.get("id", ""))
        if vid not in ("moremodes", "scores"):
            game.pop("_panel_view", None)
            return None
        if time.time() - float(sv.get("ts", 0) or 0) > MODE_SUBVIEW_TTL:
            game.pop("_panel_view", None)
            return None
        # «موضوعات بیشتر» فقط در فاز انتخاب موضوع معنی دارد
        if vid == "moremodes" and str(game.get("phase", "")) != str(sv.get("phase", "topic")):
            game.pop("_panel_view", None)
            return None
        return vid
    except Exception:
        return None


def moremodes_view(game: dict) -> tuple:
    """📋 «موضوعات بیشتر» نسل ۱۱ — دسته‌بندی + تعداد سوال هر موضوع + رنگ."""
    off = set(topics_off())
    adult_ok = bool(get_group(int(game.get("chat_id", 0))).get("adult_mode", False))
    lines = [
        ds_top("📋"),
        "│  📋 <b>موضوعات بیشتر</b>",
        "│  <i>گنجینه‌ی کامل موضوع‌های ویژه</i>",
        ds_sep(),
    ]
    rows: list = []
    # — 🔞 موضوع ویژه +۱۸ (اگر گروه روشن کرده باشد) —
    if "adult" not in off:
        if adult_ok:
            cnt = len(BANKS.get("adult", []))
            lines.append(f"│  🔞 <b>موضوع ویژه</b> — {pnum(cnt)} سوال داغ")
            rows.append([btn(f"🔞 +۱۸ · {pnum(cnt)} سوال", "G|MODE|adult", "danger")])
        else:
            lines.append("│  🔞 +۱۸: خاموش (سرگروه از لابی روشنش می‌کند)")
    # — دسته‌های سه‌گانه —
    total_shown = 0
    for icon, cat, keys in MODE_CATEGORIES:
        cat_modes = []
        for key in keys:
            if key in off or key in MODE_MAIN_KEYS:
                continue
            cnt = len(BANKS.get(key, []))
            if cnt > 0:
                cat_modes.append((key, cnt))
        if not cat_modes:
            continue
        total_shown += len(cat_modes)
        lines.append(f"│  {icon} <b>{cat}</b> · {pnum(len(cat_modes))} موضوع")
        pair = []
        for key, cnt in cat_modes:
            pair.append(btn(f"{MODE_LABELS.get(key, key)} · {pnum(cnt)}", f"G|MODE|{key}", "primary"))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)
    if total_shown == 0 and "adult" not in off and not adult_ok:
        lines.append("│  همه‌ی موضوع‌های ویژه خاموش شده‌اند.")
    lines += [
        ds_sep("⋆"),
        "│  💡 هر موضوع، بانک سوال مخصوص خودش را دارد",
        ds_close("📋"),
    ]
    rows.append([btn("⬅️ موضوع‌های اصلی", "G|TURN")])
    rows.append([btn("🎲 رد کردن نوبت", "G|SKIP"), btn("📊 امتیازها", "G|SCORES")])
    return "\n".join(lines), kb(rows)


def scores_view(game: dict) -> tuple:
    """🏆 «امتیازها» نسل ۱۱ — سکوی مدال + نوار امتیاز هر بازیکن."""
    scores = game.get("round_scores", {})
    players = [int(x) for x in game.get("players", [])]
    entries = sorted(((int(scores.get(str(p), 0)), p) for p in players),
                     key=lambda x: (-x[0], name_of(x[1], game)))
    max_score = max((s for s, _ in entries), default=0)
    heat_info = game_heat_advanced(game)
    round_num = int(game.get("round", 0)) + 1
    started = int(game.get("started_at", 0))
    duration_min = (now_ts() - started) // 60 if started else 0
    total_q = int(game.get("_question_stats", {}).get("total", 0))
    lines = [
        ds_top("🏆"),
        "│  🏆 <b>امتیازهای بازی</b>",
        "│  <i>سکوی قهرمانان — زنده و لحظه‌ای</i>",
        ds_sep(),
        ds_row("🎯 دور", pnum(round_num)),
        ds_row("🌡 گرما", heat_info.get("name", "🟢 آرام")),
        ds_row("⏱ مدت", f"{pnum(duration_min)} دقیقه"),
        ds_row("📊 سوالات", pnum(total_q)),
        ds_sep("⋆"),
    ]
    medals = ["🥇", "🥈", "🥉"]
    if not entries:
        lines.append("│  هنوز امتیازی ثبت نشده — اولین قهرمان کی می‌شه؟")
    for i, (score, p) in enumerate(entries, 1):
        prefix = medals[i - 1] if i <= 3 else f"<b>{pnum(i)}.</b>"
        try:
            level = int(get_user(p).get("level", 1))
        except Exception:
            level = 1
        bar = pbar(score, max(1, max_score), 10, pct=False) if max_score > 0 else "░" * 10
        lines.append(f"│  {prefix} {mention_user(p, name_of(p, game))} 🔥{pnum(level)}")
        lines.append(f"│  ▸ {bar} ⭐ {pnum(score)}")
    lines.append(ds_close("🏆"))
    rows = [
        [btn("↻ تازه‌سازی", "G|SCORES"), btn("🎤 کارت نوبت", "G|TURN")],
    ]
    return "\n".join(lines), kb(rows)


async def game_ask_question(context, game: dict, questioner: int, target: int, mode: str, query=None) -> None:
    chat_id = int(game.get("chat_id", 0))
    # گاهی به‌جای سوال، حکم یا رویداد یا باس‌راند صادر می‌شود
    special = None
    settings = game.get("settings", {})
    roll = random.random()
    if roll < 0.10 and settings.get("allow_random_events", True):
        special = "event"
    elif roll < 0.16 and settings.get("allow_boss", True):
        special = "boss"
    elif roll < 0.26 and mode in ("dare", "truth") and settings.get("allow_duel", True):
        special = "penalty"

    if special == "penalty":
        await game_show_penalty(context, game, target, questioner, query)
        return
    if special == "boss":
        await game_boss_round(context, game, questioner, query)
        return
    if special == "event":
        await game_random_event(context, game, questioner, query)
        return

    question = pick_question(game, mode, target)
    heat_info = game_heat_advanced(game)
    heat_name = heat_info.get("name", "🟢 آرام")
    heat_level = heat_info.get("level", 1)
    round_num = int(game.get("round", 0)) + 1
    # اطلاعات پرسشگر و هدف
    try:
        q_user = get_user(int(questioner))
        q_level = int(q_user.get("level", 1))
        q_rank_name, q_rank_icon, _ = rank_for_xp(int(q_user.get("xp", 0)))
    except Exception:
        q_level = 1
        _, q_rank_icon = "تازه‌کار", "🌱"
    try:
        t_user = get_user(int(target))
        t_level = int(t_user.get("level", 1))
        t_rank_name, t_rank_icon, _ = rank_for_xp(int(t_user.get("xp", 0)))
    except Exception:
        t_level = 1
        _, t_rank_icon = "تازه‌کار", "🌱"
    # --- سیستم کیفیتی کارت (اومگا) — صرفاً بصری، بدون تغییر سوال ---
    rarity = question_rarity(question)
    rare = rarity["key"] not in ("common",)
    pipe = "┃" if rare else "│"
    sep = og_sep("◈") if rare else ds_sep()
    close = og_close(rarity["jewel"]) if rare else ds_close(rarity["jewel"])
    lines = [
        og_top(rarity["jewel"]) if rare else ds_top(rarity["jewel"]),
        f"{pipe}  {MODE_LABELS.get(mode, mode)} — <b>کارت سرنوشت</b>  {rarity['icon']}",
        f"{pipe}  کیفیت کارت: <b>{rarity['name']}</b>" + ("  ✵" if rare else ""),
        sep,
        f"{pipe}  ▌<b>{escape(question)}</b>",
        sep,
        f"{pipe}  🎤 {mention_user(questioner, name_of(questioner, game))} 🔥{pnum(q_level)} {q_rank_icon}",
        f"{pipe}  🎯 {mention_user(target, name_of(target, game))} 🔥{pnum(t_level)} {t_rank_icon}",
        f"{pipe}  🌡 {heat_name} {og_gauge(heat_level)} · 🎯 دور {pnum(round_num)}",
        sep,
        f"{pipe}  ✍️ {mention_user(target, name_of(target, game))} با <b>Reply به همین پیام</b> جواب بده!",
        f"{pipe}  🎁 پاداش: +۵ تا +۸ ایکس‌پی و سکه"
        + (f" ⚡بونوس کیفی: +{pnum(rarity['bonus'])}" if rarity.get("bonus") else ""),
        close,
    ]
    text = "\n".join(lines)
    footer = ads_footer(chat_id, "question")
    if footer:
        text += "\n\n" + footer
    try:
        # 🚩 نسخه ۶ — دکمه‌ی گزارش روی کارت سوال برای همه‌ی اعضا
        m = await context.bot.send_message(
            chat_id, text,
            parse_mode=ParseMode.HTML,
            reply_markup=kb([[btn("🚩 گزارش این سوال", "QG|REPORT")]]),
        )
        game["phase"] = "question"
        # ⏱ ۶.۲ — نمای «در انتظار پاسخ» بلافاصله روی پنل بیاید
        panel_reset_timer(game)
        # 🧹 تک‌پیام: کارت سوال تا وقتی Reply نخورده محافظت می‌شود
        ui_retag(chat_id, m.message_id, UI_TAG_QUESTION)
        game["reply_prompt"] = {
            "message_id": m.message_id,
            "questioner_uid": int(questioner),
            "target_uid": int(target),
            "mode": mode,
            "question_text": str(question),
            "expires": time.time() + int(settings.get("penalty_deadline", 300) or 300) + 600,
            "responders": [],
            "sent_ts": time.time(),
            "heat_level": heat_level,
        }
        # آمار موضوع برای پروفایل
        try:
            st = get_user(target).setdefault("stats", {})
            if mode in st:
                st[mode] = int(st.get(mode, 0)) + 1
        except Exception:
            pass
        # ثبت در آمار بازی
        try:
            game_stats = game.setdefault("_question_stats", {})
            game_stats[mode] = int(game_stats.get(mode, 0)) + 1
            game_stats["total"] = int(game_stats.get("total", 0)) + 1
        except Exception:
            pass
        touch_game(game)
        save_data(force=True)
        if query is not None:
            await safe_answer_query(query)
            try:
                await safe_delete(query.message)
            except Exception:
                pass
    except Exception as exc:
        audit("question_send_error", questioner, chat_id, repr(exc)[:200])


async def game_show_penalty(context, game: dict, target: int, questioner: int, query=None) -> None:
    chat_id = int(game.get("chat_id", 0))
    penalty = pick_penalty(game)
    settings = game.get("settings", {})
    deadline = int(settings.get("penalty_deadline", 300) or 300)
    heat_info = game_heat_advanced(game)
    heat_name = heat_info.get("name", "🟢 آرام")
    # اطلاعات محکوم
    try:
        t_user = get_user(int(target))
        t_level = int(t_user.get("level", 1))
        t_rank_name, t_rank_icon, _ = rank_for_xp(int(t_user.get("xp", 0)))
    except Exception:
        t_level = 1
        _, t_rank_icon = "تازه‌کار", "🌱"
    round_num = int(game.get("round", 0)) + 1
    lines = [
        ds_top("☠"),
        "│  ⚖️ <b>دادگاه صادر کرد!</b>",
        "│  <i>حکم اجرایی شد — راه فراری نیست</i>",
        ds_sep(),
        f"│  🎯 محکوم: {mention_user(target, name_of(target, game))} 🔥{pnum(t_level)} {t_rank_icon}",
        f"│  🎤 صادرکننده: {mention_user(questioner, name_of(questioner, game))}",
        ds_row("🌡 گرما", heat_name),
        ds_row("🎯 دور", pnum(round_num)),
        ds_sep("⋆"),
        f"│  ▌⚖️ حکم: <b>{escape(penalty)}</b>",
        ds_sep(),
        ds_row("⏳ مهلت", f"{pnum(deadline // 60)} دقیقه"),
        "│  ✅ بعد از انجام، با <b>Reply به همین پیام</b> تأیید کن",
        "│  🎁 پاداش: +۴ ایکس‌پی و +۲ سکه",
        ds_close("☠"),
    ]
    text = "\n".join(lines)
    footer = ads_footer(chat_id, "question")
    if footer:
        text += "\n\n" + footer
    try:
        # 🚩 نسخه ۶ — دکمه‌ی گزارش روی کارت حکم برای همه‌ی اعضا
        m = await context.bot.send_message(
            chat_id, text,
            parse_mode=ParseMode.HTML,
            reply_markup=kb([[btn("🚩 گزارش این حکم", "QG|REPORT")]]),
        )
        game["phase"] = "question"
        # ⏱ ۶.۲ — شمارنده‌ی رفرش از همین لحظه شروع شود
        panel_reset_timer(game)
        # 🧹 تک‌پیام: کارت حکم تا وقتی Reply نخورده محافظت می‌شود
        ui_retag(chat_id, m.message_id, UI_TAG_QUESTION)
        game["pending_penalties"][str(target)] = {
            "text": penalty,
            "ts": now_ts(),
            "deadline": deadline,
            "done": False,
            "skipped": False,
            "source": "game",
        }
        game["reply_prompt"] = {
            "message_id": m.message_id,
            "questioner_uid": int(questioner),
            "target_uid": int(target),
            "mode": "penalty",
            "kind": "penalty",
            "question_text": str(penalty),
            "expires": time.time() + deadline + 300,
            "responders": [],
            "sent_ts": time.time(),
        }
        # ثبت آمار مجازات
        try:
            game_stats = game.setdefault("_question_stats", {})
            game_stats["penalties"] = int(game_stats.get("penalties", 0)) + 1
        except Exception:
            pass
        touch_game(game)
        save_data(force=True)
        if query is not None:
            await safe_answer_query(query)
            try:
                await safe_delete(query.message)
            except Exception:
                pass
    except Exception as exc:
        audit("penalty_send_error", questioner, chat_id, repr(exc)[:200])


async def game_boss_round(context, game: dict, questioner: int, query=None) -> None:
    """Boss Round — چالش ویژه برای همه‌ی بازیکنان. بعد از اجرا، نوبت بعدی."""
    chat_id = int(game.get("chat_id", 0))
    challenge = random.choice(BOSS_CHALLENGES)
    await safe_answer_query(query, "👑 دور باس!")
    try:
        await context.bot.send_message(
            chat_id,
            f"{ds_top('👑')}\n"
            f"│  👑 <b>دور باس — Boss Round</b>\n"
            f"│  <i>چالش ویژه برای همه‌ی بازیکنان!</i>\n"
            f"{ds_sep()}\n"
            f"│  ▌<b>{escape(challenge)}</b>\n"
            f"{ds_sep('⋆')}\n"
            f"│  🏃 اولین نفری که چالش رو انجام بده پاداش می‌گیره!\n"
            f"│  💡 با Reply به همین پیام، انجام چالش رو ثبت کن.\n"
            f"{ds_close('👑')}",
            parse_mode=ParseMode.HTML,
        )
        for p in [int(x) for x in game.get("players", [])]:
            get_user(p)["boss"] = int(get_user(p).get("boss", 0)) + 1
        # ثبت آمار
        try:
            game_stats = game.setdefault("_question_stats", {})
            game_stats["boss_rounds"] = int(game_stats.get("boss_rounds", 0)) + 1
        except Exception:
            pass
        touch_game(game)
        save_data()
    except Exception:
        pass
    # پیشروی نوبت بعد از Boss Round
    game.pop("reply_prompt", None)
    nxt = advance_turn(game)
    save_data(force=True)
    if nxt is not None:
        await game_send_turn_card(context, game)


async def game_random_event(context, game: dict, questioner: int, query=None) -> None:
    """رویداد تصادفی — بعد از اجرا، نوبت بعدی."""
    chat_id = int(game.get("chat_id", 0))
    title, desc = random.choice(RANDOM_EVENTS)
    players = [int(x) for x in game.get("players", [])]
    await safe_answer_query(query, "✨ رویداد ویژه!")
    try:
        await context.bot.send_message(
            chat_id,
            f"{ds_top('✨')}\n"
            f"│  ✨ <b>رویداد ویژه فعال شد!</b>\n"
            f"│  <i>{escape(title)}</i>\n"
            f"{ds_sep()}\n"
            f"│  ▌{escape(desc)}\n"
            f"{ds_close('✨')}",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass
    # اجرای افکت رویداد
    try:
        if title.startswith("💰") and players:
            for p in random.sample(players, k=min(3, len(players))):
                add_coins(p, 3, name_of(p, game))
                try:
                    await context.bot.send_message(
                        chat_id,
                        f"💰 {mention_user(p, name_of(p, game))} +۳ سکه گرفت!",
                        parse_mode=ParseMode.HTML,
                    )
                except Exception:
                    pass
        elif title.startswith("🛡") and players:
            lucky = random.choice(players)
            grant_item(lucky, "shield", 1)
            try:
                await context.bot.send_message(
                    chat_id,
                    f"🛡 {mention_user(lucky, name_of(lucky, game))} یک سپر دریافت کرد!",
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
        elif title.startswith("✨") and players:
            # دو برابر XP برای نوبت بعدی
            game.setdefault("settings", {})["_double_xp_next"] = True
        elif title.startswith("🔥") and players:
            # نوبت بعدی به حالت سرعت تبدیل می‌شود
            game["_speed_round_next"] = True
        elif title.startswith("🎲") and players:
            # حالت بازی تصادفی برای نوبت بعدی
            game["_random_mode_next"] = True
    except Exception:
        pass
    # ثبت آمار
    try:
        game_stats = game.setdefault("_question_stats", {})
        game_stats["random_events"] = int(game_stats.get("random_events", 0)) + 1
    except Exception:
        pass
    touch_game(game)
    save_data()
    # پیشروی نوبت بعد از رویداد
    game.pop("reply_prompt", None)
    nxt = advance_turn(game)
    save_data(force=True)
    if nxt is not None:
        await game_send_turn_card(context, game)


REPLY_REWARDS = {"truth": (6, 2), "dare": (7, 3), "mind": (5, 2), "scenario": (6, 2),
                 "flirty": (7, 2), "adult": (8, 3)}


def reward_player(game: dict, uid: int, xp: int, coins: int, win: bool = False, loss: bool = False, reason: str = "") -> None:
    """پاداش مقاوم‌شده: همیشه round_scores موجود، همیشه ذخیره امن.
    نسخه‌ی بهبودیافته: پاداش ویژه برای VIP، ثبت آمار غنی، اعلان خودکار.
    """
    try:
        if isinstance(game, dict):
            game.setdefault("round_scores", {})
    except Exception:
        pass
    try:
        settings = game.get("settings", {}) if isinstance(game, dict) else {}
        xmult = max(1, int(settings.get("xp_multiplier", 1) or 1))
        cmult = max(1, int(settings.get("coins_multiplier", 1) or 1))
    except Exception:
        xmult, cmult = 1, 1
    # پاداش ویژه برای VIP (۱۰٪ بیشتر)
    try:
        if is_vip(int(uid)):
            xp = int(xp) + max(1, int(xp) // 10)
            coins = int(coins) + max(1, int(coins) // 10)
    except Exception:
        pass
    # پاداش استریک روزانه (۵٪ بیشتر برای هر روز استریک، حداکثر ۵۰٪)
    try:
        u = get_user(uid)
        streak = int(u.get("daily_streak", 0))
        if streak > 0:
            bonus_pct = min(50, streak * 5)
            xp = int(xp) + (int(xp) * bonus_pct // 100)
            coins = int(coins) + (int(coins) * bonus_pct // 100)
    except Exception:
        pass
    add_xp(uid, int(xp), name_of(uid, game), xmult)
    add_coins(uid, int(coins), name_of(uid, game), cmult)
    if win:
        u = get_user(uid)
        u["wins"] = int(u.get("wins", 0)) + 1
        u["streak"] = int(u.get("streak", 0)) + 1
        u["best_streak"] = max(int(u.get("best_streak", 0)), int(u.get("streak", 0)))
        check_achievements(uid)
        # بررسی Milestone
        try:
            check_milestones(int(uid))
        except Exception:
            pass
        # ثبت آمار فصل
        try:
            season_bump(int(uid), xp=int(xp), wins=1, games=1)
        except Exception:
            pass
        # Quest progress
        try:
            bump_quest_progress(int(uid), "wins", 1)
            bump_quest_progress(int(uid), "games", 1)
        except Exception:
            pass
    if loss:
        u = get_user(uid)
        u["losses"] = int(u.get("losses", 0)) + 1
        u["streak"] = 0
        # ثبت آمار فصل
        try:
            season_bump(int(uid), xp=int(xp), wins=0, games=1)
        except Exception:
            pass
        # Quest progress
        try:
            bump_quest_progress(int(uid), "games", 1)
        except Exception:
            pass
    try:
        if isinstance(game, dict):
            scores = game.setdefault("round_scores", {})
            scores[str(uid)] = int(scores.get(str(uid), 0)) + int(xp)
    except Exception:
        pass
    # ثبت در stats_ext (آمار غنی)
    try:
        u = get_user(uid)
        ext = u.setdefault("stats_ext", {})
        ext["total_xp_earned"] = int(ext.get("total_xp_earned", 0)) + int(xp)
        ext["total_coins_earned"] = int(ext.get("total_coins_earned", 0)) + int(coins)
        if not ext.get("first_game_at"):
            ext["first_game_at"] = now_ts()
        # ثبت مود بازی‌شده
        modes = ext.setdefault("modes_played", {})
        mode_key = str(game.get("selected_mode", "unknown")) if isinstance(game, dict) else "unknown"
        modes[mode_key] = int(modes.get(mode_key, 0)) + 1
        # ثبت گروه بازی‌شده
        groups_played = ext.setdefault("groups_played_in", [])
        if isinstance(game, dict):
            chat_id = int(game.get("chat_id", 0))
            if chat_id and chat_id not in groups_played:
                groups_played.append(chat_id)
                if len(groups_played) > 20:
                    ext["groups_played_in"] = groups_played[-20:]
    except Exception:
        pass


async def handle_game_reply(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """موتور پاسخ: جواب‌های Reply شده به سوال/حکم را می‌خواند."""
    msg = update.message
    if not msg or not msg.reply_to_message or not msg.text:
        return False
    chat = update.effective_chat
    if chat is None or chat.type not in ("group", "supergroup"):
        return False
    game = active_game(int(chat.id))
    if not game or str(game.get("status")) != "active":
        return False
    prompt = game.get("reply_prompt")
    if not isinstance(prompt, dict):
        return False
    if int(prompt.get("message_id", -1)) != int(msg.reply_to_message.message_id):
        return False
    if time.time() > float(prompt.get("expires", 0)):
        game.pop("reply_prompt", None)
        save_data(force=True)
        try:
            await msg.reply_text("⌛ این نوبت تمام شده است؛ نوبت بعدی را از منوی بازی دنبال کنید.")
        except Exception:
            pass
        return True
    # 🚩 نسخه ۶ — گزارش کارت با Reply: متن شروع‌شده با «گزارش» به‌عنوان گزارش ثبت می‌شود
    rtext = str(msg.text or "").strip()
    if rtext.startswith(("گزارش", "/گزارش")) or rtext.startswith("🚩"):
        rep_uid = int(update.effective_user.id)
        qtext = str(prompt.get("question_text") or "(کارت فعال)")
        dup = any(
            isinstance(r, dict) and int(r.get("uid", 0)) == rep_uid
            and str(r.get("question", "")) == qtext
            and str(r.get("status", "")) == "pending"
            for r in DATA.get("question_reports", [])
        )
        if dup:
            try:
                await msg.reply_text("✅ این کارت رو قبلاً گزارش کردی — در صف بررسیه. 🙏")
            except Exception:
                pass
        else:
            question_report(rep_uid, qtext, rtext[:200])
            save_data()
            # ۶.۲ — گزارش کارت سوال هم یک پیام اولویت‌بالا در صندوق است
            try:
                entry = {
                    "id": next_id("feedback"),
                    "uid": rep_uid,
                    "text": f"🚩 سوال: {qtext}" + (f" | یادداشت: {rtext[:120]}" if rtext else ""),
                    "ts": now_ts(),
                    "status": "new",
                    "reply": "",
                    "kind": "report",
                    "priority": "high",
                    "source": "question_card",
                    "origin": "کارت سوال در گروه",
                }
                DATA.setdefault("feedback", []).append(entry)
                analytics_bump("reports_sent")
                save_data()
                await admin_notify_inbox(context.bot, entry)
            except Exception:
                pass
            try:
                await msg.reply_text(
                    "🚩 <b>گزارش ثبت شد!</b>\n"
                    "🔴 اولویت: بالا — زودتر بررسی می‌شود\n"
                    "⚡ تیم ربات این سوال رو بررسی می‌کنه — ممنون که مراقب کیفیت بازی هستی 🙏",
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
        return True
    uid = int(update.effective_user.id)
    target = prompt.get("target_uid")
    if target is None:
        return False
    target = int(target)
    if uid != target and not is_admin(uid):
        try:
            await msg.reply_text(f"🎯 فعلاً نوبت {mention_user(target, name_of(target, game))} است.", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return True
    if uid in {int(x) for x in prompt.get("responders", [])}:
        try:
            await msg.reply_text("✅ پاسخ تو قبلاً برای این نوبت ثبت شده است.")
        except Exception:
            pass
        return True
    prompt.setdefault("responders", []).append(uid)
    kind = str(prompt.get("mode") or prompt.get("kind") or "truth")
    # متن پاسخ برای ارزیابی کیفیت
    answer_text = str(msg.text or "").strip()
    answer_len = len(answer_text)

    # --- تکمیل حکم: پاداش کوچک، بدون پیشروی نوبت ---
    if kind == "penalty":
        pending = game.get("pending_penalties", {}).get(str(uid))
        if pending and not pending.get("done") and not pending.get("skipped"):
            pending["done"] = True
            pending["completed_at"] = now_ts()
            add_xp(uid, 4, name_of(uid, game))
            add_coins(uid, 2, name_of(uid, game))
            if str(pending.get("source", "")).startswith("🤫"):
                get_user(uid)["missions"] = int(get_user(uid).get("missions", 0)) + 1
        game.pop("reply_prompt", None)
        touch_game(game)
        save_data(force=True)
        try:
            await msg.reply_text("✅ <b>حکم انجام شد و ثبت شد.</b>\n🎁 +۴ ایکس‌پی و +۲ سکه", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return True

    # محاسبه پاداش بر اساس کیفیت پاسخ
    xp, coins = REPLY_REWARDS.get(kind, (5, 2))
    # پاداش کیفیت: پاسخ‌های طولانی‌تر پاداش بیشتری
    quality_bonus = 0
    quality_label = ""
    if answer_len >= 100:
        quality_bonus = 3
        quality_label = "📝 پاسخ مفصل! +۳ ایکس‌پی"
    elif answer_len >= 50:
        quality_bonus = 2
        quality_label = "📝 پاسخ خوب! +۲ ایکس‌پی"
    elif answer_len >= 20:
        quality_bonus = 1
        quality_label = "📝 پاسخ متوسط! +۱ ایکس‌پی"
    elif answer_len < 5:
        quality_bonus = 0
        quality_label = "📝 پاسخ کوتاه"
    xp_total = xp + quality_bonus
    reward_player(game, uid, xp_total, coins, win=True, reason=f"Turn Reply:{kind}")
    questioner = int(prompt.get("questioner_uid", current_questioner(game) or uid))
    add_xp(questioner, 2, name_of(questioner, game), 1)
    try:
        game.setdefault("round_scores", {})[str(questioner)] = int(game.setdefault("round_scores", {}).get(str(questioner), 0)) + 2
    except Exception:
        pass
    # ثبت آمار پاسخ‌دهی
    try:
        bump_mission_progress(int(uid), "answers", 1)
        if kind == "dare":
            bump_mission_progress(int(uid), "dares", 1)
        elif kind == "truth":
            bump_mission_progress(int(uid), "truths", 1)
    except Exception:
        pass
    game.pop("reply_prompt", None)
    next_q = advance_turn(game)
    save_data(force=True)
    # پیام تأیید غنی
    confirmation_msg = (
        f"✅ <b>پاسخ ثبت شد!</b>\n\n"
        f"🎯 {mention_user(uid, name_of(uid, game))} پاسخ نوبت را داد.\n"
        f"🎤 {mention_user(questioner, name_of(questioner, game))}، سوال شما با موفقیت جواب داده شد.\n"
        f"🎁 پاسخ‌دهنده: +{fmt_num(xp_total)} ایکس‌پی و +{fmt_num(coins)} سکه\n"
        f"⭐ پرسشگر: +۲ ایکس‌پی"
    )
    if quality_label:
        confirmation_msg += f"\n{quality_label}"
    try:
        await msg.reply_text(confirmation_msg, parse_mode=ParseMode.HTML)
    except Exception:
        pass
    if next_q is not None:
        await game_send_turn_card(context, game)
    return True


async def game_show_scores(query, game: dict) -> None:
    """(۱۱.۰) امتیازها با سازنده‌ی مشترک scores_view — و ثبت به‌عنوان نمای فرعی
    تا موتور نبض آن را رندر کند و دیگر با رفرش بلعیده نشود."""
    panel_subview_set(game, "scores")
    panel_reset_timer(game)
    text, markup = scores_view(game)
    await safe_edit(query, text, markup)
    # (۱۱.۰) هش همین رندر ثبت شود تا موتور بعد از مهلت، ویرایش تکراری نزند
    try:
        game["_panel_hash"] = _panel_hash(text, markup)
    except Exception:
        pass


async def cmd_apexend(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or user is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🏁 این دستور فقط داخل گروه کار می‌کند.")
        return
    game = active_game(int(chat.id))
    if game is None:
        await msg.reply_text("فعلاً بازی فعالی در این گروه نیست.")
        return
    if int(user.id) != int(game.get("leader_id", 0)) and not is_admin(int(user.id)):
        await msg.reply_text("فقط سرگروه می‌تواند بازی را تمام کند.")
        return
    await end_game_flow(context, game, reason="manual")


async def end_game_flow(context, game: dict, query=None, reason: str = "manual") -> None:
    chat_id = int(game.get("chat_id", 0))
    game["status"] = "finished"
    game["finish_reason"] = str(reason)
    game["finished_at"] = now_ts()
    scores = game.get("round_scores", {})
    players = [int(x) for x in game.get("players", [])]
    ranked = sorted(players, key=lambda p: -int(scores.get(str(p), 0)))
    # آمار پایان بازی
    for p in players:
        u = get_user(p)
        u["games"] = max(0, int(u.get("games", 0)) - 1) + 1  # بدون تغییر (شروع هم شمرده شد)
    if ranked:
        reward_player(game, ranked[0], 10, 5, win=True, reason="game_win")
        for p in ranked[1:]:
            reward_player(game, p, 3, 1, reason="game_end")
    get_group(chat_id)["active_game"] = None
    # FIX: ثبت آمار پایان بازی در Analytics — قبلاً games_ended هرگز ثبت نمی‌شد
    try:
        analytics_bump("games_ended")
    except Exception:
        pass
    try:
        game_ended_stats(game)
    except Exception:
        pass
    save_data(force=True)
    audit("game_end", 0, chat_id, reason)
    medals = ["🥇", "🥈", "🥉"]
    podium = "\n".join(
        podium_line(medals[i], mention_user(p, name_of(p, game)), scores.get(str(p), 0))
        for i, p in enumerate(ranked[:3]) if int(scores.get(str(p), 0)) > 0
    ) or "│  امتیازی ثبت نشد — ولی خاطره‌ها ارزشش رو داشت!"
    # محاسبه آمار کامل بازی
    started_at = int(game.get("started_at", 0))
    finished_at = int(game.get("finished_at", 0))
    duration_min = (finished_at - started_at) // 60 if started_at else 0
    total_rounds = int(game.get("round", 0))
    # انتخاب بهترین بازیکن بازی (Player of the Game)
    potg_uid = 0
    potg_name = ""
    potg_score = 0
    if ranked and int(scores.get(str(ranked[0]), 0)) > 0:
        potg_uid = int(ranked[0])
        potg_name = name_of(potg_uid, game)
        potg_score = int(scores.get(str(potg_uid), 0))
        # پاداش ویژه‌ی بهترین بازیکن
        try:
            add_xp(potg_uid, 25, name_of(potg_uid))
            add_coins(potg_uid, 15, name_of(potg_uid))
            push_notification(potg_uid, "achievement",
                              "🏆 بهترین بازیکن بازی!",
                              f"در بازی گروهی با {potg_score} امتیاز برنده شدی! +25 XP +15 سکه",
                              action_data="P|PROFILE")
            log_user_activity(potg_uid, "player_of_game", f"+25xp +15c score={potg_score}")
        except Exception:
            pass
    # ساخت مراسم پایانی پرایم
    lines = [
        ds_top("🏆"),
        "│  🏁 <b>مراسم اختتامیه بازی!</b>",
        "│  <i>قهرمان‌ها اعلام می‌شن...</i>",
        ds_sep(),
        "│  ▎🎭 <b>سکوی قهرمانی</b>",
        podium,
    ]
    if potg_uid:
        lines += [
            ds_sep("⋆"),
            f"│  🏆 MVP بازی: {mention_user(potg_uid, potg_name)}",
            f"│  ⭐ با <b>{pnum(potg_score)}</b> امتیاز — <b>+۲۵ XP و +۱۵ سکه</b>",
        ]
    lines += [
        ds_sep("⋆"),
        ds_row("⏱ مدت بازی", f"{pnum(duration_min)} دقیقه"),
        ds_row("🎯 تعداد دور", pnum(total_rounds)),
        ds_row("👥 بازیکنان", pnum(len(players))),
        ds_close("🏆"),
        "",
        "🎉 ممنون از بازیِ شما! برای دور جدید: /apex",
    ]
    text = "\n".join(lines)
    # ثبت در تاریخچه بازی هر بازیکن
    try:
        for p in players:
            p_score = int(scores.get(str(p), 0))
            p_rank = ranked.index(p) + 1 if p in ranked else 0
            is_winner = (p == ranked[0]) if ranked else False
            game_history_add(p, {
                "mode": "group_game",
                "result": "برد" if is_winner else "باخت",
                "xp": 10 if is_winner else 3,
                "coins": 5 if is_winner else 1,
                "players": len(players),
                "chat_id": chat_id,
                "rank": p_rank,
                "score": p_score,
            })
    except Exception:
        pass
    try:
        # سکانس سینمایی کانفتی + اعلام نتایج روی همان پیام
        await cinematic(context.bot, chat_id, confetti_frames(), delay=1.2, final_text=text)
        if query is not None:
            await safe_answer_query(query, "بازی تمام شد 🏁")
    except Exception:
        pass


# -----------------------------
#  نگهبان نوبت (Stall Guard) + بازی گیرکرده (Stuck Recovery)
# -----------------------------
async def stall_guard_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    """هر ۳ دقیقه: بازی‌های گیرکرده را پیدا کن، یادآوری بده یا رد کن.
    نسخه‌ی بهبودیافته: یادآوری چندمرحله‌ای با Escalation.
    """
    try:
        cfgs: dict[int, dict] = {}
        for gid, game in list(DATA.get("games", {}).items()):
            if not isinstance(game, dict) or str(game.get("status")) != "active":
                continue
            chat_id = int(game.get("chat_id", 0))
            if chat_id not in cfgs:
                cfgs[chat_id] = anti_abuse_cfg(chat_id)
            cfg = cfgs[chat_id]
            if not cfg.get("stall", True):
                continue
            prompt = game.get("reply_prompt")
            smin = max(3, int(cfg.get("smin", 12)))
            try:
                sent = game.get("_q_sent_ts", 0)
                reminded_count = int(game.get("_q_remind_count", 0))
                if not sent and isinstance(prompt, dict):
                    sent = float(prompt.get("sent_ts", 0) or 0) or 0
                if not sent:
                    continue
                elapsed = time.time() - float(sent)
                # مرحله‌ی ۱: یادآوری اول (پس از smin دقیقه)
                if elapsed > smin * 60 and reminded_count == 0:
                    target = prompt.get("target_uid")
                    if target:
                        try:
                            await context.bot.send_message(
                                chat_id,
                                f"⏳ {mention_user(int(target), name_of(int(target), game))} هنوز منتظر جواب تو هستیم! 🙏\n"
                                f"💡 با Reply به پیام سوال جواب بده.",
                                parse_mode=ParseMode.HTML,
                            )
                        except Exception:
                            pass
                    game["_q_remind_count"] = 1
                    save_data()
                # مرحله‌ی ۲: یادآوری دوم (پس از smin + ۳ دقیقه)
                elif elapsed > (smin + 3) * 60 and reminded_count == 1:
                    target = prompt.get("target_uid")
                    if target:
                        try:
                            await context.bot.send_message(
                                chat_id,
                                f"⏰ {mention_user(int(target), name_of(int(target), game))} وقتت داره تموم می‌شه! 🚨\n"
                                f"⏳ فقط ۳ دقیقه دیگه!",
                                parse_mode=ParseMode.HTML,
                            )
                        except Exception:
                            pass
                    game["_q_remind_count"] = 2
                    save_data()
                # مرحله‌ی ۳: رد خودکار نوبت (پس از smin + ۶ دقیقه)
                elif elapsed > (smin + 6) * 60:
                    # رد خودکار نوبت
                    target = prompt.get("target_uid")
                    if target:
                        try:
                            await context.bot.send_message(
                                chat_id,
                                f"⏭ نوبت {mention_user(int(target), name_of(int(target), game))} به‌خاطر عدم پاسخ، خودکار رد شد.",
                                parse_mode=ParseMode.HTML,
                            )
                        except Exception:
                            pass
                    game.pop("reply_prompt", None)
                    game.pop("_q_reminded", None)
                    game.pop("_q_remind_count", None)
                    nxt = advance_turn(game)
                    save_data(force=True)
                    if nxt is not None:
                        await game_send_turn_card(context, game)
            except Exception:
                continue
    except Exception as exc:
        audit("stall_guard_error", 0, 0, repr(exc)[:200])


async def stuck_recovery_job(context: ContextTypes.DEFAULT_TYPE) -> None:
    """بازی‌های لابی‌مانده یا بی‌نوبت را بازیابی می‌کند."""
    try:
        for gid, game in list(DATA.get("games", {}).items()):
            if not isinstance(game, dict) or str(game.get("status")) != "active":
                continue
            phase = str(game.get("phase", ""))
            started = float(game.get("started_at", 0) or 0)
            auto_min = int(game.get("settings", {}).get("auto_end_minutes", 90) or 90)
            # بازی خیلی قدیمی → پایان خودکار
            if started and (time.time() - started) > auto_min * 60:
                await end_game_flow(context, game, reason="auto-timeout")
                continue
            # بازی فعال بدون پرسشگر → نوبت جدید
            if phase in ("topic", "playing") and current_questioner(game) is None:
                nxt = advance_turn(game)
                save_data(force=True)
                if nxt is not None:
                    await game_send_turn_card(context, game)
                continue
            # بازی فعال بدون بازیکن زنده → پایان
            if not [p for p in game.get("players", []) if p]:
                await end_game_flow(context, game, reason="empty")
    except Exception as exc:
        audit("stuck_recovery_error", 0, 0, repr(exc)[:200])


# ================================================================
#  سیستم‌های گروهی — تیم‌ها، چالش روزانه، قلب، BRB، گزارش هفتگی
