def teams_entry(chat_id: int) -> dict:
    e = v20_store()["teams"].get(group_key(int(chat_id)))
    if isinstance(e, dict) and str(e.get("date", "")) == day_key():
        return e
    return {}


def teams_build(chat_id: int, players: list) -> dict:
    """قرعه‌ی متعادل تیم قرمز/آبی بر اساس XP (مارپیچ)."""
    ranked = sorted([int(p) for p in players], key=lambda p: -int(get_user(p).get("xp", 0)))
    red, blue = [], []
    for i, p in enumerate(ranked):
        (red if i % 2 == 0 else blue).append(p)
    entry = {
        "date": day_key(),
        "red": red,
        "blue": blue,
        "points": {"red": 0, "blue": 0},
        "ts": now_ts(),
    }
    v20_store()["teams"][group_key(int(chat_id))] = entry
    save_data()
    return entry


def team_credit(uid: int, xp: int) -> None:
    """امتیاز سایه‌ای تیم: XP هر عضو به تیمش هم اضافه می‌شود."""
    try:
        if int(xp) <= 0:
            return
        # جستجو در همه‌ی گروه‌های امروز
        teams = v20_store()["teams"]
        today = day_key()
        for gk, entry in teams.items():
            if not isinstance(entry, dict) or str(entry.get("date", "")) != today:
                continue
            for color in ("red", "blue"):
                if int(uid) in [int(x) for x in entry.get(color, [])]:
                    pts = entry.setdefault("points", {})
                    pts[color] = int(pts.get(color, 0)) + int(xp)
                    return
    except Exception:
        pass


def teams_text(chat_id: int) -> str:
    e = teams_entry(chat_id)
    if not e:
        return (
            "🤝 <b>تیم‌های رقابتی</b>\n━━━━━━━━━━━━━━━━━━\n"
            "برای این گروه هنوز تیمی ساخته نشده است.\n"
            "تیم‌ها به‌صورت خودکار هنگام شروع بازی (۴ نفر به بالا) ساخته می‌شوند."
        )
    def side(color, emoji):
        members = [int(x) for x in e.get(color, [])]
        if not members:
            return f"{emoji} <b>تیم {('قرمز' if color=='red' else 'آبی')}</b>: —"
        names = "، ".join(mention_user(p, name_of(p)) for p in members)
        return f"{emoji} <b>تیم {('قرمز' if color=='red' else 'آبی')}</b>: {names}"
    r = int(e.get("points", {}).get("red", 0))
    b = int(e.get("points", {}).get("blue", 0))
    return (
        "🤝 <b>تیم‌های رقابتی</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"{side('red', '🔴')}\n{side('blue', '🔵')}\n\n"
        f"⚔️ امتیاز: قرمز <b>{fmt_num(r)}</b> — آبی <b>{fmt_num(b)}</b>\n"
        + ("🔴 تیم قرمز جلوتر است!" if r > b else ("🔵 تیم آبی جلوتر است!" if b > r else "⚖️ مساوی!"))
    )


async def cmd_apexteams(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    chat = update.effective_chat
    if msg is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🤝 تیم‌ها فقط داخل گروه ساخته می‌شوند.")
        return
    game = active_game(int(chat.id))
    players = [int(x) for x in game.get("players", [])] if game else []
    if len(players) >= 4 and not teams_entry(int(chat.id)):
        teams_build(int(chat.id), players)
        save_data()
    await msg.reply_text(teams_text(int(chat.id)), parse_mode=ParseMode.HTML)


def daily_entry(chat_id: int) -> dict:
    st = v20_store()["daily"]
    e = st.get(group_key(int(chat_id)))
    if not isinstance(e, dict) or str(e.get("date", "")) != day_key():
        e = {"date": day_key(), "turns": 0, "claimed": False, "players": {}}
        st[group_key(int(chat_id))] = e
    return e


def daily_tick(game: dict, questioner: int) -> None:
    """هر اعلام نوبت، شمارنده‌ی چالش روزانه را زیاد می‌کند."""
    try:
        if not chat_cfg(int(game.get("chat_id", 0))).get("daily", True):
            return
        e = daily_entry(int(game.get("chat_id", 0)))
        e["turns"] = int(e.get("turns", 0)) + 1
        if questioner:
            k = user_key(int(questioner))
            e["players"][k] = int(e.get("players", {}).get(k, 0)) + 1
        if not e.get("claimed") and int(e.get("turns", 0)) >= int(chat_cfg(int(game.get("chat_id", 0))).get("daily_goal", 25)):
            e["claimed"] = True
    except Exception:
        pass


def daily_text(chat_id: int) -> str:
    e = daily_entry(chat_id)
    cfg = chat_cfg(chat_id)
    goal = int(cfg.get("daily_goal", 25))
    turns = int(e.get("turns", 0))
    bar = progress_bar(turns, goal)
    if e.get("claimed"):
        status = "✅ کامل شد — جایزه به همه‌ی بازیکنان فعال رسید!"
    else:
        status = f"⏳ باقی‌مانده: <b>{fmt_num(max(0, goal - turns))}</b> نوبت"
    return (
        "📅 <b>چالش روزانه‌ی گروه</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"🎯 هدف امروز: <b>{fmt_num(goal)}</b> نوبت پرسشگری\n"
        f"📊 پیشرفت: <b>{fmt_num(turns)}/{fmt_num(goal)}</b> {bar}\n"
        f"{status}\n\n"
        "🎁 جایزه: هر بازیکنِ فعال امروز +۸ سکه می‌گیرد."
    )


async def daily_celebrate(context, chat_id: int) -> None:
    """پرداخت جایزه‌ی چالش روزانه به همه‌ی بازیکنان فعال امروز."""
    try:
        e = daily_entry(chat_id)
        for k in list(e.get("players", {}).keys()):
            try:
                uid = int(k)
            except Exception:
                continue
            add_coins(uid, 8, name_of(uid))
            award_achievement(uid, "v20_daily_hero")
        save_data(force=True)
        await context.bot.send_message(
            int(chat_id),
            "🎉 <b>چالش روزانه کامل شد!</b>\n"
            "🎁 همه‌ی بازیکنان فعال امروز +۸ سکه دریافت کردند.",
            parse_mode=ParseMode.HTML,
        )
    except Exception as exc:
        audit("daily_celebrate_error", 0, int(chat_id), repr(exc)[:200])


