async def cmd_apexheart(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """قلب محبت: روی ریپلای یک نفر، روزی ۶ بار، +۳ سکه به طرف مقابل."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    target = getattr(msg.reply_to_message, "from_user", None) if msg.reply_to_message else None
    if target is None or int(target.id) == int(user.id):
        await msg.reply_text("❤️ روی پیام یکی دیگر Reply کن تا قلب بفرستی!")
