def weekly_board(limit: int = 10) -> list:
    """بردهای هفتگی از دفتر XP هفته."""
    week = week_key()
    weekly = DATA.setdefault("v19", {}).setdefault("weekly", {})
    book = weekly.get(week)
    if not isinstance(book, dict):
        book = {}
        weekly[week] = book
    items = sorted(book.items(), key=lambda kv: -int(kv[1] or 0))
    out = []
    for k, v in items[:int(limit)]:
        try:
            out.append((int(k), int(v)))
        except Exception:
            continue
    return out


def weekly_record_xp(uid: int, xp: int) -> None:
    """ثبت XP در دفتر هفتگی."""
    if int(xp) <= 0:
        return
    try:
        week = week_key()
        weekly = DATA.setdefault("v19", {}).setdefault("weekly", {})
        book = weekly.setdefault(week, {})
        k = user_key(int(uid))
        book[k] = int(book.get(k, 0)) + int(xp)
    except Exception:
        pass


