def uptime_text() -> str:
    sec = max(1, int(time.time() - BOOT_TS))
    d, rem = divmod(sec, 86400)
    h, rem = divmod(rem, 3600)
    m, _ = divmod(rem, 60)
    if d:
        return f"{fmt_num(d)} روز و {fmt_num(h)} ساعت"
    if h:
        return f"{fmt_num(h)} ساعت و {fmt_num(m)} دقیقه"
    return f"{fmt_num(m)} دقیقه"


def rss_mb() -> float:
    try:
        with open("/proc/self/status", "r", encoding="utf-8") as fh:
            for line in fh:
                if line.startswith("VmRSS:"):
                    return round(int(line.split()[1]) / 1024.0, 1)
    except Exception:
        pass
    return 0.0


