LOVE_DIMS = [
    ("romance", "🌹 رمانس"),
    ("trust", "🛡 اعتماد"),
    ("fun", "🎉 هیجان"),
    ("future", "🚀 آینده"),
]


def love_score(a: int, b: int) -> int:
    """درصد عشق پایدار (بر اساس آیدی‌ها — همیشه یکسان)."""
    seed = f"{min(a,b)}x{max(a,b)}"
    return 40 + int(hashlib.sha256(seed.encode()).hexdigest()[:6], 16) % 61


def love_report(a_name: str, b_name: str, a: int, b: int) -> str:
    total = love_score(a, b)
    lines = []
    for key, label in LOVE_DIMS:
        seed = f"{min(a,b)}:{max(a,b)}:{key}"
        v = 30 + int(hashlib.sha256(seed.encode()).hexdigest()[:6], 16) % 71
        lines.append(f"{label}: <b>{fmt_num(v)}٪</b> {progress_bar(v, 100, 8)}")
    if total >= 85:
        verdict = "💞 افسانه‌ای! همین امشب قهوه بخورید."
    elif total >= 65:
        verdict = "💖 قول خوبی می‌دهد؛ یک قرار بیشتر لازم است."
    elif total >= 45:
        verdict = "🤔 پتانسیل هست ولی هنوز جوش نیامده."
    else:
        verdict = "🌿 دوستیِ قشنگی می‌شوید — عاشقی هنوز زود است."
    return (
        "❤️ <b>عشق‌سنج حرفه‌ای</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"💜 {escape(a_name)} و {escape(b_name)}\n\n"
        f"💘 درصد تطابق کلی: <b>{fmt_num(total)}٪</b> {progress_bar(total, 100, 10)}\n\n"
        + "\n".join(lines)
        + f"\n\n🔮 <b>حکم عشق‌سنج:</b> {verdict}"
    )


