async def cmd_apexpunishments(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """فهرست مجازات‌های در جریان."""
    msg = update.message
    if msg is None:
        return
    rows = []
    for pid, p in v24_store()["punish"].items():
        if not isinstance(p, dict) or p.get("done") or p.get("expired") or p.get("forgiven"):
            continue
        if (time.time() - float(p.get("ts", 0) or 0)) > 24 * 3600:
            continue
        age_h = int((time.time() - float(p.get("ts", 0))) // 3600)
        rows.append(
            f"• {mention_user(int(p.get('uid', 0)), name_of(int(p.get('uid', 0))))} — "
            f"«{escape(str(p.get('text', ''))[:60])}» ({fmt_num(age_h)} ساعت پیش)"
        )
    await msg.reply_text(
        "⚖️ <b>مجازات‌های در جریان</b>\n━━━━━━━━━━━━━━━━━━\n"
        + ("\n".join(rows) if rows else "فعلاً هیچ مجازاتی در جریان نیست. چه صلح و صفایی! 🕊"),
        parse_mode=ParseMode.HTML,
    )


async def punish_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    data = str(query.data or "")
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""
    pid = parts[2] if len(parts) > 2 else ""
    uid = int(query.from_user.id)
    p = v24_store()["punish"].get(str(pid))
    if not isinstance(p, dict):
        await safe_answer_query(query, "این حکم دیگر معتبر نیست.")
        return
    judge = int(p.get("by", 0))

    if action == "DONE":
        # محکوم اعلام انجام می‌کند؛ قاضی (یا ادمین) تایید نهایی می‌کند
        if p.get("done"):
            await safe_answer_query(query, "قبلاً تایید شده است ✅")
            return
        p["claimed"] = True
        save_data()
        await safe_answer_query(query, "در انتظار تایید قاضی... ⏳")
        await context.bot.send_message(
            int(p.get("chat_id", 0)),
            f"🙋 {mention_user(int(p.get('uid', 0)), name_of(int(p.get('uid', 0))))} ادعا کرد حکم را انجام داده است!\n"
            f"🧑‍⚖️ {mention_user(judge, name_of(judge))} تایید می‌کنی؟",
            parse_mode=ParseMode.HTML,
            reply_markup=kb([
                [btn("✅ تایید و پاداش", f"PN|CONFIRM|{pid}"), btn("❌ رد ادعا", f"PN|REJECT|{pid}")],
            ]),
        )
        return

    if action in ("CONFIRM", "REJECT"):
        if uid != judge and not is_admin(uid):
            await safe_answer_query(query, "فقط قاضی یا ادمین می‌تواند تایید کند.", True)
            return
        if action == "CONFIRM":
            p["done"] = True
            p["confirmed"] = True
            cond = int(p.get("uid", 0))
            add_xp(cond, 5, name_of(cond))
            add_coins(cond, 3, name_of(cond))
            save_data(force=True)
            await safe_answer_query(query, "تایید شد ✅")
            await context.bot.send_message(
                int(p.get("chat_id", 0)),
                f"✅ حکم تایید شد! {mention_user(cond, name_of(cond))} آزاد شد و +۵ XP و +۳ سکه گرفت.",
                parse_mode=ParseMode.HTML,
            )
        else:
            p.pop("claimed", None)
            save_data()
            await safe_answer_query(query, "ادعا رد شد")
            await context.bot.send_message(
                int(p.get("chat_id", 0)),
                f"❌ ادعای {mention_user(int(p.get('uid', 0)), name_of(int(p.get('uid', 0))))} رد شد. حکم همچنان پابرجاست!",
                parse_mode=ParseMode.HTML,
            )
        return

    if action == "FORGIVE":
        if uid != judge and not is_admin(uid):
            await safe_answer_query(query, "فقط قاضی یا ادمین می‌تواند ببخشد.", True)
            return
        p["forgiven"] = True
        save_data(force=True)
        await safe_answer_query(query, "بخیده شد 🕊")
        await context.bot.send_message(
            int(p.get("chat_id", 0)),
            f"🤝 {mention_user(int(p.get('uid', 0)), name_of(int(p.get('uid', 0))))} بخشیده شد!",
            parse_mode=ParseMode.HTML,
        )
        return

    await safe_answer_query(query)


# ================================================================
#  دوئل دو نفره — /apexduel با لینک دعوت
