DUEL_ROUNDS = 10


async def cmd_apexduel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """دوئل: در گروه روی ریپلای حریف یا در خصوصی با دعوت‌نامه."""
    msg = update.message
    user = update.effective_user
    chat = update.effective_chat
    if msg is None or user is None or chat is None:
        return
    uid = int(user.id)
    st = v24_store()
    # در خصوصی
    if chat.type == "private":
        code = v24_new_code()
        st["duels"][str(code)] = {
            "a": uid, "b": None,
            "round": 0, "score_a": 0, "score_b": 0,
            "ts": now_ts(), "state": "waiting",
        }
        save_data(force=True)
        try:
            me = await context.bot.get_me()
            link = f"https://t.me/{me.username}?start=duel-{code}"
        except Exception:
            link = ""
        await msg.reply_text(
            "🤺 <b>دوئل دو نفره</b>\n━━━━━━━━━━━━━━━━━━\n"
            "یک لینک دعوت برایت ساختم؛ برای حریف بفرست تا نبرد شروع شود!\n"
            "⏱ مهلت پیوستن: ۲۴ ساعت\n\n"
            "🎁 برنده: +۱۰ XP و +۵ سکه",
            parse_mode=ParseMode.HTML,
            reply_markup=kb([[InlineKeyboardButton("⚔️ لینک دعوت دوئل", url=link)]]) if link else None,
        )
        return
    # در گروه
    target = getattr(msg.reply_to_message, "from_user", None) if msg.reply_to_message else None
    if target is None:
        await msg.reply_text("🤺 در گروه روی پیام حریف Reply کن و /apexduel بزن، یا در چت خصوصی من /apexduel بزن تا لینک دعوت بگیری.")
        return
    tid = int(target.id)
    if tid == uid:
        await msg.reply_text("😅 با خودت نمی‌توانی دوئل کنی!")
        return
    code = v24_new_code()
    st["duels"][str(code)] = {
        "a": uid, "b": tid,
        "round": 0, "score_a": 0, "score_b": 0,
        "ts": now_ts(), "state": "topic",
        "chat_id": int(chat.id),
    }
    st["stats"]["duels"] = int(st["stats"].get("duels", 0)) + 1
    save_data(force=True)
    await msg.reply_text(
        f"🤺 <b>چالش دوئل!</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"⚔️ {mention_user(uid, user.first_name)} ↔️ {mention_user(tid, target.first_name)}\n\n"
        "۱۰ راند، هر راند یک سوال از بانک بزرگ؛ برنده‌ی راندهای بیشتر، قهرمان است!\n"
        "شروع در چت خصوصی ربات انجام می‌شود ⬇️",
        parse_mode=ParseMode.HTML,
        reply_markup=kb([[btn("🎯 شروع دوئل (خصوصی)", "D|OPEN")]]),
    )
    for who in (uid, tid):
        try:
            await context.bot.send_message(
                who,
                "🤺 دوئل شما آماده است! دکمه‌ی زیر را بزن تا به میدان خصوصی دوئل بروی:",
                reply_markup=kb([[btn("⚔️ ورود به دوئل", f"D|ENTER|{code}")]]),
            )
        except Exception:
            pass


async def duel_handle_deep_link(update: Update, context: ContextTypes.DEFAULT_TYPE, uid: int, code_raw) -> None:
    """دیپ‌لینک /start duel-<code> و duel-lv<code><a|b> (عشق‌سنج)."""
    msg = update.message
    raw = str(code_raw)
    # عشق‌سنج دو نفره: duel-lv123a
    if raw.startswith("lv") and len(raw) >= 4:
        side = raw[-1] if raw[-1] in ("a", "b") else "a"
        try:
            code = int(raw[2:-1])
        except Exception:
            code = 0
        if code:
            await love2_start_for(update, context, uid, code, side)
            return
    try:
        code = int(raw)
    except Exception:
        code = 0
    if not code:
        await msg.reply_text("⌛ این لینک دعوت معتبر نیست.")
        return
    st = v24_store()
    duel = st["duels"].get(str(code))
    if not isinstance(duel, dict):
        await msg.reply_text("⌛ این دعوت‌نامه منقضی شده است.")
        return
    if (time.time() - float(duel.get("ts", 0))) > 24 * 3600:
        st["duels"].pop(str(code), None)
        save_data()
        await msg.reply_text("⌛ این دعوت‌نامه منقضی شده است.")
        return
    if int(duel.get("a", 0)) == uid:
        await duel_show(update, context, uid, code)
        return
    if duel.get("b") is None:
        duel["b"] = uid
        duel["state"] = "topic"
        save_data(force=True)
        await duel_show(update, context, uid, code)
        try:
            await context.bot.send_message(int(duel["a"]), "⚔️ حریفت پیوست! دوئل آماده است.")
        except Exception:
            pass
        return
    if int(duel.get("b", 0)) == uid:
        await duel_show(update, context, uid, code)
        return
    await msg.reply_text("🚫 این دوئل مخصوص دو نفر دیگر است!")


async def duel_show(update: Update, context: ContextTypes.DEFAULT_TYPE, uid: int, code: int) -> None:
    duel = v24_store()["duels"].get(str(code))
    if not isinstance(duel, dict):
        await update.message.reply_text("⌛ این دوئل دیگر معتبر نیست.")
        return
    _, b = int(duel.get("a", 0)), int(duel.get("b", 0) or 0)
    if not b:
        await update.message.reply_text(
            "⏳ در انتظار حریف...\nلینک دعوت را برایش بفرست!",
            reply_markup=kb([[btn("🔄 تازه‌سازی", f"D|ENTER|{code}")]]),
        )
        return
    await update.message.reply_text(
        duel_round_text(duel, code),
        parse_mode=ParseMode.HTML,
        reply_markup=duel_round_markup(duel, code, uid),
    )


def duel_round_text(duel: dict, code: int) -> str:
    a, b = int(duel.get("a", 0)), int(duel.get("b", 0) or 0)
    rnd = int(duel.get("round", 0))
    if str(duel.get("state")) == "done":
        sa, sb = int(duel.get("score_a", 0)), int(duel.get("score_b", 0))
        if sa > sb:
            champ = mention_user(a, name_of(a))
        elif sb > sa:
            champ = mention_user(b, name_of(b))
        else:
            champ = "هیچ‌کس — مساوی!"
        lines = [
            ds_top("🏁"),
            "│  🏁 <b>پایان دوئل — نتیجه نهایی</b>",
            ds_sep(),
            f"│  ⚔️ {mention_user(a, name_of(a))} <b>{pnum(int(duel.get('score_a', 0)))}</b> — "
            f"<b>{pnum(int(duel.get('score_b', 0)))}</b> {mention_user(b, name_of(b))}",
            ds_sep("⋆"),
            f"│  🏆 قهرمان دوئل: {champ}",
            ds_close("🏁"),
        ]
        return "\n".join(lines)
    turn_is_a = (rnd % 2 == 0)
    current = a if turn_is_a else b
    lines = [
        ds_top("🤺"),
        f"│  🤺 <b>دوئل آتشین</b> — راند <b>{pnum(rnd + 1)}</b> از {pnum(DUEL_ROUNDS)}",
        "│  <i>شمشیرها رو بکشید!</i>",
        ds_sep(),
        f"│  ⚔️ {mention_user(a, name_of(a))} <b>{pnum(int(duel.get('score_a', 0)))}</b> — "
        f"<b>{pnum(int(duel.get('score_b', 0)))}</b> {mention_user(b, name_of(b))}",
        f"│  {pbar(rnd, DUEL_ROUNDS, 12, pct=False)} پیشرفت دوئل",
        ds_sep("⋆"),
        f"│  🎯 نوبت انتخاب موضوع: {mention_user(current, name_of(current))}",
        ds_close("🤺"),
    ]
    return "\n".join(lines)


def duel_round_markup(duel: dict, code: int, uid: int) -> InlineKeyboardMarkup:
    if str(duel.get("state")) == "done":
        return kb([[btn("⌂ منوی اصلی", "H|HOME")]])
    rnd = int(duel.get("round", 0))
    current = int(duel.get("a", 0)) if rnd % 2 == 0 else int(duel.get("b", 0) or 0)
    if uid != current:
        return kb([[btn("🔄 منتظر حریف...", "D|ENTER|{}".format(code))]])
    rows = []
    pair = []
    for key, label in MODE_ORDER[:8]:
        pair.append(btn(label, f"D|MODE|{code}|{key}"))
        if len(pair) == 2:
            rows.append(pair)
            pair = []
    if pair:
        rows.append(pair)
    return kb(rows)


async def duel_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    data = str(query.data or "")
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    try:
        code = int(parts[2]) if len(parts) > 2 else 0
    except Exception:
        code = 0

    if action == "OPEN" and update.effective_chat:
        # انتقال به خصوصی
        try:
            await context.bot.send_message(uid, "🤺 برای دوئل، اینجا را ادامه بده!", reply_markup=kb([[btn("⚔️ دوئل‌های من", "D|LIST")]]))
            await safe_answer_query(query, "در چت خصوصی ادامه بده! 📩")
        except Exception:
            await safe_answer_query(query, "اول به چت من /start بزن!", True)
        return

    if action == "LIST":
        st = v24_store()
        mine = [(cid, d) for cid, d in st["duels"].items()
                if isinstance(d, dict) and uid in (int(d.get("a", 0)), int(d.get("b", 0) or 0))
                and str(d.get("state")) != "done" and (time.time() - float(d.get("ts", 0))) < 24 * 3600]
        if not mine:
            await safe_answer_query(query)
            await safe_edit(query, "فعلاً دوئل فعالی نداری.\nبرای ساخت: /apexduel", kb([[btn("⌂ منوی اصلی", "H|HOME")]]))
            return
        rows = [[btn(f"🤺 دوئل #{cid}", f"D|ENTER|{cid}")] for cid, _ in mine]
        await safe_answer_query(query)
        await safe_edit(query, "🤺 <b>دوئل‌های فعال من</b>", kb(rows))
        return

    if action == "ENTER":
        if not code:
            await safe_answer_query(query)
            return
        await safe_answer_query(query)
        await duel_show(query, context, uid, code)
        return

    if action == "MODE":
        duel = v24_store()["duels"].get(str(code))
        if not isinstance(duel, dict) or str(duel.get("state")) == "done":
            await safe_answer_query(query, "این دوئل تمام شده است.")
            return
        rnd = int(duel.get("round", 0))
        current = int(duel.get("a", 0)) if rnd % 2 == 0 else int(duel.get("b", 0) or 0)
        if uid != current:
            await safe_answer_query(query, "نوبت حریف است!", True)
            return
        mode = parts[3] if len(parts) > 3 else "truth"
        question = pick_question(duel, mode, uid)
        duel["current_q"] = question
        duel["current_mode"] = mode
        duel["state"] = "answer"
        duel["q_ts"] = time.time()
        save_data(force=True)
        await safe_answer_query(query, "سوال صادر شد!")
        await safe_edit(
            query,
            f"🤺 <b>راند {fmt_num(rnd + 1)}</b> — {MODE_LABELS.get(mode, mode)}\n"
            f"{ds_sep('⋆')}\n"
            f"<b>{escape(question)}</b>\n\n"
            f"✍️ {mention_user(uid, name_of(uid))}، جوابت را بنویس (یک پیام).\n"
            "⏱ ۱۲۰ ثانیه وقت داری!",
            kb([[btn("⏭ رد کردن", f"D|SKIPQ|{code}")]]),
        )
        return

    if action == "SKIPQ":
        duel = v24_store()["duels"].get(str(code))
        if not isinstance(duel, dict) or str(duel.get("state")) != "answer":
            await safe_answer_query(query)
            return
        if uid not in (int(duel.get("a", 0)), int(duel.get("b", 0) or 0)):
            await safe_answer_query(query)
            return
        duel["state"] = "topic"
        duel["round"] = int(duel.get("round", 0)) + 1
        save_data()
        await safe_answer_query(query, "رد شد")
        if duel["round"] >= DUEL_ROUNDS:
            await duel_finish(context, code, duel)
            return
        await safe_edit(query, duel_round_text(duel, code), duel_round_markup(duel, code, uid))
        return

    await safe_answer_query(query)


async def duel_finish(context, code: int, duel: dict) -> None:
    duel["state"] = "done"
    a, b = int(duel.get("a", 0)), int(duel.get("b", 0) or 0)
    sa, sb = int(duel.get("score_a", 0)), int(duel.get("score_b", 0))
    if sa > sb and a:
        add_xp(a, 10, name_of(a)); add_coins(a, 5, name_of(a))
    elif sb > sa and b:
        add_xp(b, 10, name_of(b)); add_coins(b, 5, name_of(b))
    for who in (a, b):
        if who:
            get_user(who)["duels"] = int(get_user(who).get("duels", 0)) + 1
    award_achievement(a, "v24_duelist")
    award_achievement(b, "v24_duelist")
    save_data(force=True)
    text = duel_round_text(duel, code)
    for who in (a, b):
        if who:
            try:
                await context.bot.send_message(who, text, parse_mode=ParseMode.HTML)
            except Exception:
                pass
    gid = duel.get("chat_id")
    if gid:
        try:
            await context.bot.send_message(int(gid), text, parse_mode=ParseMode.HTML)
        except Exception:
            pass


async def duel_handle_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """جواب‌های متنی دوئل در چت خصوصی."""
    msg = update.message
    if msg is None or not msg.text:
        return False
    chat = update.effective_chat
    if chat is None or chat.type != "private":
        return False
    uid = int(update.effective_user.id)
    for code, duel in v24_store()["duels"].items():
        if not isinstance(duel, dict) or str(duel.get("state")) != "answer":
            continue
        if uid not in (int(duel.get("a", 0)), int(duel.get("b", 0) or 0)):
            continue
        if time.time() - float(duel.get("q_ts", 0) or 0) > 120:
            duel["state"] = "topic"
            duel["round"] = int(duel.get("round", 0)) + 1
            save_data()
            await msg.reply_text("⌛ وقت تمام شد؛ راند رد شد.")
            return True
        # پاسخ‌دهنده امتیاز می‌گیرد
        is_a = uid == int(duel.get("a", 0))
        duel["score_a" if is_a else "score_b"] = int(duel.get("score_a" if is_a else "score_b", 0)) + 1
        add_xp(uid, 3, name_of(uid))
        duel["state"] = "topic"
        duel["round"] = int(duel.get("round", 0)) + 1
        save_data(force=True)
        await msg.reply_text("✅ جواب ثبت شد! +۳ XP")
        if int(duel.get("round", 0)) >= DUEL_ROUNDS:
            await duel_finish(context, int(code), duel)
            return True
        await msg.reply_text(duel_round_text(duel, int(code)), parse_mode=ParseMode.HTML,
                             reply_markup=duel_round_markup(duel, int(code), uid))
        return True
    return False


# ================================================================
#  بازی‌های مهمانی — گردونه، می‌کردی؟، هرگز نشده، به احتمال زیاد
# ================================================================

async def cmd_apexspin(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """گردونه‌ی بطری — در گروه."""
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or user is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🎰 گردونه‌ی بطری فقط در گروه چرخش می‌کند!")
        return
    # بازیکنان از بازی فعال یا اخیرین پیام‌ها — ساده: بازی فعال یا لیست آماده
    game = active_game(int(chat.id))
    players = [int(x) for x in game.get("players", [])] if game else []
    if len(players) < 2:
        await msg.reply_text(
            "🎰 <b>گردونه‌ی بطری</b>\n"
            "حداقل ۲ بازیکن لازم است!\n"
            "اول با /apex لابی باز کن، بعد گردونه را بچرخان.",
            parse_mode=ParseMode.HTML,
        )
        return
    victim = random.choice(players)
    bank = random.choice(["truth", "dare", "flirty"])
    question = pick_question({"v7_used_prompts_global": [], "v7_used_penalties": [], "round": 0}, bank, victim)
    v24_store()["stats"]["party_games"] = int(v24_store()["stats"].get("party_games", 0)) + 1
    award_achievement(int(user.id), "v24_party_soul")
    save_data()
    await msg.reply_text(
        f"🎰 <b>گردونه چرخید...</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"🍾 گردونه روی {mention_user(victim, name_of(victim))} ایستاد!\n\n"
        f"🎲 حکم گردونه: <b>{MODE_LABELS.get(bank, bank)}</b>\n"
        f"<b>{escape(question)}</b>",
        parse_mode=ParseMode.HTML,
    )


WYR_TEMPLATE = [
    ("A", "B"),
]


async def cmd_apexwyr(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """می‌کردی؟ — رأی‌گیری زنده با نوار درصد."""
    msg = update.message
    chat = update.effective_chat
    if msg is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🤔 «می‌کردی؟» فقط در گروه جواب می‌دهد!")
        return
    question = pick_question({"v7_used_prompts_global": [], "v7_used_penalties": [], "round": 0}, "wouldyou", None)
    # پرسش‌های بانک به شکل «... یا ...» هستند؛ اگر نبود، جدا کن
    if " یا " in question:
        left, right = question.split(" یا ", 1)
    else:
        left, right = question, "همه‌چیز را رها کنی و بروی!"
    poll_id = f"wyr{v24_new_code()}"
    context.application.bot_data.setdefault("wyr", {})[poll_id] = {"a": 0, "b": 0, "voters": {}, "ts": time.time()}
    v24_store()["stats"]["party_games"] = int(v24_store()["stats"].get("party_games", 0)) + 1
    save_data()
    await msg.reply_text(
        "🤔 <b>تو کدوم رو می‌کردی؟</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"🅰️ <b>{escape(left.strip())}</b>\n\nیا\n\n"
        f"🅱️ <b>{escape(right.strip())}</b>",
        parse_mode=ParseMode.HTML,
        reply_markup=kb([
            [btn("🅰️ گزینه اول", f"FY|WYR|{poll_id}|a"), btn("🅱️ گزینه دوم", f"FY|WYR|{poll_id}|b")],
        ]),
    )


async def wyr_vote(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    if len(parts) < 4:
        await safe_answer_query(query)
        return
    poll_id, choice = parts[2], parts[3]
    polls = context.application.bot_data.setdefault("wyr", {})
    poll = polls.get(poll_id)
    if not isinstance(poll, dict):
        await safe_answer_query(query, "این نظرسنجی بسته شده است.")
        return
    uid = int(query.from_user.id)
    voters = poll.setdefault("voters", {})
    if str(uid) in voters:
        await safe_answer_query(query, "رأی‌ات را قبلاً دادی! 🗳")
        return
    voters[str(uid)] = choice
    poll[choice] = int(poll.get(choice, 0)) + 1
    a, b = int(poll.get("a", 0)), int(poll.get("b", 0))
    total = max(1, a + b)
    pa, pb = int(a * 100 / total), 100 - int(a * 100 / total)
    try:
        await query.edit_message_text(
            "🤔 <b>تو کدوم رو می‌کردی؟</b> (زنده!)\n━━━━━━━━━━━━━━━━━━\n"
            f"🅰️ {progress_bar(pa, 100, 8)} <b>{fmt_num(pa)}٪</b> ({fmt_num(a)})\n"
            f"🅱️ {progress_bar(pb, 100, 8)} <b>{fmt_num(pb)}٪</b> ({fmt_num(b)})\n\n"
            "🗳 رأی بده تا نوارها زنده به‌روز شوند!",
            parse_mode=ParseMode.HTML,
            reply_markup=query.message.reply_markup,
        )
        await safe_answer_query(query, "رأی ثبت شد! 🗳")
    except Exception:
        await safe_answer_query(query, "رأی ثبت شد! 🗳")


