async def cmd_apexlikely(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """به احتمال زیاد — رأی‌گیری که کی این کار را می‌کند."""
    msg = update.message
    chat = update.effective_chat
    if msg is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🎯 «به احتمال زیاد» فقط در گروه!")
        return
    game = active_game(int(chat.id))
    players = [int(x) for x in game.get("players", [])] if game else []
    question = random.choice(QUESTIONS_GROUP)
    v24_store()["stats"]["party_games"] = int(v24_store()["stats"].get("party_games", 0)) + 1
    save_data()
    poll_id = f"lk{v24_new_code()}"
    context.application.bot_data.setdefault("likely", {})[poll_id] = {"votes": {}, "ts": time.time()}
    rows = []
    if len(players) >= 2:
        for p in players:
            rows.append([btn(f"👉 {name_of(p, game)}", f"FY|LIKELY|{poll_id}|{p}")])
    else:
        await msg.reply_text(
            "🎯 <b>به احتمال زیاد</b>\n━━━━━━━━━━━━━━━━━━\n"
            f"❓ {escape(question)}\n\n"
            "برای رأی‌گیری بازیکنان، اول با /apex لازی باز کن؛ فعلاً بحث آزاد!",
            parse_mode=ParseMode.HTML,
        )
        return
    await msg.reply_text(
        "🎯 <b>به احتمال زیاد، کی؟</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"❓ {escape(question)}\n\n"
        "🗳 به نظرت کدام بازیکن؟ رأی بده!",
        parse_mode=ParseMode.HTML,
        reply_markup=kb(rows),
    )


async def likely_vote(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    if len(parts) < 4:
        await safe_answer_query(query)
        return
    poll_id, target = parts[2], parts[3]
    polls = context.application.bot_data.setdefault("likely", {})
    poll = polls.get(poll_id)
    if not isinstance(poll, dict):
        await safe_answer_query(query, "این رأی‌گیری بسته شده است.")
        return
    uid = int(query.from_user.id)
    votes = poll.setdefault("votes", {})
    votes[str(uid)] = target
    counts: dict[str, int] = {}
    for v in votes.values():
        counts[v] = counts.get(v, 0) + 1
    top = sorted(counts.items(), key=lambda kv: -kv[1])
    lines = "\n".join(
        f"• {mention_user(int(k), name_of(int(k)))}: <b>{fmt_num(v)} رأی</b> {progress_bar(v, max(1, len(votes)), 8)}"
        for k, v in top
    )
    try:
        await query.edit_message_text(
            "🎯 <b>به احتمال زیاد، کی؟</b> (زنده!)\n━━━━━━━━━━━━━━━━━━\n"
            + (lines or "هنوز رأیی نیامده."),
            parse_mode=ParseMode.HTML,
            reply_markup=query.message.reply_markup,
        )
        await safe_answer_query(query, "رأی ثبت شد! 🗳")
    except Exception:
        await safe_answer_query(query, "رأی ثبت شد! 🗳")


