THEME_BORDERS = {
    "purple": "✦✦✦✦✦✦✦✦✦✦",
    "gold": "★⋆★⋆★⋆★⋆★⋆",
    "fire": "✹✹✹✹✹✹✹✹✹✹",
    "ocean": "≈≈≈≈≈≈≈≈≈≈",
    "neon": "✧△✧△✧△✧△✧△",
    "royal": "♛♔♛♔♛♔♛♔♛♔",
}


def profile_text(uid: int) -> str:
    u = get_user(uid)
    level = int(u.get("level", 1))
    xp = int(u.get("xp", 0))
    floor_xp = (level - 1) * 100
    title = str(u.get("title") or "")
    title_disp = TITLES_SHOP.get(title, {}).get("name", "") if title else title_for(xp)
    inv = u.get("inventory", {})
    inv_count = sum(1 for v in inv.values() if int(v) > 0)
    stats = u.get("stats", {})
    fav = ""
    try:
        fav_key, fav_n = sorted(
            [(k, int(v)) for k, v in stats.items() if int(v) > 0],
            key=lambda kv: -kv[1])[0]
        fav = f"{MODE_LABELS.get(fav_key, fav_key)} ({fmt_num(fav_n)} بار)"
    except Exception:
        fav = "—"
    created = u.get("created_at", 0)
    age = ""
    if created:
        days = max(1, (now_ts() - int(created)) // 86400)
        age = f"{fmt_num(days)} روز با ما"
    # (۹.۰) تعداد Achievement از کل پایه + V11 + سفارشی ادمین
    ach_total = v9_ach_total()
    ach_count = sum(1 for k in u.get("achievements", []) if k in ACHIEVEMENTS_BASE or k in ACHIEVEMENTS_V11)
    # 1.1.0 — Rank و Level Tier
    rank_name, rank_icon, _ = rank_for_xp(xp)
    lv_tier, _ = level_tier(level)
    # 1.1.0 — Daily Streak و آخرین فعالیت
    daily_streak = int(u.get("daily_streak", 0))
    last_active = int(u.get("last_active", 0))
    last_active_str = "—"
    if last_active:
        try:
            diff = max(0, now_ts() - last_active)
            if diff < 60:
                last_active_str = "همین الان"
            elif diff < 3600:
                last_active_str = f"{diff // 60} دقیقه پیش"
            elif diff < 86400:
                last_active_str = f"{diff // 3600} ساعت پیش"
            else:
                last_active_str = f"{diff // 86400} روز پیش"
        except Exception:
            pass
    # 1.1.0 — Frame انتخابی
    frame_key = str(u.get("frame", "default") or "default")
    frame_name = FRAMES_SHOP.get(frame_key, {}).get("name", "⚪ ساده")
    badge_key = str(u.get("badge", "") or "")
    badge_name = BADGES_SHOP.get(badge_key, {}).get("name", "") if badge_key else ""
    # 1.1.0 — آمار جدید
    private_games = int(u.get("private_games", 0))
    private_wins = int(u.get("private_wins", 0))
    tournaments_joined = int(u.get("tournaments_joined", 0))
    tournaments_won = int(u.get("tournaments_won", 0))
    survival_best = int(u.get("survival_best", 0))
    friends_count = len(u.get("friends", []))
    rivals_count = len(u.get("rivals", []))
    referrals_count = len(u.get("referrals", []))
    # 1.1.0 — درصد موفقیت
    wins = int(u.get("wins", 0))
    losses = int(u.get("losses", 0))
    games = int(u.get("games", 0))
    success_rate = (wins * 100 // games) if games > 0 else 0
    # 1.1.0 — فصل
    season_xp = int(u.get("season_xp", 0))
    best_season_rank = int(u.get("best_season_rank", 999))
    season_rank_disp = f"#{best_season_rank}" if best_season_rank < 999 else "—"
    # (۹.۰) کارت بازیکن تطبیقی — موبایل: تمیز و ستونی | دسکتاپ: قاب لوکس
    wide = dm_wide()
    if wide:
        _lines = [
            ds_top(),
            f"│  🪪 <b>کارت بازیکن — {escape(str(u.get('name') or 'بازیکن'))}</b>",
            f"│  {gender_icon(uid)} {escape(title_disp)}"
            + (f" · {frame_name}" if frame_name else "")
            + (f" · 🎖 {badge_name}" if badge_name else ""),
            ds_sep(),
            f"│  🔥 سطح <b>{pnum(level)}</b> · {lv_tier}",
            f"│  {pbar(xp - floor_xp, 100, 12)} <i>({pnum(xp - floor_xp)}/۱۰۰)</i>",
            f"│  {rank_icon} رنک <b>{rank_name}</b> · ⭐ {pnum(xp)} XP",
            ds_row("🪙 سکه", pnum(int(u.get('coins', 0)))),
            ds_sep("⋆"),
            ds_section("🎮", "آمار بازی"),
            ds_row("🎮 بازی‌ها", pnum(games)),
            ds_row("🏆 برد / 💔 باخت", f"{pnum(wins)} / {pnum(losses)}"),
            f"│  📊 نرخ موفقیت {pbar(success_rate, 100, 10, pct=False)} <b>{fa(success_rate)}٪</b>",
            ds_row("🔥 بهترین استریک", pnum(int(u.get('best_streak', 0)))),
            ds_row("🤝 دوئل", pnum(int(u.get('duels', 0)))),
            ds_row("👑 باس‌ها", pnum(int(u.get('boss', 0)))),
            ds_sep("⋆"),
            ds_section("🎯", "مسابقات"),
            ds_row("🎮 خصوصی (برد)", f"{pnum(private_games)} ({pnum(private_wins)})"),
            ds_row("🏆 مسابقات (قهرمانی)", f"{pnum(tournaments_joined)} ({pnum(tournaments_won)})"),
            ds_row("🔥 رکورد بقا", pnum(survival_best)),
            ds_sep("⋆"),
            ds_section("💞", "اجتماعی"),
            ds_row("👥 دوستان", pnum(friends_count)),
            ds_row("⚔️ رقبا", pnum(rivals_count)),
            ds_row("🎁 دعوت‌شده‌ها", pnum(referrals_count)),
            ds_row("📚 موضوع محبوب", fav),
            ds_row("🎒 کالاها", pnum(inv_count)),
            ds_row("🎖 دستاوردها", f"{pnum(ach_count)}/{pnum(ach_total)}"),
            ds_sep("⋆"),
            ds_section("🌐", "فصل و فعالیت"),
            ds_row("⭐ XP فصل", pnum(season_xp)),
            ds_row("🏆 بهترین رتبه", fa(season_rank_disp)),
            ds_row("📅 استریک روزانه", f"{pnum(daily_streak)} روز"),
            ds_row("⏰ آخرین فعالیت", last_active_str),
        ]
    else:
        # موبایل: بدون قاب عمودی و بدون نقطه‌چین — هر سطر تمیز و مستقل
        _id_line = " ".join(x for x in [gender_icon(uid), escape(title_disp)] if x) \
            + (f" · {frame_name}" if frame_name else "") \
            + (f" · 🎖 {badge_name}" if badge_name else "")
        _lines = [
            ds_top("🪪"),
            f"👤 <b>{escape(str(u.get('name') or 'بازیکن'))}</b>",
            _id_line,
            ds_sep(),
            f"🔥 سطح <b>{pnum(level)}</b> · {lv_tier}",
            f"{pbar(xp - floor_xp, 100, 10)} <i>{pnum(xp - floor_xp)}/۱۰۰</i>",
            f"{rank_icon} رنک <b>{rank_name}</b> · ⭐ {pnum(xp)} XP",
            "",
            ds_section("🎮", "آمار بازی"),
            ds_row("🎮 بازی‌ها", pnum(games)),
            ds_row("🏆 برد / 💔 باخت", f"{pnum(wins)} / {pnum(losses)}"),
            f"📊 نرخ موفقیت {pbar(success_rate, 100, 10, pct=False)} <b>{fa(success_rate)}٪</b>",
            ds_row("🔥 بهترین استریک", pnum(int(u.get('best_streak', 0)))),
            ds_row("🤝 دوئل", pnum(int(u.get('duels', 0)))),
            ds_row("👑 باس‌ها", pnum(int(u.get('boss', 0)))),
            "",
            ds_section("🎯", "مسابقات"),
            ds_row("🎮 خصوصی (برد)", f"{pnum(private_games)} ({pnum(private_wins)})"),
            ds_row("🏆 مسابقات (قهرمانی)", f"{pnum(tournaments_joined)} ({pnum(tournaments_won)})"),
            ds_row("🔥 رکورد بقا", pnum(survival_best)),
            "",
            ds_section("💞", "اجتماعی"),
            ds_row("👥 دوستان", pnum(friends_count)),
            ds_row("⚔️ رقبا", pnum(rivals_count)),
            ds_row("🎁 دعوت‌شده‌ها", pnum(referrals_count)),
            ds_row("📚 موضوع محبوب", fav),
            ds_row("🎒 کالاها", pnum(inv_count)),
            ds_row("🎖 دستاوردها", f"{pnum(ach_count)}/{pnum(ach_total)}"),
            "",
            ds_section("🌐", "فصل و فعالیت"),
            ds_row("🪙 سکه", pnum(int(u.get('coins', 0)))),
            ds_row("⭐ XP فصل", pnum(season_xp)),
            ds_row("🏆 بهترین رتبه", fa(season_rank_disp)),
            ds_row("📅 استریک روزانه", f"{pnum(daily_streak)} روز"),
            ds_row("⏰ آخرین فعالیت", last_active_str),
        ]
    # ✏️ (۸.۰) بایو — (۹.۰) تطبیقی: بعد از نام کاربر
    bio = str(u.get("bio") or "").strip()
    if bio:
        _lines.insert(2, f"<i>💬 {escape(bio[:120])}</i>" if not wide
                      else f"│  <i>💬 {escape(bio[:120])}</i>")
    # 🖼 (۸.۰) ویترین
    sc = u.get("showcase") or []
    if sc:
        sc_names = [SHOP_ITEMS.get(k, {}).get("name", "") for k in sc if SHOP_ITEMS.get(k)]
        sc_names = [n for n in sc_names if n]
        if sc_names:
            _line_sc = ("│  🖼 " if wide else "🖼 ") + " · ".join(sc_names[:3])
            _lines.insert(3 + (1 if bio else 0), _line_sc)
    # 🏆 (۸.۰) نشان‌های رتبه
    try:
        _pm_t = pm_tier(pm_elo_get(uid))
        _mm_t = mm_tier(int(u.get("elo_rating", 1000)))
        _line_tier = (f"🏆 {_pm_t[0]} دوئل {pnum(pm_elo_get(uid))} · {_mm_t[0]} آرنا {pnum(u.get('elo_rating', 1000))}")
        _lines.insert(4 + (1 if bio else 0) + (1 if sc else 0),
                      ("│  " + _line_tier) if wide else _line_tier)
    except Exception:
        pass
    if age:
        _lines.append(("│  🎂 " if wide else "🎂 ") + age)
    _lines += [
        ds_close(),
        f"📦 <i>ApexRival نسخه {fa(VERSION)} — {DS_VER}</i>",
    ]
    return "\n".join(_lines)


async def cmd_apexprofile(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    if is_banned(int(user.id)) and not is_admin(int(user.id)):
        await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
        return
    target = getattr(msg.reply_to_message, "from_user", None) if msg.reply_to_message else None
    uid = int(target.id) if target else int(user.id)
    await msg.reply_text(profile_text(uid), parse_mode=ParseMode.HTML,
                         reply_markup=kb([[btn("🎖 دستاوردها", "P|ACH"), btn("🛍 فروشگاه", "S|HOME")]]))


async def profile_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """روتر کالبک‌های پروفایل و رتبه‌بندی — تایتان (۸.۰)."""
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    if action == "PROFILE":
        await safe_answer_query(query)
        await safe_edit(query, profile_text(uid),
                        kb([
                            [btn("🎖 دستاوردها", "P|ACH"), btn("📊 کارنامه‌ی بازی‌ها", "P|REPORT", "primary")],
                            [btn("✏️ بیو بنویس", "P|BIO"), btn("🖼 ویترین", "P|SHOWCASE")],
                            [btn("📜 تاریخچه بازی", "GH|HOME"), btn("🛍 فروشگاه", "S|HOME")],
                            [btn("❓ راهنمای پروفایل", "GD|PROFILE")],
                            nav_footer(),
                        ]))
        return
    if action == "REPORT":
        await safe_answer_query(query)
        await profile_report_card(query, uid)
        return
    if action == "BIO":
        # حالت ورود متن بایو
        await safe_answer_query(query, "✏️ حالا بیویت را بنویس و بفرست (حداکثر ۱۲۰ حرف)")
        DATA.setdefault("_await_bio", {})[str(uid)] = True
        await safe_edit(query,
            f"{ds_top('✏️')}\n│  ✏️ <b>بیوی پروفایل</b>\n{ds_sep()}\n"
            "│  بیویت را همین حالا به‌صورت یک پیام بفرست.\n"
            "│  هر چیزی که دوست داری درباره‌ی خودت بگو —\n"
            "│  روی کارت پروفایلت نمایش داده می‌شود.\n"
            "│  (حداکثر ۱۲۰ حرف · «پاک کن» = حذف بایو)",
            kb([[btn("🧹 پاک کردن بایو", "P|BIOCLEAR")], nav_footer()]))
        return
    if action == "BIOCLEAR":
        get_user(int(uid)).pop("bio", None)
        await safe_answer_query(query, "🧹 بایو پاک شد!")
        await safe_edit(query, profile_text(uid),
                        kb([
                            [btn("🎖 دستاوردها", "P|ACH"), btn("📊 کارنامه‌ی بازی‌ها", "P|REPORT", "primary")],
                            [btn("✏️ بیو بنویس", "P|BIO"), btn("🖼 ویترین", "P|SHOWCASE")],
                            [btn("📜 تاریخچه بازی", "GH|HOME"), btn("🛍 فروشگاه", "S|HOME")],
                            [btn("❓ راهنمای پروفایل", "GD|PROFILE")],
                            nav_footer(),
                        ]))
        return
    if action == "SHOWCASE":
        await safe_answer_query(query)
        await profile_showcase(query, uid)
        return
    if action == "SHOWCASESET" and len(parts) > 2:
        key = parts[2]
        u = get_user(int(uid))
        sc = u.setdefault("showcase", [])
        if key in sc:
            sc.remove(key)
            await safe_answer_query(query, "🔻 از ویترین برداشته شد")
        else:
            if len(sc) >= 3:
                await safe_answer_query(query, "🖼 ویترین فقط ۳ جا دارد — اول یکی را بردار!")
                return
            sc.append(key)
            await safe_answer_query(query, "🖼 به ویترین اضافه شد!")
        await profile_showcase(query, uid)
        return
    if action == "TOP":
        await safe_answer_query(query)
        await cmd_apextop_fake(query)
        return
    if action == "ACH":
        await achievements_show(update, context, query=query)
        return
    # اکشن‌های اضافی برای پروفایل
    if action == "EDIT":
        await safe_answer_query(query, "برای تغییر نام از /apexname استفاده کن")
        return
    await safe_answer_query(query)


async def profile_report_card(query, uid: int) -> None:
    """📊 کارنامه‌ی کامل بازی‌ها — آمار تک‌تک بخش‌ها (۸.۰)."""
    try:
        u = get_user(int(uid))
        pm_rec = pm_matchup_record(uid)
        pm_elo = pm_elo_get(uid)
        pm_t = pm_tier(pm_elo)
        elo = int(u.get("elo_rating", 1000))
        mm_t = mm_tier(elo)
        sv = u.get("sv_records", {})
        mg_b = u.get("mg_best", {})
        ln = u.get("ln_stats", {})
        ttt = u.get("tournaments_joined", 0)
        lines = [
            ds_top("📊"),
            "│  📊 <b>کارنامه‌ی بازی‌های من</b>",
            ds_sep(),
            "│  ▎⚔️ <b>دوئل خصوصی</b>",
            f"│  {pm_t[0]} {pm_t[1]} · Elo {pnum(pm_elo)}",
            f"│  🏆 {pnum(pm_rec['w'])} برد · {pnum(pm_rec['l'])} باخت · {pnum(pm_rec['d'])} مساوی",
            ds_sep("⋆"),
            "│  ▎🏆 <b>آرنا (رنک‌دار)</b>",
            f"│  {mm_t[0]} {mm_t[1]} · Elo {pnum(elo)}",
            f"│  🏆 {pnum(u.get('matchmaking_wins', 0))} برد · {pnum(u.get('matchmaking_losses', 0))} باخت"
            + (f" · 🔥 {pnum(u.get('mm_streak', 0))} برد پیاپی" if int(u.get("mm_streak", 0)) >= 2 else ""),
            ds_sep("⋆"),
            "│  ▎🔥 <b>بقای تایتان</b>",
        ]
        for d, cfg in SV_DIFFS.items():
            r = sv.get(d) or {}
            if int(r.get("day", 0)) > 0:
                lines.append(f"│  {cfg['icon']} {cfg['name']}: روز {pnum(r.get('day', 0))} · {pnum(r.get('points', 0))} امتیاز")
        if not sv:
            lines.append("│  هنوز ماجراجویی‌ای ثبت نشده!")
        lines += [
            ds_sep("⋆"),
            "│  ▎🕹 <b>مرکز بازی‌ها</b>",
            f"│  🎮 {pnum(u.get('mini_games_played', 0))} بازی · 🏆 {pnum(u.get('mini_games_won', 0))} برد",
        ]
        mg_notables = []
        if int(mg_b.get("trivia", 0)) > 0:
            mg_notables.append(f"🧠 زنجیره {pnum(mg_b['trivia'])}")
        if int(mg_b.get("simon", 0)) > 0:
            mg_notables.append(f"🎵 مرحله {pnum(mg_b['simon'])}")
        if int(mg_b.get("mine", 0)) > 0:
            mg_notables.append(f"⛏ ضریب {pnum(mg_b['mine']) // 100}×")
        if int(mg_b.get("reaction_ms", 0)) > 0:
            mg_notables.append(f"⚡ {pnum(mg_b['reaction_ms'])}ms")
        if mg_notables:
            lines.append("│  " + " · ".join(mg_notables))
        lines += [
            ds_sep("⋆"),
            "│  ▎🎰 <b>کازینو</b>",
            f"│  🎲 {pnum(ln.get('spins', 0))} شرط · 💎 {pnum(ln.get('jackpots', 0))} جکپات"
            + (f" · {'🟢 +' if int(ln.get('net', 0)) >= 0 else '🔴 '}{pnum(ln.get('net', 0))}" if ln else ""),
            ds_sep("⋆"),
            "│  ▎🤝 <b>جمعی</b>",
            f"│  👥 {pnum(u.get('team_battles', 0))} نبرد تیمی برنده · 🏅 {pnum(ttt)} تورنمنت",
            f"│  🎮 {pnum(u.get('games', 0))} بازی گروهی · 🏆 {pnum(u.get('wins', 0))} برد",
        ]
        lines.append(ds_close("📊"))
        await safe_edit(query, "\n".join(lines), kb([
            [btn("🪪 پروفایل من", "P|PROFILE", "primary")],
            nav_footer(),
        ]))
    except Exception as exc:
        log_event("error", "system", f"profile_report_card failed: {exc!r}")


async def profile_showcase(query, uid: int) -> None:
    """🖼 ویترین پروفایل — سه جای نشان‌دار (۸.۰)."""
    try:
        u = get_user(int(uid))
        sc = u.setdefault("showcase", [])
        # کاندیدها: لقب‌ها + قاب‌ها + آیتم‌های موجودی
        candidates = []
        for key, d in SHOP_ITEMS.items():
            if d.get("cat") in ("title", "theme", "power"):
                if d.get("kind") == "power" and int(u.get("inventory", {}).get(str(d.get("value")), 0)) <= 0:
                    continue
                candidates.append((key, d["name"]))
        lines = [
            ds_top("🖼"),
            ds_head("🖼", "ویترین پروفایل", "سه کالای محبوبت روی کارتت می‌درخشند"),
            ds_sep("⋆"),
            ds_section("✅", "انتخاب‌های فعلی"),
        ]
        if sc:
            for k in sc:
                d = SHOP_ITEMS.get(k)
                if d:
                    lines.append(f"🖼 {d['name']}")
        else:
            lines.append("— ویترین خالی است")
        rows = []
        pair = []
        for key, name in candidates[:16]:
            mark = "✅ " if key in sc else "▫️ "
            pair.append(btn(mark + name.split(" ", 1)[-1], f"P|SHOWCASESET|{key}"))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)
        rows.append([btn("🪪 پروفایل من", "P|PROFILE", "primary")])
        rows.append(nav_footer())
        await safe_edit(query, "\n".join(lines), kb(rows))
    except Exception as exc:
        log_event("error", "system", f"profile_showcase failed: {exc!r}")


async def cmd_apextop_fake(query) -> None:
    """نمایش رتبه‌بندی داخل پنل (بدون پیام جدید)."""
    weekly = weekly_board(10)
    alltime = sorted(
        [(int(k), int(v.get("xp", 0))) for k, v in DATA.get("users", {}).items() if isinstance(v, dict)],
        key=lambda x: -x[1],
    )[:10]
    wk_lines = "\n".join(
        f"{['🥇','🥈','🥉'][i] if i < 3 else f'{fmt_num(i+1)}.'} {mention_user(u, name_of(u))} · ⭐ {fmt_num(xp)}"
        for i, (u, xp) in enumerate(weekly)
    ) or "هنوز کسی این هفته XP نگرفته."
    at_lines = "\n".join(
        f"{['🥇','🥈','🥉'][i] if i < 3 else f'{fmt_num(i+1)}.'} {mention_user(u, name_of(u))} · ⭐ {fmt_num(xp)}"
        for i, (u, xp) in enumerate(alltime)
    ) or "هنوز کسی بازی نکرده."
    await safe_edit(
        query,
        "🏆 <b>رتبه‌بندی</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"📅 <b>این هفته</b>\n{wk_lines}\n\n♾ <b>همه‌ی زمان‌ها</b>\n{at_lines}",
        kb([[btn("⬅️ منوی اصلی", "H|HOME")]]),
    )


