async def admin_ads_home(query) -> None:
    ads = v24_store().get("ads", [])
    cfg = v24_store().get("ads_cfg", {})
    lines = []
    for i, ad in enumerate(ads):
        if not isinstance(ad, dict):
            continue
        on = "🟢" if ad.get("on") else "🔴"
        lines.append(f"{on} {fmt_num(i+1)}. {escape(str(ad.get('text', ''))[:40])}")
    await safe_answer_query(query)
    await safe_edit(
        query,
        "📢 <b>مدیریت تبلیغات</b>\n━━━━━━━━━━━━━━━━━━\n"
        f"⚙️ هر <b>{fmt_num(int(cfg.get('every', 10)))}</b> پیامِ محتوا یک بار\n"
        f"زیر سوال‌ها: {'✅' if cfg.get('on_question', True) else '❌'} · زیر بازی‌های مهمانی: {'✅' if cfg.get('on_party', True) else '❌'}\n\n"
        + ("\n".join(lines) if lines else "فعلاً تبلیغی ثبت نشده."),
        kb([
            [btn("➕ تبلیغ جدید", "A|ADADD"), btn("🔢 تناوب", "A|ADFREQ")],
            [btn("🔻 حذف تبلیغ", "A|ADDEL")],
            nav_row("A|HOME"),
        ]),
    )


async def admin_ads_action(query, parts) -> None:
    action = parts[1]
    if action == "ADADD":
        await safe_answer_query(query)
        await query.message.reply_text(
            "➕ <b>تبلیغ جدید</b>\n"
            "متن تبلیغ را بفرست. اگر لینک داری، در آخر خط جدا بنویس:\n"
            "<code>متن تبلیغ\nhttps://example.com</code>",
            parse_mode=ParseMode.HTML,
        )
        ads_input_mode(query)["mode"] = "ad_text"
        return
    if action == "ADDEL":
        ads = [a for a in v24_store().get("ads", []) if isinstance(a, dict)]
        if not ads:
            await safe_answer_query(query, "تبلیغی برای حذف نیست.")
            return
        rows = [[btn(f"🗑 {escape(str(a.get('text', ''))[:30])}", f"A|ADDELX|{i}")] for i, a in enumerate(ads)]
        rows.append(nav_row("A|ADS"))
        await safe_answer_query(query)
        await safe_edit(query, "🗑 کدام تبلیغ حذف شود؟", kb(rows))
        return
    if action == "ADDELX":
        try:
            idx = int(parts[2])
        except Exception:
            idx = -1
        ads = v24_store().get("ads", [])
        if 0 <= idx < len(ads):
            ads.pop(idx)
            save_data(force=True)
            await safe_answer_query(query, "حذف شد 🗑")
        else:
            await safe_answer_query(query, "نامعتبر.")
        await admin_ads_home(query)
        return
    if action == "ADTOG":
        try:
            idx = int(parts[2])
        except Exception:
            idx = -1
        ads = v24_store().get("ads", [])
        if 0 <= idx < len(ads) and isinstance(ads[idx], dict):
            ads[idx]["on"] = not bool(ads[idx].get("on"))
            save_data()
            await safe_answer_query(query, "تغییر کرد ✅")
        await admin_ads_home(query)
        return
    if action == "ADFREQ":
        await safe_answer_query(query)
        await query.message.reply_text("🔢 هر چند پیامِ محتوا یک بار تبلیغ بیاید؟ عدد را بفرست:", parse_mode=ParseMode.HTML)
        ads_input_mode(query)["mode"] = "ad_freq"
        return
    await safe_answer_query(query)


_ADS_INPUT = {"mode": ""}


def ads_input_mode(query) -> dict:
    return _ADS_INPUT


def ads_footer(chat_id: int, placement: str) -> str:
    """موتور تبلیغ: هر N پیام محتوا، یک تبلیغ فعال."""
    try:
        cfg_all = v24_store().get("group_cfg", {})
        gcfg = cfg_all.get(group_key(chat_id), {})
        if not gcfg.get("ads", True):
            return ""
        cfg = v24_store().get("ads_cfg", {})
        key_ok = {"question": "on_question", "party": "on_party"}.get(placement)
        if key_ok and not cfg.get(key_ok, True):
            return ""
        ads = [a for a in v24_store().get("ads", []) if isinstance(a, dict) and a.get("on")]
        if not ads:
            return ""
        every = max(1, int(cfg.get("every", 10)))
        # شمارنده سراسری
        _AD_STATE["n"] = int(_AD_STATE.get("n", 0)) + 1
        if _AD_STATE["n"] % every != 0:
            return ""
        ad = random.choice(ads)
        text = f"📢 {escape(str(ad.get('text', '')))}"
        url = str(ad.get("url", "") or "")
        if url:
            text += f'\n➡️ {escape(url)}'
        return text
    except Exception:
        return ""


_AD_STATE: dict = {"n": 0}


# -----------------------------
#  پیام همگانی (Broadcast)
# -----------------------------
_BC_STATE: dict = {"mode": "", "text": "", "photo": None, "url": "", "url_label": "", "targets": "all", "preview": False}


async def admin_bc_home(query) -> None:
    await safe_answer_query(query)
    users_count = len(DATA.get("users", {}))
    lines = [
        ds_top("📡"),
        "│  📡 <b>پیام همگانی</b>",
        "│  <i>مخابرات مرکزی — ارسال به همه</i>",
        ds_sep(),
        ds_row("👥 گیرندگان", f"{pnum(users_count)} کاربر"),
        ds_sep("⋆"),
        "│  🧭 مسیر ویزارد:",
        "│  متن ← عکس (اختیاری) ← دکمه لینک (اختیاری)",
        "│  ← پیش‌نمایش ← ارسال",
        ds_close("📡"),
    ]
    await safe_edit(
        query,
        "\n".join(lines),
        kb([
            [btn("✍️ شروع پیام جدید", "A|BCNEW")],
            [btn("📜 تاریخچه", "A|BCHIST")],
            nav_row("A|HOME"),
        ]),
    )


async def admin_bc_action(update, context, query, parts) -> None:
    action = parts[1]
    if action == "BCNEW":
        _BC_STATE.clear()
        _BC_STATE.update({"mode": "text", "text": "", "photo": None, "url": "", "url_label": "", "targets": "all"})
        await safe_answer_query(query)
        await query.message.reply_text(
            "✍️ <b>متن پیام همگانی</b> را بفرست (HTML مجاز است):",
            parse_mode=ParseMode.HTML,
        )
        return
    if action == "BCPHOTO":
        await safe_answer_query(query)
        _BC_STATE["mode"] = "photo"
        await query.message.reply_text("📷 عکس را بفرست، یا /skip بزن:", parse_mode=ParseMode.HTML)
        return
    if action == "BCURL":
        await safe_answer_query(query)
        _BC_STATE["mode"] = "url"
        await query.message.reply_text("🔗 لینک دکمه را بفرست (یا /skip):", parse_mode=ParseMode.HTML)
        return
    if action == "BCTARGET":
        await safe_answer_query(query)
        _BC_STATE["mode"] = "targets"
        await query.message.reply_text(
            "🎯 گیرندگان؟\n<code>all</code> = همه · <code>active</code> = فعال‌ها (بازی داشته) · عدد = حداقل سطح",
            parse_mode=ParseMode.HTML,
        )
        return
    if action == "BCPREVIEW":
        await safe_answer_query(query)
        await bc_render_preview(context, int(query.from_user.id), query)
        return
    if action == "BCSEND":
        await safe_answer_query(query)
        await bc_send_all(update, context, query)
        return
    if action == "BCHIST":
        log = DATA.get("broadcast_log", [])[-5:]
        lines = []
        for e in log:
            if not isinstance(e, dict):
                continue
            lines.append(f"• {escape(str(e.get('ts_date', '')))} → {fmt_num(int(e.get('sent', 0)))} نفر ({escape(str(e.get('snippet', ''))[:30])})")
        await safe_answer_query(query)
        await safe_edit(
            query,
            "📜 <b>تاریخچه‌ی پیام‌های همگانی</b>\n━━━━━━━━━━━━━━━━━━\n" + ("\n".join(lines) if lines else "هنوز پیامی نفرستاده‌ای."),
            kb([nav_row("A|BC")]),
        )
        return
    await safe_answer_query(query)


async def bc_render_preview(context, admin_id: int, query=None) -> None:
    text = str(_BC_STATE.get("text") or "(متنی وارد نشده)")
    markup = None
    if _BC_STATE.get("url"):
        markup = kb([[InlineKeyboardButton(str(_BC_STATE.get("url_label") or "باز کن"), url=str(_BC_STATE["url"]))]])
    try:
        if _BC_STATE.get("photo"):
            await context.bot.send_photo(admin_id, _BC_STATE["photo"], caption=text,
                                         parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await context.bot.send_message(admin_id, text, parse_mode=ParseMode.HTML,
                                           reply_markup=markup, disable_web_page_preview=True)
    except Exception:
        await context.bot.send_message(admin_id, text, parse_mode=ParseMode.HTML)
    if query is not None:
        await safe_edit(query,
            f"{ds_top('👁')}\n"
            f"│  👁 <b>پیش‌نمایش بالا رفت!</b>\n"
            f"│  <i>همین شکلی به کاربرا می‌رسه</i>\n"
            f"{ds_close('👁')}",
                        kb([[btn("🚀 ارسال به همه", "A|BCSEND")], [btn("✏️ از اول", "A|BCNEW")], nav_row("A|BC")]))


async def bc_send_all(update, context, query) -> None:
    text = str(_BC_STATE.get("text") or "")
    if not text.strip():
        await query.message.reply_text("⚠️ متنی نیست! از اول شروع کن.")
        return
    targets_mode = str(_BC_STATE.get("targets") or "all")
    recipients = []
    for k, u in DATA.get("users", {}).items():
        if not isinstance(u, dict) or u.get("banned"):
            continue
        try:
            uid = int(k)
        except Exception:
            continue
        if targets_mode == "active" and int(u.get("games", 0)) < 1:
            continue
        if targets_mode.isdigit() and int(u.get("level", 1)) < int(targets_mode):
            continue
        recipients.append(uid)
    markup = None
    if _BC_STATE.get("url"):
        markup = kb([[InlineKeyboardButton(str(_BC_STATE.get("url_label") or "باز کن"), url=str(_BC_STATE["url"]))]])
    total = len(recipients)
    # پیام پیشرفت زنده — با نوار پیشرفت گرادیانی
    progress_msg = None
    try:
        progress_msg = await context.bot.send_message(
            int(query.from_user.id),
            f"{ds_top('📡')}\n"
            f"│  📡 <b>ارسال همگانی شروع شد...</b>\n"
            f"│  {pbar(0, max(1, total), 14)}\n"
            f"│  ✅ ۰ · ❌ ۰ · مجموع ۰/{pnum(total)}\n"
            f"{ds_close('📡')}",
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        progress_msg = None
    sent = failed = 0
    for i, uid in enumerate(recipients, 1):
        try:
            if _BC_STATE.get("photo"):
                await context.bot.send_photo(uid, _BC_STATE["photo"], caption=text,
                                             parse_mode=ParseMode.HTML, reply_markup=markup)
            else:
                bc_m = await context.bot.send_message(uid, text, parse_mode=ParseMode.HTML,
                                               reply_markup=markup, disable_web_page_preview=True)
                # 🧹 تک‌پیام: نامه‌ی همگانی هرگز با دستور بعدی کاربر پاک نمی‌شود
                ui_hold(uid, bc_m.message_id)
            sent += 1
        except Exception:
            failed += 1
        # به‌روزرسانی زنده‌ی نوار پیشرفت هر ۲۵ گیرنده
        if progress_msg is not None and (i % 25 == 0 or i == total):
            try:
                await progress_msg.edit_text(
                    f"{ds_top('📡')}\n"
                    f"│  📡 <b>در حال ارسال...</b>\n"
                    f"│  {pbar(i, max(1, total), 14)}\n"
                    f"│  ✅ {pnum(sent)} · ❌ {pnum(failed)} · مجموع {pnum(i)}/{pnum(total)}\n"
                    f"{ds_close('📡')}",
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
        await asyncio.sleep(0.05)
    with LOCK:
        DATA.setdefault("broadcast_log", []).append({
            "ts": now_ts(),
            "ts_date": datetime.now(timezone.utc).strftime("%Y-%m-%d"),
            "sent": sent,
            "failed": failed,
            "snippet": text[:60],
        })
    save_data(force=True)
    audit("broadcast", int(query.from_user.id), None, f"sent={sent} failed={failed}")
    try:
        await context.bot.send_message(
            int(query.from_user.id),
            f"{ds_top('📊')}\n"
            f"│  📊 <b>گزارش نهایی ارسال</b>\n"
            f"│  <i>عملیات مخابراتی کامل شد!</i>\n"
            f"{ds_sep()}\n"
            + ds_row("✅ موفق", pnum(sent)) + "\n"
            + ds_row("❌ ناموفق", pnum(failed)) + "\n"
            + ds_row("👥 کل گیرندگان", pnum(total)) + "\n"
            + ds_row("📈 نرخ موفقیت", f"{fa(int(sent * 100 / max(1, total)))}٪") + "\n"
            + ds_close("📊"),
            parse_mode=ParseMode.HTML,
        )
    except Exception:
        pass
    _BC_STATE.clear()
    _BC_STATE.update({"mode": ""})


async def admin_text_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """ورودی‌های متنی ویزاردهای ادمین (broadcast/ads/user-action)."""
    msg = update.message
    user = update.effective_user
    chat = update.effective_chat
    if msg is None or user is None or chat is None or chat.type != "private":
        return False
    if not is_admin(int(user.id)):
        return False
    text = (msg.text or "").strip()
    photo = msg.photo

    # --- (۹.۰) ویزاردهای اُمگا+ ---
    v9mode = _V9_INPUT.get("mode", "")
    v9data = _V9_INPUT.get("data", {})
    if v9mode and text:
        _V9_INPUT["mode"] = ""
        # یادداشت مدیریت کاربر
        if v9mode == "v9_unote":
            tid = int(v9data.get("target", 0))
            u = DATA.get("users", {}).get(str(tid))
            if isinstance(u, dict):
                if text == "پاک":
                    u.pop("admin_note", None)
                    await msg.reply_text("🧹 یادداشت پاک شد.")
                else:
                    u["admin_note"] = text[:400]
                    await msg.reply_text("📝 یادداشت ثبت شد.")
                save_data()
                audit("user_note", int(user.id), tid, "note")
            else:
                await msg.reply_text("⚠️ کاربر پیدا نشد.")
            return True
        # (۱۰.۰) تنظیم لقب کاربر
        if v9mode == "v10_utitle":
            tid = int(v9data.get("target", 0))
            u = DATA.get("users", {}).get(str(tid))
            if isinstance(u, dict):
                if text == "پاک":
                    u.pop("title", None)
                    await msg.reply_text("🧹 لقب پاک شد.")
                else:
                    u["title"] = text[:40]
                    await msg.reply_text(f"🏷 لقب ثبت شد: {escape(text[:40])}",
                                         parse_mode=ParseMode.HTML)
                save_data()
                audit("user_title", int(user.id), tid, text[:40])
            else:
                await msg.reply_text("⚠️ کاربر پیدا نشد.")
            return True
        # (۱۰.۰) مقدار سفارشی هدیه همگانی
        if v9mode == "v10_giftall":
            try:
                amt = max(1, min(100000, int(text)))
            except Exception:
                await msg.reply_text("⚠️ عدد معتبر نیست — دوباره تلاش کن.")
                return True
            users_n = len(DATA.get("users", {}))
            await msg.reply_text(
                og_banner("تأیید هدیه سفارشی", "🎀") + "\n"
                f"🎁 مقدار: <b>+{pnum(amt)}</b>\n"
                f"👥 دریافت‌کنندگان: <b>{pnum(users_n)}</b>\n"
                "نوع هدیه را انتخاب کن:",
                parse_mode=ParseMode.HTML,
                reply_markup=kb([
                    [btn(f"🪙 +{pnum(amt)} سکه", f"A|GIFTALLC|coin|{amt}", "primary")],
                    [btn(f"⭐ +{pnum(amt)} XP", f"A|GIFTALLC|xp|{amt}", "primary")],
                    [btn("✖ انصراف", "A|GIFTALL", "danger")],
                ]))
            return True
        # مقدار سفارشی سکه/XP
        if v9mode == "v9_ucustom":
            tid = int(v9data.get("target", 0))
            kind = str(v9data.get("kind", "coin"))
            try:
                delta = int(text)
            except Exception:
                await msg.reply_text("⚠️ عدد معتبر نیست.")
                return True
            u = DATA.get("users", {}).get(str(tid))
            if not isinstance(u, dict):
                await msg.reply_text("⚠️ کاربر پیدا نشد.")
                return True
            if kind == "coin":
                if delta >= 0:
                    add_coins(tid, delta, u.get("name"))
                else:
                    u["coins"] = max(0, int(u.get("coins", 0)) + delta)
                log_economy(tid, "earn" if delta >= 0 else "spend", abs(delta), "admin_grant")
                audit("admin_coin", int(user.id), None, f"target={tid} delta={delta}")
                await msg.reply_text(f"✅ سکه‌ی {fmt_num(tid)} الان: {fmt_num(int(u.get('coins', 0)))}")
            else:
                if delta >= 0:
                    add_xp(tid, delta, u.get("name"))
                else:
                    u["xp"] = max(0, int(u.get("xp", 0)) + delta)
                    u["level"] = level_for_xp(int(u["xp"]))
                audit("admin_xp", int(user.id), None, f"target={tid} delta={delta}")
                await msg.reply_text(f"✅ XP کاربر {fmt_num(tid)} الان: {fmt_num(int(u.get('xp', 0)))}")
            save_data(force=True)
            return True
        # ساخت کد هدیه
        if v9mode == "v9_gift":
            parts_txt = text.split()
            if len(parts_txt) < 2:
                await msg.reply_text("⚠️ قالب: <code>code amount uses</code>", parse_mode=ParseMode.HTML)
                return True
            code_str = parts_txt[0]
            try:
                amount = int(parts_txt[1])
            except Exception:
                amount = 0
            uses = 1
            if len(parts_txt) > 2:
                try:
                    uses = int(parts_txt[2])
                except Exception:
                    uses = 1
            ok, message = v9_gift_create(code_str, amount, uses, int(user.id))
            await msg.reply_text(("✅ " if ok else "⚠️ ") + message)
            return True
        # دستاورد سفارشی — سه مرحله
        if v9mode == "v9_ach_name":
            _V9_INPUT["mode"] = "v9_ach_desc"
            _V9_INPUT["data"] = {"name": text[:40]}
            await msg.reply_text("✍️ توضیح دستاورد را بفرست (مرحله ۲ از ۳):")
            return True
        if v9mode == "v9_ach_desc":
            _V9_INPUT["mode"] = "v9_ach_reward"
            _V9_INPUT["data"] = {**v9data, "desc": text[:120]}
            await msg.reply_text("🪙 جایزه را بفرست (مرحله ۳ از ۳) — قالب: <code>سکه XP</code>\nمثال: <code>100 50</code>",
                                 parse_mode=ParseMode.HTML)
            return True
        if v9mode == "v9_ach_reward":
            try:
                coins_r = int(text.split()[0]) if text.split() else 0
                xp_r = int(text.split()[1]) if len(text.split()) > 1 else 0
            except Exception:
                coins_r, xp_r = 0, 0
            key = "c_" + bank_hash(str(v9data.get("name", "")) + str(now_ts()))[:8]
            v9_custom_ach_store()[key] = {
                "name": str(v9data.get("name", "")), "icon": "🎖",
                "desc": str(v9data.get("desc", "")), "coins": max(0, coins_r),
                "xp": max(0, xp_r), "created": now_ts()}
            save_data(force=True)
            audit("ach_custom_new", int(user.id), None, f"key={key}")
            await msg.reply_text(
                f"🎖 دستاورد سفارشی «{escape(str(v9data.get('name', '')))}» ساخته شد!\n"
                f"🪙 {pnum(max(0, coins_r))} سکه · ⭐ {pnum(max(0, xp_r))} XP",
                parse_mode=ParseMode.HTML)
            return True
        # اعطای دستاورد
        if v9mode == "v9_achgrant":
            seg = text.split("|")
            if len(seg) != 2 or not seg[0].strip().lstrip("-").isdigit():
                await msg.reply_text("⚠️ قالب: <code>آیدی|کلید</code>", parse_mode=ParseMode.HTML)
                return True
            tuid = int(seg[0].strip())
            akey = seg[1].strip()
            all_ach = v9_all_achievements()
            if akey not in all_ach:
                await msg.reply_text(f"⚠️ کلید «{escape(akey)}» وجود ندارد.")
                return True
            u = get_user(tuid)
            if akey in all_ach and akey not in (ACHIEVEMENTS_BASE.keys() | ACHIEVEMENTS_V11.keys()):
                ok = v9_award_custom(tuid, akey)
                await msg.reply_text("✅ دستاورد سفارشی اعطا شد!" if ok else "⚠️ قبلاً گرفته است!")
            else:
                if akey in u.get("achievements", []):
                    await msg.reply_text("⚠️ این کاربر قبلاً این دستاورد را دارد.")
                    return True
                u.setdefault("achievements", []).append(akey)
                d = all_ach.get(akey, {})
                if int(d.get("coins", 0)) > 0:
                    add_coins(tuid, int(d.get("coins", 0)), u.get("name"))
                if int(d.get("xp", 0)) > 0:
                    add_xp(tuid, int(d.get("xp", 0)), u.get("name"))
                save_data(force=True)
                audit("ach_grant", int(user.id), tuid, f"key={akey}")
                await msg.reply_text("✅ دستاورد اعطا شد!")
            return True
        # افزودن دسترسی
        if v9mode == "v9_adminadd":
            seg = text.split()
            if len(seg) < 2 or not seg[0].lstrip("-").isdigit() or seg[1] not in ("admin", "mod"):
                await msg.reply_text("⚠️ قالب: <code>آیدی admin|mod</code>", parse_mode=ParseMode.HTML)
                return True
            tuid = int(seg[0])
            ok = set_user_role(tuid, seg[1])
            get_user(tuid)
            save_data(force=True)
            audit("perm_add", int(user.id), tuid, f"role={seg[1]}")
            await msg.reply_text(f"✅ {fmt_num(tuid)} → {seg[1]}" if ok else "⚠️ ناموفق")
            return True
        # زمان‌بندی تعمیرات
        if v9mode == "v9_maintsch":
            try:
                mins = max(1, min(1440, int(text)))
            except Exception:
                await msg.reply_text("⚠️ عدد دقیقه معتبر نیست.")
                return True
            DATA["v9_maint_scheduled"] = now_ts() + mins * 60
            save_data(force=True)
            await msg.reply_text(f"🛠 تعمیرات {pnum(mins)} دقیقه دیگر به‌طور خودکار روشن می‌شود.")
            audit("maint_schedule", int(user.id), None, f"in={mins}m")
            return True
        # جست‌وجو در بانک‌ها
        if v9mode == "v9_bksearch":
            term = str(text).strip()
            bank_filter = str(v9data.get("bank", "") or "")
            hits = []
            if len(term) >= 2:
                for bkey, bbank in BANKS.items():
                    if bank_filter and bkey != bank_filter:
                        continue
                    for i, q in enumerate(bbank):
                        if term.lower() in str(q).lower():
                            hits.append((bkey, i, str(q)))
                            if len(hits) >= 40:
                                break
                    if len(hits) >= 40:
                        break
            lines_s = [f"🔍 <b>نتایج «{escape(term[:30])}»</b> — {pnum(len(hits))} یافته",
                       "━━━━━━━━━━━━━━━━━━"]
            for bkey, i, q in hits[:25]:
                lines_s.append(f"🗂 <b>{escape(bkey)}</b> #{pnum(i+1)}: {escape(q[:80])}")
            await msg.reply_text("\n".join(lines_s) if hits else "چیزی پیدا نشد 🤷",
                                 parse_mode=ParseMode.HTML)
            audit("bank_search", int(user.id), None, f"term={term[:40]} hits={len(hits)}")
            return True
        # ساخت بانک جدید
        if v9mode == "v9_bknew":
            name = str(text).strip().lower().replace(" ", "_")
            if not name or not name.replace("_", "").isalnum() or len(name) > 24:
                await msg.reply_text("⚠️ نام معتبر نیست (حروف انگلیسی/عدد/زیرخط، حداکثر ۲۴).")
                return True
            if name in BANKS:
                await msg.reply_text("⚠️ این بانک از قبل وجود دارد.")
                return True
            BANKS[name] = []
            DATA.setdefault("v18_custom_prompts", {})[name] = []
            save_data(force=True)
            apply_bank_admin_changes()
            audit("bank_new", int(user.id), None, f"key={name}")
            await msg.reply_text(f"🗂 بانک «{name}» ساخته شد! حالا سوال اضافه کن.")
            return True
        # جست‌وجوی لاگ
        if v9mode == "v9_logq":
            term = text.lower()
            entries = [e for e in DATA.get("audit", []) if isinstance(e, dict)]
            hits = [e for e in entries[-500:]
                    if term in str(e.get("msg", "")).lower()
                    or term in str(e.get("category", "")).lower()
                    or term == str(e.get("actor", ""))]
            lines_q = [f"🔍 <b>نتایج «{escape(text[:30])}»</b> — {pnum(len(hits))} یافته",
                       "━━━━━━━━━━━━━━━━━━"]
            for e in reversed(hits[-15:]):
                ts = int(e.get("ts", 0))
                t_str = datetime.fromtimestamp(ts).strftime("%m-%d %H:%M") if ts else ""
                lines_q.append(f"{'🔴' if e.get('level') == 'error' else '🟡' if e.get('level') == 'warn' else '🔵'}"
                               f" [{fa(t_str)}] {escape(str(e.get('msg', ''))[:80])}")
            await msg.reply_text("\n".join(lines_q) if hits else "چیزی پیدا نشد 🤷", parse_mode=ParseMode.HTML)
            return True

    # --- اکشن‌های کاربر (XP/سکه/DM/جستجو) ---
    ua = _ADMIN_USER_INPUT.get("action")
    if ua in ("UXP", "UCOIN", "UDM") and (text or ua == "UDM"):
        tid = int(_ADMIN_USER_INPUT.get("target", 0))
        _ADMIN_USER_INPUT["action"] = ""
        u = DATA.get("users", {}).get(str(tid))
        if not isinstance(u, dict):
            await msg.reply_text("⚠️ کاربر دیگر موجود نیست.")
            return True
        if ua == "UXP":
            try:
                delta = int(text)
            except Exception:
                await msg.reply_text("⚠️ عدد معتبر نیست.")
                return True
            add_xp(tid, delta if delta > 0 else 0, u.get("name"))
            if delta < 0:
                u["xp"] = max(0, int(u.get("xp", 0)) + delta)
                u["level"] = level_for_xp(int(u["xp"]))
            save_data(force=True)
            audit("admin_xp", int(user.id), None, f"target={tid} delta={delta}")
            await msg.reply_text(f"✅ XP کاربر {fmt_num(tid)} تغییر کرد: {fmt_num(int(u.get('xp', 0)))}")
            return True
        if ua == "UCOIN":
            try:
                delta = int(text)
            except Exception:
                await msg.reply_text("⚠️ عدد معتبر نیست.")
                return True
            if delta >= 0:
                add_coins(tid, delta, u.get("name"))
            else:
                u["coins"] = max(0, int(u.get("coins", 0)) + delta)
            save_data(force=True)
            audit("admin_coin", int(user.id), None, f"target={tid} delta={delta}")
            await msg.reply_text(f"✅ سکه‌ی کاربر {fmt_num(tid)} تغییر کرد: {fmt_num(int(u.get('coins', 0)))}")
            return True
        if ua == "UDM" and text:
            try:
                dm_m = await context.bot.send_message(tid, f"📩 <b>پیام از پشتیبانی:</b>\n\n{escape(text[:3500])}", parse_mode=ParseMode.HTML)
                # 🧹 تک‌پیام: نامه‌ی پشتیبانی هرگز خودکار پاک نمی‌شود
                ui_hold(tid, dm_m.message_id)
                await msg.reply_text("✅ پیام достав شد.")
            except Exception as exc:
                await msg.reply_text(f"⚠️ ارسال ناموفق: {str(exc)[:80]}")
            audit("admin_dm", int(user.id), None, f"target={tid}")
            return True

    # --- پاسخ به بازخورد (اومگا) ---
    if _FB_REPLY_INPUT.get("active") and text:
        fb_idx = int(_FB_REPLY_INPUT.get("idx", -1))
        _FB_REPLY_INPUT["active"] = False
        feedbacks = DATA.get("feedback", [])
        if 0 <= fb_idx < len(feedbacks) and isinstance(feedbacks[fb_idx], dict):
            fb = feedbacks[fb_idx]
            fb["reply"] = text[:3000]
            fb["status"] = "done"
            fb["replied_by"] = int(user.id)
            fb["replied_ts"] = now_ts()
            save_data(force=True)
            audit("fb_reply", int(user.id), None, f"idx={fb_idx}")
            fb_snippet = str(fb.get("text", ""))[:180]
            sent_ok = False
            try:
                fb_m = await context.bot.send_message(
                    int(fb.get("uid", 0)),
                    f"{ds_top('💬')}\n"
                    "│  💬 <b>پاسخ پشتیبانی رسید!</b>\n"
                    "│  <i>در پاسخ به بازخوردت:</i>\n"
                    f"{ds_sep()}\n"
                    f"│  ▸ {escape(fb_snippet)}\n"
                    f"{ds_sep()}\n"
                    f"│  ✍️ {escape(text[:2400])}\n"
                    f"{ds_close('💬')}\n\n"
                    "💗 از اینکه با ما هم‌صدا شدی ممنونیم!",
                    parse_mode=ParseMode.HTML,
                )
                # 🧹 تک‌پیام: پاسخ پشتیبانی هرگز خودکار پاک نمی‌شود
                ui_hold(int(fb.get("uid", 0)), fb_m.message_id)
                sent_ok = True
            except Exception:
                sent_ok = False
            note = "و برای بازیکن ارسال شد ✅" if sent_ok else "ثبت شد، اما ارسال ناموفق بود ⚠️"
            await msg.reply_text(f"✅ پاسخ ثبت شد — {note}")
        else:
            await msg.reply_text("⚠️ بازخورد دیگر موجود نیست.")
        return True

    # --- جستجوی کاربر با آیدی ---
    if _ADS_INPUT.get("mode") == "user_search" and text:
        _ADS_INPUT["mode"] = ""
        if text.lstrip("-").isdigit():
            tid = int(text)
            fake_q = _FakeQuery(query=msg, uid=int(user.id))
            await admin_user_detail(fake_q, tid)
        else:
            await msg.reply_text("⚠️ فقط آیدی عددی!")
        return True

    # --- تبلیغات ---
    mode = _ADS_INPUT.get("mode")
    if mode == "ad_text" and text:
        _ADS_INPUT["mode"] = ""
        lines = text.split("\n")
        ad_text = lines[0].strip()
        url = lines[1].strip() if len(lines) > 1 else ""
        if not ad_text:
            return True
        v24_store()["ads"].append({"text": ad_text, "url": url, "on": True, "impressions": 0})
        save_data(force=True)
        await msg.reply_text(f"✅ تبلیغ ثبت شد: «{escape(ad_text[:50])}»", parse_mode=ParseMode.HTML)
        return True
    if mode == "ad_freq" and text:
        _ADS_INPUT["mode"] = ""
        try:
            n = max(1, min(100, int(text)))
            v24_store()["ads_cfg"]["every"] = n
            save_data()
            await msg.reply_text(f"✅ تناوب تبلیغ: هر {fmt_num(n)} پیام محتوا.")
        except Exception:
            await msg.reply_text("⚠️ عدد معتبر نیست.")
        return True

    if _ADS_INPUT.get("mode") == "bank_add" and text:
        _ADS_INPUT["mode"] = ""
        key = str(_ADS_INPUT.get("bank", ""))
        if key and key in BANKS:
            clean = text.strip()
            if clean and clean not in BANKS[key]:
                BANKS[key].append(clean)
                store = DATA.setdefault("v18_custom_prompts", {})
                store.setdefault(key, [])
                if clean not in store[key]:
                    store[key].append(clean)
                editor_store()["stats"]["adds"] = int(editor_store()["stats"].get("adds", 0)) + 1
                save_data(force=True)
                await msg.reply_text(f"✅ به بانک <code>{escape(key)}</code> اضافه شد.", parse_mode=ParseMode.HTML)
            else:
                await msg.reply_text("⚠️ خالی یا تکراری است.")
        else:
            await msg.reply_text("⚠️ بانک نامعتبر است.")
        return True

    if _ADS_INPUT.get("mode") == "bank_edit" and text:
        _ADS_INPUT["mode"] = ""
        key = str(_ADS_INPUT.get("bank", ""))
        idx = int(_ADS_INPUT.get("idx", -1))
        bank = BANKS.get(key, [])
        if key and 0 <= idx < len(bank) and text.strip():
            current = bank[idx]
            h = bank_hash(current)
            editor_store()["overrides"].setdefault(key, {})[h] = text.strip()
            bank[idx] = text.strip()
            editor_store()["stats"]["edits"] = int(editor_store()["stats"].get("edits", 0)) + 1
            award_achievement(int(user.id), "v18_bank_editor")
            save_data(force=True)
            await msg.reply_text("✅ سوال ویرایش شد.", parse_mode=ParseMode.HTML)
        else:
            await msg.reply_text("⚠️ ویرایش ناموفق بود.")
        return True

    # --- پیام همگانی ---
    bmode = _BC_STATE.get("mode")
    if bmode == "text" and (text or photo):
        if text:
            _BC_STATE["text"] = text
            _BC_STATE["mode"] = "photo"
            await msg.reply_text("✅ متن ثبت شد.\n📷 حالا عکس بفرست یا /skip بزن:", parse_mode=ParseMode.HTML)
        return True
    if bmode == "photo":
        if photo:
            _BC_STATE["photo"] = photo[-1].file_id
        _BC_STATE["mode"] = "url"
        await msg.reply_text("🔗 لینک دکمه را بفرست (یا /skip):", parse_mode=ParseMode.HTML)
        return True
    if bmode == "url":
        if text and text != "/skip" and text.startswith("http"):
            _BC_STATE["url"] = text
            _BC_STATE["mode"] = "url_label"
            await msg.reply_text("🏷 متن دکمه را بفرست (یا /skip):", parse_mode=ParseMode.HTML)
        else:
            _BC_STATE["mode"] = "targets"
            await msg.reply_text(
                "🎯 گیرندگان؟\n<code>all</code> · <code>active</code> · عدد (حداقل سطح)",
                parse_mode=ParseMode.HTML,
            )
        return True
    if bmode == "url_label":
        if text and text != "/skip":
            _BC_STATE["url_label"] = text[:32]
        _BC_STATE["mode"] = "targets"
        await msg.reply_text(
            "🎯 گیرندگان؟\n<code>all</code> · <code>active</code> · عدد (حداقل سطح)",
            parse_mode=ParseMode.HTML,
        )
        return True
    if bmode == "targets":
        if text:
            _BC_STATE["targets"] = text if text in ("all", "active") or text.isdigit() else "all"
        _BC_STATE["mode"] = ""
        await msg.reply_text("👁 پیش‌نمایش:", parse_mode=ParseMode.HTML)
        await bc_render_preview(context, int(user.id))
        # FIX: قبلاً بعد از پیش‌نمایش هیچ دکمه‌ای نمایش داده نمی‌شد و ادمین
        # راهی برای ارسال نهایی نداشت (bc_render_preview بدون query دکمه نمی‌ساخت).
        # حالا پیام تأیید با دکمه‌ی ارسال ارسال می‌شود.
        try:
            await context.bot.send_message(
                int(user.id),
                "🚀 <b>ارسال نهایی؟</b>",
                parse_mode=ParseMode.HTML,
                reply_markup=kb([
                    [btn("🚀 ارسال به همه", "A|BCSEND")],
                    [btn("✏️ از اول", "A|BCNEW")],
                    [btn("⌂ منوی اصلی", "A|HOME"), btn("✕ بستن", "H|CLOSE")],
                ]),
            )
        except Exception:
            pass
        return True
    return False


async def cmd_skip_wizard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    if not is_admin(int(user.id)):
        return
    if _BC_STATE.get("mode") == "photo":
        _BC_STATE["mode"] = "url"
        await msg.reply_text("🔗 لینک دکمه را بفرست (یا /skip):", parse_mode=ParseMode.HTML)
        return
    if _BC_STATE.get("mode") in ("url", "url_label", "targets"):
        await admin_text_router(update, context)
        return
    await msg.reply_text("چیزی برای رد کردن نیست 🙂")


