# گیت دستورات گروهی: بعضی دستورها فقط در خصوصی معنا دارند
PRIVATE_ONLY_COMMANDS = {
    "shop", "profile", "rank", "help", "menu", "game", "bazi", "start",
    "apexprofile", "apextop", "apexguide", "apexlive", "apexluck",
    "apexquiz", "apexgift", "apexlove2", "apexduel",
}
_group_hint_ts: dict[int, float] = {}


async def group_command_gate(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """حذف خودکار پیام دستورات در گروه + راهنمای دستورات خصوصی."""
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or user is None or chat.type not in ("group", "supergroup"):
        return
    cmd = (msg.text or "").split("@")[0].lstrip("/").split()[0].lower() if msg.text else ""
    # حذف پیام دستور در گروه (اگر تنظیمات فعال باشه)
    if chat_cfg(int(chat.id)).get("delcmd", True) and cmd:
        await safe_delete(msg)
    if cmd not in PRIVATE_ONLY_COMMANDS:
        return
    # ضد اسپم
    now = time.time()
    last = _group_hint_ts.get(int(chat.id), 0)
    if now - last < 45:
        return
    _group_hint_ts[int(chat.id)] = now
    hints = {
        "shop": "🛍 فروشگاه در چت خصوصی من باز است! اول /start بزن بعد /shop",
        "profile": "🪪 پروفایل در خصوصی من ساخته می‌شود؛ اول /start بعد /apexprofile",
        "rank": "🏆 رتبه‌بندی با /apextop همین‌جا کار می‌کند!",
        "help": "❓ راهنمای کامل: /apexhelp — راهنمای تصویری: /apexguide",
        "menu": "🎮 منوی بازی: /apex",
        "game": "🎮 برای ساخت بازی: /apex",
        "bazi": "🎮 برای ساخت بازی: /apex",
        "start": "📩 ثبت‌نام در چت خصوصی من انجام می‌شود؛ /start را در PV بزن.",
        "apexprofile": "🪪 /apexprofile را در چت خصوصی من بزن.",
        "apextop": "🏆 بله همین‌جا کار می‌کند! /apextop",
        "apexguide": "🎓 /apexguide را در خصوصی بزن تا ورق بخوری.",
        "apexlive": "📡 تله‌متری در خصوصی من نمایش داده می‌شود.",
        "apexluck": "🍀 گردونه را در چت خصوصی من بچرخان!",
        "apexquiz": "🧮 کوییز را در چت خصوصی من شروع کن.",
        "apexgift": "🎁 هدیه‌ی سکه را در خصوصی بفرست (Reply روی پیام دوستت).",
        "apexlove2": "💌 عشق‌سنج دو نفره را در خصوصی شروع کن.",
        "apexduel": "🤺 دوئل را اینجا روی پیام حریف Reply کن!",
    }
    hint = hints.get(cmd, "این دستور در چت خصوصی من کار می‌کند 📩")
    try:
        await msg.reply_text(hint)
    except Exception:
        pass


async def group_text_triggers(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """متن‌های کلیدی در گروه: «جرئت و حقیقت»، «مجازات»، «حکم»، «+18»."""
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or chat.type not in ("group", "supergroup"):
        return
    text = (msg.text or "").strip()
    uid = int(user.id) if user else 0
    # --- تریجر «حکم» — سرگروه روی پیام کسی Reply می‌زنه و می‌نویسه «حکم» ---
    if text in ("حکم", "hokm", "حکم!", "حکم."):
        # بررسی Reply
        target_user = getattr(msg.reply_to_message, "from_user", None) if msg.reply_to_message else None
        if target_user is None:
            return
        target_uid = int(target_user.id)
        if target_uid == uid:
            await msg.reply_text("❌ نمی‌تونی به خودت حکم بدی!")
            return
        # بررسی بازی فعال
        game = active_game(int(chat.id))
        if game is None or str(game.get("status")) != "active":
            await msg.reply_text("❌ بازی فعالی نیست! اول /apex بزن.")
            return
        # بررسی اینکه آیا بازیکن در بازی هست
        if target_uid not in [int(x) for x in game.get("players", [])]:
            await msg.reply_text("❌ این بازیکن در بازی نیست!")
            return
        # صدور حکم
        penalty = pick_penalty(game)
        deadline = int(game.get("settings", {}).get("penalty_deadline", 300) or 300)
        target_name = name_of(target_uid, game)
        issuer_name = name_of(uid, game)
        await context.bot.send_message(
            int(chat.id),
            f"☠️ <b>حکم صادر شد!</b>\n"
            f"━━━━━━━━━━━━━━━━━━\n"
            f"🎯 محکوم: {mention_user(target_uid, target_name)}\n"
            f"👨‍⚖️ صادرکننده: {mention_user(uid, issuer_name)}\n"
            f"━━━━━━━━━━━━━━━━━━\n"
            f"⚖️ حکم: <b>{escape(penalty)}</b>\n"
            f"━━━━━━━━━━━━━━━━━━\n"
            f"⏳ مهلت: <b>{fmt_num(deadline // 60)} دقیقه</b>\n"
            f"✅ بعد از انجام، با <b>Reply به همین پیام</b> تأیید کن\n"
            f"🎁 پاداش: +۴ ایکس‌پی و +۲ سکه",
            parse_mode=ParseMode.HTML,
            reply_markup=kb([[btn("✅ انجام شد", f"PN|DONE|{target_uid}_{now_ts()}")]]),
        )
        # ثبت مجازات در داده‌ی بازی
        game["pending_penalties"][str(target_uid)] = {
            "text": penalty,
            "ts": now_ts(),
            "deadline": deadline,
            "done": False,
            "skipped": False,
            "source": "manual_hokm",
            "by": int(uid),
        }
        touch_game(game)
        save_data(force=True)
        # پاک کردن پیام «حکم» کاربر
        if chat_cfg(int(chat.id)).get("delcmd", True):
            await safe_delete(msg)
        return
    # --- تریگر «+18» — روشن/خاموش کردن حالت بزرگسال ---
    if text in ("+18", "+۱۸", "18+", "۱۸+"):
        if not (uid == int(game.get("leader_id", 0)) if (game := active_game(int(chat.id))) else False):
            if not has_permission(int(uid), "admin"):
                # فقط سرگروه یا ادمین
                return
        g = get_group(int(chat.id))
        g["adult_mode"] = not bool(g.get("adult_mode", False))
        save_data(force=True)
        state = "روشن ✅" if g.get("adult_mode") else "خاموش ❌"
        await msg.reply_text(f"🔞 حالت +۱۸: <b>{state}</b>", parse_mode=ParseMode.HTML)
        if chat_cfg(int(chat.id)).get("delcmd", True):
            await safe_delete(msg)
        return
    if text == "جرئت و حقیقت":
        await msg.reply_text(
            "🎯 همین حالا بازی کن! با /apex لابی بساز و ۸۲۸۱ سوال را شروع کنید.",
            parse_mode=ParseMode.HTML,
        )
        return
    if text == "مجازات":
        await msg.reply_text(
            "⚖️ برای مجازات هوشمند، روی پیام مقصر Reply کن و /apexpunish بزن!\n"
            "💡 یا روی پیام کسی Reply کن و بنویس «حکم»",
            parse_mode=ParseMode.HTML,
        )
        return


