def group_cfg_of(chat_id: int) -> dict:
    st = v24_store()
    cfg = st.setdefault("group_cfg", {}).setdefault(group_key(chat_id), {})
    merged = dict(GROUP_SETTINGS_DEFAULTS)
    if isinstance(cfg.get("topics"), dict):
        merged["topics"].update(cfg["topics"])
    else:
        cfg["topics"] = dict(merged["topics"])
    for k in ("welcome", "levelup", "ads"):
        merged[k] = bool(cfg.get(k, merged[k]))
    cfg.clear()
    cfg.update(merged)
    # برگرداندن خودِ dict ذخیره‌شده تا تغییرها (toggle) ماندگار باشند
    return cfg


async def cmd_apexsettings(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or user is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("⚙️ تنظیمات گروه، داخل خود گروه باز می‌شود!")
        return
    # فقط ادمین‌های گروه
    try:
        member = await context.bot.get_chat_member(int(chat.id), int(user.id))
        if member.status not in ("administrator", "creator") and not is_admin(int(user.id)):
            await msg.reply_text("👑 فقط ادمین‌های گروه می‌توانند تنظیمات را تغییر دهند.")
            return
    except Exception:
        pass
    await settings_render(msg, int(chat.id))


async def settings_render(msg, chat_id: int, query=None) -> None:
    cfg = group_cfg_of(chat_id)
    lines = [
        ds_top("⚙️"),
        "│  ⚙️ <b>تنظیمات گروه</b>",
        "│  <i>میز کنترل سرگروه</i>",
        ds_sep(),
        ds_row("👋 خوش‌آمدگویی", "روشن ✅" if cfg['welcome'] else "خاموش ❌"),
        ds_row("🎉 جشن ارتقای سطح", "روشن ✅" if cfg['levelup'] else "خاموش ❌"),
        ds_row("📢 تبلیغات", "روشن ✅" if cfg['ads'] else "خاموش ❌"),
        ds_sep("⋆"),
        "│  ▎📚 موضوعات فعال — روی هرکدوم بزن تا روشن/خاموش بشه:",
    ]
    text = "\n".join(lines)
    off = set(topics_off())
    rows = [
        [btn(f"👋 خوش‌آمد: {'روشن' if cfg['welcome'] else 'خاموش'}", "ST|WELCOME"),
         btn(f"🎉 ارتقا: {'روشن' if cfg['levelup'] else 'خاموش'}", "ST|LEVELUP")],
        [btn(f"📢 تبلیغ: {'روشن' if cfg['ads'] else 'خاموش'}", "ST|ADS")],
    ]
    for key, label in MODE_ORDER:
        if key in ("truth", "dare"):
            continue
        active = key not in off
        rows.append([btn(f"{label} {'✅' if active else '❌'}", f"ST|TOPIC|{key}")])
    rows.append(nav_row("H|CLOSE"))
    markup = kb(rows)
    if query is not None:
        await safe_answer_query(query)
        await safe_edit(query, text, markup)
    else:
        try:
            await msg.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        except Exception:
            pass


async def settings_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None or query.message is None:
        return
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    chat_id = int(query.message.chat.id)
    uid = int(query.from_user.id)
    # فقط ادمین گروه یا ادمین ربات
    is_group_admin = False
    try:
        member = await context.bot.get_chat_member(chat_id, uid)
        is_group_admin = member.status in ("administrator", "creator")
    except Exception:
        pass
    if not (is_group_admin or is_admin(uid)):
        await safe_answer_query(query, "فقط ادمین‌های گروه!", True)
        return
    cfg = group_cfg_of(chat_id)
    if action == "WELCOME":
        cfg["welcome"] = not cfg["welcome"]
    elif action == "LEVELUP":
        cfg["levelup"] = not cfg["levelup"]
    elif action == "ADS":
        cfg["ads"] = not cfg["ads"]
    elif action == "TOPIC":
        key = parts[2] if len(parts) > 2 else ""
        off = topics_off()
        if key in off:
            off.remove(key)
        else:
            off.append(key)
    else:
        await safe_answer_query(query)
        return
    save_data(force=True)
    audit("group_settings", uid, chat_id, action)
    await settings_render(None, chat_id, query=query)


# -----------------------------
#  جشن ارتقای سطح
# -----------------------------
async def celebrate_levelup(update: Update, uid: int) -> None:
    """اگر کاربر در این تعامل سطحش بالا رفته، جشن بگیر."""
    try:
        chat = update.effective_chat
        if chat is None or chat.type not in ("group", "supergroup"):
            return
        pend = DATA.setdefault("v19", {}).setdefault("lvl_pending", {})
        lvl = pend.pop(user_key(uid), None)
        if not lvl:
            return
        if not group_cfg_of(int(chat.id)).get("levelup", True):
            return
        await context_message_reply(update, (
            f"{ds_top('🎉')}\n"
            f"│  🎉 <b>ارتقای سطح!</b>\n"
            f"│  {mention_user(uid, name_of(uid))} به سطح <b>{pnum(int(lvl))}</b> رسید! 🚀\n"
            f"{ds_close('🎉')}"
        ))
    except Exception:
        pass


def context_message_reply(update: Update, text: str) -> Any:
    msg = getattr(update, "message", None)
    if msg is not None:
        return msg.reply_text(text, parse_mode=ParseMode.HTML)
    return _NoReply()


class _NoReply:
    async def __call__(self):
        return None


