        rows = []
        for q in quests:
            if q.get("completed", False) and q.get("key", "") not in claimed:
                rows.append([btn(f"🎁 {q.get('name', '')[:25]}", f"QS|CLMD|daily|{q.get('key', '')}")])
        rows.append([btn("⬅️ بازگشت", "QS|HOME")])
        await safe_edit(query, "\n".join(lines), kb(rows))
