        rows = [[btn("⛏ دوباره", "MG|MINE", "primary"), btn("🏠 مرکز بازی‌ها", "MG|HOME")]]
        await safe_edit(query, f"⛏ <b>مین‌یاب</b>\n━━━━━━━━━━━━━━━━━━\n\n💰 <b>برداشت موفق!</b> +{pnum(pot)} سکه", kb(rows))
