def question_submit(uid: int, qtype: str, text: str) -> bool:
    """ثبت سوال پیشنهادی کاربر."""
    try:
        submission = {
            "id": next_id("feedback"),
            "uid": int(uid),
            "type": str(qtype),  # truth | dare | flirty | ...
            "text": str(text)[:500],
            "ts": now_ts(),
            "status": "pending",  # pending | approved | rejected
            "reviewed_by": 0,
        }
        DATA.setdefault("question_submissions", []).append(submission)
        return True
    except Exception:
        return False


def question_report(uid: int, question: str, reason: str) -> bool:
    """گزارش یک سوال نامناسب."""
    try:
        report = {
            "id": next_id("feedback"),
            "uid": int(uid),
            "question": str(question)[:300],
            "reason": str(reason)[:200],
            "ts": now_ts(),
            "status": "pending",
            "reviewed_by": 0,
        }
        DATA.setdefault("question_reports", []).append(report)
        return True
    except Exception:
        return False


def question_submissions_approve(submission_id: int, admin_uid: int) -> bool:
    """تأیید سوال پیشنهادی توسط ادمین."""
    try:
        subs = DATA.get("question_submissions", [])
        for s in subs:
            if isinstance(s, dict) and int(s.get("id", 0)) == int(submission_id):
                s["status"] = "approved"
                s["reviewed_by"] = int(admin_uid)
                # اضافه کردن به BANKS
                qtype = str(s.get("type", "truth"))
                if qtype not in BANKS:
                    qtype = "truth"
                BANKS[qtype].append(str(s.get("text", "")))
                return True
        return False
    except Exception:
        return False


