#  فاز ۳۴ — Trade System (cosmetics)
# ================================================================
def trade_create(from_uid: int, to_uid: int, offer: dict, request: dict) -> dict:
    """ساخت درخواست تجارت.
    offer: {"type": "title"|"frame"|"badge"|"coins", "key": "...", "amount": N}
    request: مشابه offer
    """
    try:
        if int(from_uid) == int(to_uid):
            return {}
        # بررسی cooldown
        uf = get_user(int(from_uid))
        if int(uf.get("trade_cooldown_until", 0)) > now_ts():
            return {}
        trade_id = next_id("feedback")
        trade = {
            "id": trade_id,
            "from": int(from_uid),
            "to": int(to_uid),
            "offer": offer,
            "request": request,
            "ts": now_ts(),
            "status": "pending",  # pending | accepted | rejected | cancelled
            "completed_at": 0,
        }
        DATA.setdefault("trades_log", []).append(trade)
        # ثبت در پروفایل هر دو
        uf.setdefault("trades_sent", []).append({"id": trade_id, "to": int(to_uid), "ts": now_ts()})
        ut = get_user(int(to_uid))
        ut.setdefault("trades_received", []).append({"id": trade_id, "from": int(from_uid), "ts": now_ts()})
        push_notification(int(to_uid), "friend_req",
                          "🔄 درخواست تجارت!",
                          f"{name_of(int(from_uid))} می‌خواد باهات تجارت کنه.",
                          action_data="TR|HOME")
        return trade
    except Exception:
        return {}


def trade_accept(trade_id: int, acceptor_uid: int) -> bool:
    """قبول درخواست تجارت."""
    try:
        trades = DATA.get("trades_log", [])
        for t in trades:
            if isinstance(t, dict) and int(t.get("id", 0)) == int(trade_id):
                if int(t.get("to", 0)) != int(acceptor_uid):
                    return False
                if str(t.get("status")) != "pending":
                    return False
                # انجام تجارت
                from_uid = int(t.get("from", 0))
                to_uid = int(t.get("to", 0))
                offer = t.get("offer", {})
                request = t.get("request", {})
                uf = get_user(from_uid)
                ut = get_user(to_uid)
                # انتقال offer از from به to
                if offer.get("type") == "coins":
                    if spend_coins(from_uid, int(offer.get("amount", 0))):
                        add_coins(to_uid, int(offer.get("amount", 0)))
                elif offer.get("type") == "title":
                    key = offer.get("key", "")
                    if key in uf.get("titles_owned", []):
                        uf["titles_owned"] = [x for x in uf["titles_owned"] if x != key]
                        ut.setdefault("titles_owned", []).append(key)
                elif offer.get("type") == "frame":
                    key = offer.get("key", "")
                    if key in uf.get("frames_owned", []):
                        uf["frames_owned"] = [x for x in uf["frames_owned"] if x != key]
                        ut.setdefault("frames_owned", []).append(key)
                elif offer.get("type") == "badge":
                    key = offer.get("key", "")
                    if key in uf.get("badges_owned", []):
                        uf["badges_owned"] = [x for x in uf["badges_owned"] if x != key]
                        ut.setdefault("badges_owned", []).append(key)
                # انتقال request از to به from
                if request.get("type") == "coins":
                    if spend_coins(to_uid, int(request.get("amount", 0))):
                        add_coins(from_uid, int(request.get("amount", 0)))
                elif request.get("type") == "title":
                    key = request.get("key", "")
                    if key in ut.get("titles_owned", []):
                        ut["titles_owned"] = [x for x in ut["titles_owned"] if x != key]
                        uf.setdefault("titles_owned", []).append(key)
                elif request.get("type") == "frame":
                    key = request.get("key", "")
                    if key in ut.get("frames_owned", []):
                        ut["frames_owned"] = [x for x in ut["frames_owned"] if x != key]
                        uf.setdefault("frames_owned", []).append(key)
                elif request.get("type") == "badge":
                    key = request.get("key", "")
                    if key in ut.get("badges_owned", []):
                        ut["badges_owned"] = [x for x in ut["badges_owned"] if x != key]
                        uf.setdefault("badges_owned", []).append(key)
                # تکمیل
                t["status"] = "accepted"
                t["completed_at"] = now_ts()
                uf["trades_completed"] = int(uf.get("trades_completed", 0)) + 1
                ut["trades_completed"] = int(ut.get("trades_completed", 0)) + 1
                # cooldown 1 ساعت
                uf["trade_cooldown_until"] = now_ts() + 3600
                ut["trade_cooldown_until"] = now_ts() + 3600
                push_notification(int(from_uid), "achievement",
                                  "✅ تجارت انجام شد!",
                                  f"با {name_of(to_uid)} تجارت کردی.",
                                  action_data="P|PROFILE")
                return True
        return False
    except Exception:
        return False


def trade_reject(trade_id: int, rejector_uid: int) -> bool:
    """رد درخواست تجارت."""
    try:
        trades = DATA.get("trades_log", [])
        for t in trades:
            if isinstance(t, dict) and int(t.get("id", 0)) == int(trade_id):
                if int(t.get("to", 0)) != int(rejector_uid):
                    return False
                t["status"] = "rejected"
                return True
        return False
    except Exception:
        return False


async def tr_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """روتر کالبک‌های Trade."""
    query = update.callback_query
    if query is None:
        return
    uid = int(query.from_user.id)
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    try:
        if action == "HOME":
            await tr_send_home(query, uid)
            return
        if action == "ACC" and len(parts) > 2:
            tid = int(parts[2])
            ok = trade_accept(tid, int(uid))
            if ok:
                await safe_answer_query(query, "✅ تجارت انجام شد!")
            else:
                await safe_answer_query(query, "❌ قابل قبول نیست.")
            await tr_send_home(query, uid)
            return
        if action == "REJ" and len(parts) > 2:
            tid = int(parts[2])
            ok = trade_reject(tid, int(uid))
            if ok:
                await safe_answer_query(query, "❌ تجارت رد شد.")
            await tr_send_home(query, uid)
            return
        await safe_answer_query(query)
    except Exception as exc:
        log_event("error", "system", f"tr_callback failed: {exc!r}", actor=uid)


async def tr_send_home(query, uid: int) -> None:
    """نمایش پنل Trade."""
    try:
        user = get_user(int(uid))
        received = user.get("trades_received", [])[:5]
        completed = int(user.get("trades_completed", 0))
        cooldown = int(user.get("trade_cooldown_until", 0)) - now_ts()
        lines = [
            ds_top("🔄"),
            "│  🔄 <b>Trade Center</b>",
            ds_sep(),
            f"✅ تجارت‌های انجام‌شده: <b>{fmt_num(completed)}</b>",
            f"📨 دریافتی: <b>{fmt_num(len(user.get('trades_received', [])))}</b>",
            f"📤 ارسالی: <b>{fmt_num(len(user.get('trades_sent', [])))}</b>",
        ]
        if cooldown > 0:
            lines.append(f"⏳ Cooldown: <b>{cooldown // 60} دقیقه</b>")
        lines.extend(["", "━ درخواست‌های دریافتی ━"])
        if not received:
            lines.append("— درخواستی نداری.")
        else:
            for t in received:
                tid = int(t.get("id", 0))
                from_uid = int(t.get("from", 0))
                lines.append(f"🔄 #{tid} از {escape(name_of(from_uid))}")
        rows = []
        for t in received[:3]:
            tid = int(t.get("id", 0))
            rows.append([
                btn(f"✅ قبول #{tid}", f"TR|ACC|{tid}"),
                btn("❌ رد", f"TR|REJ|{tid}"),
            ])
        rows.append([btn("❓ راهنمای این بخش", "GD|TRADE")])
        rows.append(nav_footer())
        await safe_edit(query, "\n".join(lines), kb(rows))
    except Exception as exc:
        log_event("error", "system", f"tr_send_home failed: {exc!r}")


