def verify_user(uid: int, admin_uid: int = 0) -> bool:
    """تأیید هویت کاربر توسط ادمین."""
    try:
        user = get_user(int(uid))
        user["verified"] = True
        user["verified_at"] = now_ts()
        user["verified_by"] = int(admin_uid)
        verified_list = DATA.setdefault("verified_users", [])
        if int(uid) not in [int(x) for x in verified_list]:
            verified_list.append(int(uid))
        push_notification(int(uid), "achievement",
                          "✅ حساب تأیید شد!",
                          "حساب شما تأیید شد. حالا بج ✅ در پروفایلت داری!",
                          action_data="P|PROFILE")
        return True
    except Exception:
        return False


def unverify_user(uid: int) -> bool:
    """لغو تأیید هویت."""
    try:
        user = get_user(int(uid))
        user["verified"] = False
        user["verified_at"] = 0
        user["verified_by"] = 0
        verified_list = DATA.get("verified_users", [])
        DATA["verified_users"] = [x for x in verified_list if int(x) != int(uid)]
        return True
    except Exception:
        return False


def is_verified(uid: int) -> bool:
    """آیا کاربر تأییدشده است؟"""
    try:
        return bool(get_user(int(uid)).get("verified", False))
    except Exception:
        return False


