def game_night_create(chat_id: int, day: str, time_str: str, host: int) -> dict:
    """ساخت Game Night هفتگی.
    day: monday | tuesday | ... | sunday
    time_str: HH:MM
    """
    try:
        gn_id = f"gn_{int(chat_id)}_{day}_{time_str}"
        gn = {
            "id": gn_id,
            "chat_id": int(chat_id),
            "day": str(day),
            "time": str(time_str),
            "host": int(host),
            "created_at": now_ts(),
            "active": True,
            "participants": [int(host)],
            "reminders_sent": [],
        }
        DATA.setdefault("game_nights", {})[gn_id] = gn
        return gn
    except Exception:
        return {}


def game_night_list(chat_id: int) -> list:
    """لیست Game Night های یک گروه."""
    try:
        result = []
        for gn_id, gn in DATA.get("game_nights", {}).items():
            if isinstance(gn, dict) and int(gn.get("chat_id", 0)) == int(chat_id) and gn.get("active"):
                result.append(gn)
        return result
    except Exception:
        return []


# ================================================================
#  فاز ۴۱ — Game Reactions (emoji reactions during game)
# ================================================================
def game_reaction_add(game_id: str, message_id: int, uid: int, emoji: str) -> None:
    """افزودن واکنش به پیام بازی."""
    try:
        store = DATA.setdefault("game_reactions", {})
        game_reacts = store.setdefault(str(game_id), {})
        msg_reacts = game_reacts.setdefault(str(message_id), {})
        msg_reacts[str(uid)] = str(emoji)[:10]
    except Exception:
        pass


def game_reaction_count(game_id: str, message_id: int) -> dict:
    """شمارش واکنش‌های یک پیام."""
    try:
        store = DATA.get("game_reactions", {})
        msg_reacts = store.get(str(game_id), {}).get(str(message_id), {})
        counts = {}
        for uid, emoji in msg_reacts.items():
            counts[emoji] = counts.get(emoji, 0) + 1
        return counts
    except Exception:
        return {}


