# ================================================================
#  فاز ۴۴ — Statistics Export as CSV
# ================================================================
def export_csv_users() -> str:
    """خروجی CSV کاربران برای ادمین."""
    try:
        lines = ["UID,Name,Level,XP,Coins,Games,Wins,Losses,ELO,Reputation,VIP,Verified,Created_At"]
        for uid_str, u in DATA.get("users", {}).items():
            if not isinstance(u, dict):
                continue
            try:
                name = str(u.get("name", "")).replace(",", " ").replace("\n", " ")[:50]
                vip = "Yes" if int(u.get("vip_until", 0)) > now_ts() else "No"
                verified = "Yes" if u.get("verified") else "No"
                lines.append(f"{uid_str},{name},{u.get('level', 1)},{u.get('xp', 0)},{u.get('coins', 0)},{u.get('games', 0)},{u.get('wins', 0)},{u.get('losses', 0)},{u.get('elo_rating', 1000)},{u.get('reputation', 0)},{vip},{verified},{u.get('created_at', 0)}")
            except Exception:
                continue
        return "\n".join(lines)
    except Exception as exc:
        log_event("error", "system", f"export_csv_users failed: {exc!r}")
        return ""


def export_csv_economy() -> str:
    """خروجی CSV تراکنش‌های اقتصادی."""
    try:
        lines = ["Timestamp,DateTime,Type,UID,Amount,Reason"]
        for entry in DATA.get("economy_log", []):
            try:
                ts = int(entry.get("ts", 0))
                dt = datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S") if ts else ""
                lines.append(f"{ts},{dt},{entry.get('type', '')},{entry.get('uid', 0)},{entry.get('amount', 0)},{entry.get('reason', '')}")
            except Exception:
                continue
        return "\n".join(lines)
    except Exception:
        return ""


def export_csv_analytics() -> str:
    """خروجی CSV Analytics روزانه."""
    try:
        lines = ["Date,New_Users,Active_Users,Games_Started,Games_Ended,Coins_Earned,Coins_Spent,Feedback"]
        for day, info in sorted(DATA.get("analytics_daily", {}).items()):
            try:
                lines.append(f"{day},{info.get('new_users', 0)},{info.get('active_users', 0)},{info.get('games_started', 0)},{info.get('games_end', 0)},{info.get('coins_earned', 0)},{info.get('coins_spent', 0)},{info.get('feedback_sent', 0)}")
            except Exception:
                continue
        return "\n".join(lines)
    except Exception:
        return ""


async def cmd_apexcsv(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """دستور /apexcsv — خروجی CSV برای ادمین."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    if not has_permission(int(user.id), "admin"):
        await msg.reply_text(UX_MSG["no_permission"])
        return
    args = list(getattr(context, "args", None) or [])
    csv_type = str(args[0]) if args else "users"
    csv_data = ""
    filename = ""
    if csv_type == "users":
        csv_data = export_csv_users()
        filename = f"apexrival_users_{today_key()}.csv"
    elif csv_type == "economy":
        csv_data = export_csv_economy()
        filename = f"apexrival_economy_{today_key()}.csv"
    elif csv_type == "analytics":
        csv_data = export_csv_analytics()
        filename = f"apexrival_analytics_{today_key()}.csv"
    else:
        await msg.reply_text(
            "📊 <b>خروجی CSV</b>\n━━━━━━━━━━━━━━━━━━\n"
            "نوع خروجی رو مشخص کن:\n\n"
            "<code>/apexcsv users</code> — کاربران\n"
            "<code>/apexcsv economy</code> — تراکنش‌ها\n"
            "<code>/apexcsv analytics</code> — آمار روزانه",
            parse_mode=ParseMode.HTML)
        return
    if not csv_data:
        await msg.reply_text("❌ داده‌ای برای خروجی نیست.")
        return
    try:
        import io
        from telegram import InputFile
        bio = io.BytesIO(csv_data.encode("utf-8"))
        bio.name = filename
        await context.bot.send_document(
            chat_id=int(update.effective_chat.id),
            document=InputFile(bio, filename=filename),
            caption=f"📊 خروجی CSV — {csv_type}\n📅 {today_key()}",
        )
        log_event("info", "admin", f"CSV exported: {csv_type}", actor=int(user.id))
        DATA.setdefault("csv_exports_log", []).append({
            "uid": int(user.id), "ts": now_ts(), "type": csv_type
        })
    except Exception as exc:
        log_event("error", "system", f"cmd_apexcsv failed: {exc!r}")


