# ================================================================
#  فاز ۴۶ — Reminder System
# ================================================================
def reminder_add(uid: int, text: str, when_ts: int) -> dict:
    """افزودن یادآور شخصی."""
    try:
        reminder = {
            "id": next_id("feedback"),
            "uid": int(uid),
            "text": str(text)[:200],
            "when": int(when_ts),
            "ts": now_ts(),
            "sent": False,
        }
        user = get_user(int(uid))
        user.setdefault("reminders", []).append({
            "id": reminder["id"], "text": reminder["text"],
            "when": reminder["when"], "sent": False,
        })
        # افزودن به صف جهانی برای بررسی
        DATA.setdefault("reminders_queue", []).append(reminder)
        return reminder
    except Exception:
        return {}


def reminders_check_due() -> list:
    """بررسی یادآورهای سررسیدشده."""
    try:
        now = now_ts()
        due = []
        queue = DATA.get("reminders_queue", [])
        for r in queue:
            if isinstance(r, dict) and not r.get("sent") and int(r.get("when", 0)) <= now:
                r["sent"] = True
                due.append(r)
                # آپدیت در user record
                uid = int(r.get("uid", 0))
                user = get_user(uid)
                for urm in user.get("reminders", []):
                    if int(urm.get("id", 0)) == int(r.get("id", 0)):
                        urm["sent"] = True
        return due
    except Exception:
        return []


async def cmd_apexreminder(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """دستور /apexreminder — افزودن یادآور."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    args = list(getattr(context, "args", None) or [])
    if len(args) < 2:
        await msg.reply_text(
            "⏰ <b>یادآور شخصی</b>\n━━━━━━━━━━━━━━━━━━\n"
            "فرمت: <code>/apexreminder &lt;دقیقه&gt; &lt;متن&gt;</code>\n\n"
            "مثال:\n"
            "<code>/apexreminder 60 بازی کن</code> — یک ساعت بعد یادآوری می‌شه",
            parse_mode=ParseMode.HTML)
        return
    try:
        minutes = int(args[0])
    except Exception:
        await msg.reply_text("❌ تعداد دقیقه عدد معتبر باشد.")
        return
    if minutes < 1 or minutes > 1440:
        await msg.reply_text("❌ بین ۱ تا ۱۴۴۰ دقیقه (۲۴ ساعت).")
        return
    text = " ".join(args[1:])
    when = now_ts() + minutes * 60
    reminder = reminder_add(int(user.id), text, when)
    if reminder:
        await msg.reply_text(
            f"✅ یادآور ثبت شد!\n📝 {escape(text)}\n⏰ {minutes} دقیقه بعد",
            parse_mode=ParseMode.HTML)
    else:
        await msg.reply_text("❌ خطا در ثبت یادآور.")


# ================================================================
#  فاز ۴۷ — Smart Time-based Suggestions
# ================================================================
def smart_suggestion_by_time(uid: int) -> str:
    """پیشنهاد هوشمند بر اساس زمان روز."""
    try:
        hour = datetime.now(timezone.utc).hour
        if 6 <= hour < 12:
            return "🌅 صبح بخیر! یک بازی سبک شروع کن — حالت اعتراف یا راز مناسب صبحه."
        elif 12 <= hour < 18:
            return "☀️ ظهرت بخیر! وقتشه یکم هیجان داشته باشی — حالت جرئت یا سناریو رو امتحان کن."
        elif 18 <= hour < 22:
            return "🌆 عصرت بخیر! حالت‌های داغ‌تر مثل فلرت یا جنجال الان بهت می‌سازه."
        elif 22 <= hour < 24:
            return "🌙 شب بخیر! حالت‌های راز یا خجالت برای شب عالعه."
        else:
            return "🌌 دیروقت شد! اگر بیداری، Survival Mode برای تو عالعه."
    except Exception:
        return "🎮 وقتشه بازی کنی!"


async def cmd_apexsmart(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """دستور /apexsmart — پیشنهاد هوشمند."""
    msg = update.message
    user = update.effective_user
    if msg is None or user is None:
        return
    suggestion = smart_suggestion_by_time(int(user.id))
    # ترکیب با AI suggestion
    ai_suggestion = ai_game_master_suggest(int(user.id))
