def pick_extended_penalty(game: dict) -> str:
    """انتخاب یک مجازات از لیست گسترش‌یافته."""
    try:
        used = game.get("v7_used_penalties", [])
        available = [p for p in GROUP_PENALTIES_EXTENDED if p not in used]
        if not available:
            # همه استفاده شده — شروع مجدد
            available = GROUP_PENALTIES_EXTENDED[:]
            game["v7_used_penalties"] = []
        penalty = random.choice(available)
        used.append(penalty)
        if len(used) > 50:
            game["v7_used_penalties"] = used[-50:]
        return penalty
    except Exception:
        return random.choice(GROUP_PENALTIES_EXTENDED)


def spin_bottle_pick(players: list) -> int:
    """شبیه‌سازی چرخش بطری — یک بازیکن تصادفی."""
    try:
        if not players:
            return 0
        return random.choice(players)
    except Exception:
        return players[0] if players else 0


