# سیستم Vote & Skip برای سوالات گروهی
def vote_skip_init(game: dict, question_uid: int) -> None:
    """شروع رأی‌گیری برای رد یک سوال."""
    try:
        game["_vote_skip"] = {
            "target_uid": int(question_uid),
            "yes": [],
            "no": [],
            "started_at": now_ts(),
            "active": True,
        }
    except Exception:
        pass


def vote_skip_cast(game: dict, voter_uid: int, vote: bool) -> dict:
    """ثبت رأی برای رد سوال.
    vote: True = موافق رد، False = مخالف
    برمی‌گرداند: {ended, skipped, yes_count, no_count}
    """
    try:
        v = game.get("_vote_skip", {})
        if not v.get("active"):
            return {"ended": True, "skipped": False, "yes_count": 0, "no_count": 0}
        target_uid = int(v.get("target_uid", 0))
        if int(voter_uid) == int(target_uid):
            return {"ended": False, "skipped": False, "yes_count": len(v.get("yes", [])), "no_count": len(v.get("no", []))}
        if vote:
            if int(voter_uid) not in [int(x) for x in v.get("yes", [])]:
                v.setdefault("yes", []).append(int(voter_uid))
        else:
            if int(voter_uid) not in [int(x) for x in v.get("no", [])]:
                v.setdefault("no", []).append(int(voter_uid))
        # شمارش
        total_players = len(game.get("players", []))
        yes_count = len(v.get("yes", []))
        no_count = len(v.get("no", []))
        # اگه نصف+1 موافق شد، رد می‌شه
        if yes_count >= (total_players // 2) + 1:
            v["active"] = False
            v["ended_at"] = now_ts()
            return {"ended": True, "skipped": True, "yes_count": yes_count, "no_count": no_count}
        # اگه نصف+1 مخالف شد، رد نمی‌شه
        if no_count >= (total_players // 2) + 1:
            v["active"] = False
            v["ended_at"] = now_ts()
            return {"ended": True, "skipped": False, "yes_count": yes_count, "no_count": no_count}
        return {"ended": False, "skipped": False, "yes_count": yes_count, "no_count": no_count}
    except Exception:
        return {"ended": True, "skipped": False, "yes_count": 0, "no_count": 0}


def vote_skip_clear(game: dict) -> None:
    """پاکسازی رأی‌گیری."""
    try:
        game.pop("_vote_skip", None)
    except Exception:
        pass


# سیستم Quick Game (بازی سریع بدون لابی)
def quick_game_start(chat_id: int, leader: int, name: str) -> dict:
    """شروع سریع بازی بدون لابی — فقط یک نفر شروع می‌کنه و بقیه در حین بازی ملحق می‌شن.
    FIX: قبلاً phase روی «active» می‌ماند، turn_order خالی بود و advance_turn صدا
    زده نمی‌شد؛ در نتیجه current_questioner همیشه None بود، هیچ کارت نوبتی
    ارسال نمی‌شد و بازی برای همیشه در وضعیت لابی گیر می‌کرد."""
    try:
        game = make_game(chat_id, leader, name)
        game["phase"] = "topic"
        game["started_at"] = now_ts()
        game["quick_game"] = True
        game["auto_join"] = True  # بقیه می‌تونن بدون لابی ملحق بشن
        # شروع صحیح نوبت‌ها: سرگروه در turn_order و اولین نوبت فوری
        game["turn_order"] = [int(leader)]
        game["turn_index"] = 0
        game["round_scores"] = {str(leader): 0}
        try:
            get_user(int(leader))["games"] = int(get_user(int(leader)).get("games", 0)) + 1
        except Exception:
            pass
        advance_turn(game)
        return game
    except Exception:
        return {}


# سیستم Player of the Game (بهترین بازیکن)
def player_of_game_select(game: dict) -> tuple[int, str, int]:
    """انتخاب بهترین بازیکن بازی."""
    try:
        scores = game.get("round_scores", {})
        players = [int(x) for x in game.get("players", [])]
        if not players or not scores:
            return (0, "", 0)
        ranked = sorted(players, key=lambda p: -int(scores.get(str(p), 0)))
        if not ranked:
            return (0, "", 0)
        winner = int(ranked[0])
        score = int(scores.get(str(winner), 0))
        return (winner, name_of(winner, game), score)
    except Exception:
        return (0, "", 0)


