async def cmd_apextheme(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """دستور /apextheme — تنظیم تم شب گروه."""
    msg = update.message
    user = update.effective_user
    chat = update.effective_chat
    if msg is None or user is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🌐 این دستور فقط در گروه کار می‌کنه.")
        return
    args = list(getattr(context, "args", None) or [])
    if not args:
        # نمایش تم‌های موجود
        text = "🌟 <b>شب‌های موضوعی</b>\n━━━━━━━━━━━━━━━━━━\n"
        text += "برای تنظیم تم شب، دستور رو با کلید تم بفرست:\n\n"
        for key, info in THEME_NIGHTS.items():
            text += f"{info['icon']} <code>/apextheme {key}</code> — {info['name']}\n"
            text += "🔴 <code>/apextheme off</code> — خاموش کردن\n"
        await msg.reply_text(text, parse_mode=ParseMode.HTML)
        return
    theme_key = str(args[0]).lower()
    if theme_key == "off":
        theme_night_set(int(chat.id), "")
        await msg.reply_text("🔴 تم شب خاموش شد.")
        return
    if theme_key not in THEME_NIGHTS:
        await msg.reply_text("❌ تم نامعتبر. /apextheme رو بدون آرگومان بفرست تا لیست ببینی.")
        return
    theme_night_set(int(chat.id), theme_key)
    info = THEME_NIGHTS[theme_key]
    await msg.reply_text(
        f"{info['icon']} <b>{info['name']} فعال شد!</b>\n"
        f"📝 مودهای پیشنهادی: {', '.join(info['modes'])}",
        parse_mode=ParseMode.HTML)


async def cmd_apexquick(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """دستور /apexquick — شروع سریع بازی بدون لابی."""
    msg = update.message
    user = update.effective_user
    chat = update.effective_chat
    if msg is None or user is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🌐 این دستور فقط در گروه کار می‌کنه.")
        return
    # بررسی بازی فعال
    game = active_game(int(chat.id))
    if game and str(game.get("status")) == "active":
        await msg.reply_text("⚠️ بازی فعال داری! اول /apexend بزن.")
        return
    # شروع سریع
    name = user.first_name or "بازیکن"
    game = quick_game_start(int(chat.id), int(user.id), name)
    if not game:
        await msg.reply_text(UX_MSG["error_generic"])
        return
    # FIX: آمار گروه + Analytics ثبت شود
    try:
        group = get_group(int(chat.id))
        group["created_games"] = int(group.get("created_games", 0)) + 1
        analytics_bump("games_started")
        audit("quick_game_start", int(user.id), int(chat.id))
    except Exception:
        pass
    await msg.reply_text(
        f"{ds_top('⚡')}\n"
        "│  ⚡ <b>بازی سریع شروع شد!</b>\n"
        f"{ds_sep()}\n"
        f"👑 سرگروه: {mention_user(int(user.id), name)}\n"
        "🎮 بازی شروع شد! بقیه می‌تونن با /apexjoin وارد بشن.\n"
        "🎯 اولین نوبت شروع می‌شه!",
        parse_mode=ParseMode.HTML)
    # FIX: ارسال کارت اولین نوبت — قبلاً هرگز ارسال نمی‌شد
    await game_send_turn_card(context, game)


async def cmd_apexjoin(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """دستور /apexjoin — پیوستن به بازی سریع فعال."""
    msg = update.message
    user = update.effective_user
    chat = update.effective_chat
    if msg is None or user is None or chat is None:
        return
    if chat.type not in ("group", "supergroup"):
        await msg.reply_text("🌐 این دستور فقط در گروه کار می‌کنه.")
        return
    game = active_game(int(chat.id))
    if not game or str(game.get("status")) != "active":
        await msg.reply_text("❌ بازی فعالی نیست. /apexquick بزن.")
        return
    if not game.get("quick_game") or not game.get("auto_join"):
        await msg.reply_text("❌ این بازی قابل ملحق شدن نیست.")
        return
    uid = int(user.id)
    if uid in [int(x) for x in game.get("players", [])]:
        await msg.reply_text("ℹ️ قبلاً در بازی هستی!")
        return
    # افزودن به بازی
    with LOCK:
        game["players"].append(uid)
        game["names"][str(uid)] = user.first_name or "بازیکن"
        game["ready"].append(uid)
        game["turn_order"].append(uid)
    await msg.reply_text(
        f"✅ {mention_user(uid, user.first_name)} به بازی ملحق شد! 🎉",
        parse_mode=ParseMode.HTML)


