async def admin_callback_v11(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """روتر پنل ادمین نسخه‌ی ۱.۲.۰ — wrapper روی admin_callback موجود
    با افزودن مسیرهای داشبورد جدید و Admin Managers کامل."""
    query = update.callback_query
    if query is None:
        return
    uid = int(query.from_user.id)
    if not has_permission(int(uid), "admin"):
        await safe_answer_query(query, UX_MSG["no_permission"], show_alert=True)
        return
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    try:
        # --- (۱۱.۰) ⏱ موتور نبض + 🌐 پنل گروه‌ها ---
        if action == "PULSE":
            await admin_pulse_center(query)
            return
        if action == "PULSET" and len(parts) > 2:
            key = parts[2]
            if key in ("panel_refresh", "panel_countdown"):
                store = DATA.setdefault("syscfg", {})
                store[key] = not bool(syscfg().get(key))
                save_data(force=True)
                audit("pulse_toggle", uid, None, f"{key}={store[key]}")
                await safe_answer_query(query, "✅ روشن شد" if store[key] else "🌙 خاموش شد")
            await admin_pulse_center(query)
            return
        if action == "PULSEN" and len(parts) > 2:
            try:
                delta = int(parts[2])
            except Exception:
                delta = 0
            cur = max(3, int(syscfg().get("panel_interval", 5)))
            nxt = max(PULSE_INTERVAL_MIN, min(PULSE_INTERVAL_MAX, cur + delta))
            DATA.setdefault("syscfg", {})["panel_interval"] = nxt
            save_data(force=True)
            audit("pulse_interval", uid, None, f"{nxt}")
            await safe_answer_query(query, f"⏱ فاصله‌ی رفرش: {pnum(nxt)} ثانیه")
            await admin_pulse_center(query)
            return
        if action == "PULSERUN":
            await safe_answer_query(query, "⚡ در حال رفرش فوری همه‌ی پنل‌ها...")
            n = await pulse_force_refresh(context)
            await safe_answer_query(query, f"✅ {pnum(n)} پنل تازه شد")
            await admin_pulse_center(query)
            return
        if action == "PULSECLEAN":
            n = pulse_cleanup_dead_panels()
            save_data(force=True)
            await safe_answer_query(query, f"🧹 {pnum(n)} پنل مرده پاک شد")
            await admin_gpanels_show(query)
            return
        if action == "GPANELS":
            page = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 0
            await admin_gpanels_show(query, page)
            return
        if action == "GPC" and len(parts) > 2:
            await admin_gpanel_control(query, parts[2])
            return
        if action in ("GPCR", "GPCT", "GPCI", "GPCCT", "GPCA",
                      "GPCMIN", "GPCMAX", "GPCSKIP", "GPCEND", "GPCCLOSE"):
            await admin_gpanel_action(update, context, query, action, parts)
            return
        # --- (۱۰.۰) مرکز فرماندهی نسل جدید ---
        if action == "NOP":
            await safe_answer_query(query)
            return
        if action == "PERMS":
            await admin_perms_center(query)
            return
        if action == "QUICK":
            await admin_quick_center(query)
            return
        if action == "GIFTALL":
            await admin_giftall_wizard(query)
            return
        if action == "GIFTALLC" and len(parts) > 3:
            kind = str(parts[2])
            if kind == "custom":
                _V9_INPUT["mode"] = "v10_giftall"
                _V9_INPUT["data"] = {}
                await safe_answer_query(query, "✍️ مقدار هدیه را بفرست (عدد)")
                await safe_edit(
                    query,
                    og_banner("هدیه سفارشی", "🎀") + "\n\n"
                    "مقدار هدیه را به‌صورت عدد بفرست.\n"
                    "مثال: <code>300</code>\n\n"
                    "سپس نوع (سکه/XP) و تأیید نهایی می‌آید.",
                    kb([nav_row("A|GIFTALL")]))
                return
            try:
                amt = int(parts[3])
            except Exception:
                amt = 0
            await admin_giftall_confirm(query, kind, amt)
            return
        if action == "GIFTALLGO" and len(parts) > 3:
            try:
                amt = int(parts[3])
            except Exception:
                amt = 0
            await admin_giftall_apply(update, context, query, str(parts[2]), amt)
            return
        if action == "CLEAN" and len(parts) > 2 and parts[2] == "games":
            await admin_clean_apply(update, context, query, "games")
            return
        if action == "CLEAN":
            await admin_clean_center(query)
            return
        if action == "CLEANGO" and len(parts) > 2:
            await admin_clean_apply(update, context, query, str(parts[2]))
            return
        if action == "UFILTER":
            mode = parts[2] if len(parts) > 2 else "all"
            page = int(parts[3]) if len(parts) > 3 and parts[3].isdigit() else 0
            await admin_users_manager_show(query, page, mode)
            return
        # --- (۹.۰) مسیرهای اُمگا+ — ارتقای عمیق ۲۰ بخش ---
        if action in ("UCOIN", "UXP", "UDM", "UNOTE", "UINV") and len(parts) > 2:
            tool = {"UCOIN": "coin", "UXP": "xp", "UDM": "dm",
                    "UNOTE": "note", "UINV": "inv"}[action]
            await admin_v9_user_tools(query, parts[2], tool)
            return
        if action == "UCUST" and len(parts) > 3:
            await admin_v9_user_custom(query, parts[2], parts[3])
            return
        if action == "UNOTEDEL" and len(parts) > 2:
            get_user(int(parts[2])).pop("admin_note", None)
            save_data()
            await safe_answer_query(query, "🧹 یادداشت پاک شد")
            await admin_v9_user_tools(query, parts[2], "note")
            return
        if action == "ANHR":
            await admin_v9_analytics_hourly(query)
            return
        if action == "ANTOP":
            await admin_v9_analytics_top(query)
            return
        if action == "ACHV" and len(parts) > 2:
            await admin_v9_ach_view(query, parts[2])
            return
        if action == "ACHDEL" and len(parts) > 2:
            key = parts[2]
            v9_custom_ach_store().pop(key, None)
            save_data(force=True)
            audit("ach_custom_del", uid, None, f"key={key}")
            await safe_answer_query(query, "🗑 دستاورد سفارشی حذف شد")
            await admin_v9_ach_manager(query)
            return
        if action == "ACHTOG" and len(parts) > 2:
            key = parts[2]
            st = editor_store()
            off = st.setdefault("ach_off", [])
            if key in off:
                off.remove(key)
                await safe_answer_query(query, "✅ دستاورد روشن شد")
            else:
                off.append(key)
                await safe_answer_query(query, "🌙 دستاورد خاموش شد")
            save_data(force=True)
            await admin_v9_ach_view(query, key)
            return
        if action == "ACHNEW":
            await admin_v9_ach_new_wizard(query)
            return
        if action == "ACHG":
            await admin_v9_ach_grant_wizard(query)
            return
        if action == "GIFT":
            await admin_v9_gift_home(query)
            return
        if action == "GIFTNEW":
            await admin_v9_gift_new_wizard(query)
            return
        if action == "GIFTLIST":
            await admin_v9_gift_list(query)
            return
        if action == "GIFTDEL" and len(parts) > 2:
            v9_gift_store().pop(parts[2], None)
            save_data(force=True)
            audit("gift_del", uid, None, f"code={parts[2]}")
            await safe_answer_query(query, "🗑 کد حذف شد")
            await admin_v9_gift_list(query)
            return
        if action == "GROUP" and len(parts) > 2:
            await admin_v9_group_detail(query, parts[2])
            return
        if action == "GTOG" and len(parts) > 2:
            gid = int(parts[2])
            g = get_group(gid)
            g["enabled"] = not bool(g.get("enabled", True))
            save_data(force=True)
            audit("group_toggle", uid, gid, f"enabled={g['enabled']}")
            await safe_answer_query(query, "✅ روشن شد" if g["enabled"] else "🌙 خاموش شد")
            await admin_v9_group_detail(query, gid)
            return
        if action == "GLEAVE" and len(parts) > 2:
            gid = int(parts[2])
            try:
                await context.bot.leave_chat(gid)
                await safe_answer_query(query, "🚪 از گروه خارج شدم")
                audit("group_leave", uid, gid, "left")
            except Exception as exc:
                await safe_answer_query(query, f"⚠️ خروج ناموفق: {str(exc)[:60]}")
            await admin_groups_manager_show(query)
            return
        if action == "ADMINS":
            await admin_v9_admins_panel(query)
            return
        if action == "ADMINADD":
            _V9_INPUT["mode"] = "v9_adminadd"
            await safe_answer_query(query, "✍️ «آیدی نقش» را بفرست")
            await safe_edit(query,
                "🛡 <b>افزودن دسترسی</b>\n━━━━━━━━━━━━━━━━━━\n"
                "این قالب را بفرست: <code>آیدی نقش</code>\n"
                "نقش‌ها: <code>admin</code> یا <code>mod</code>\n\n"
                "مثال: <code>123456789 mod</code>",
                kb([nav_row("A|ADMINS")]))
            return
        if action == "ADMINDEL" and len(parts) > 2:
            k = parts[2]
            perms = DATA.get("permissions", {})
            perms.pop(k, None)
            save_data(force=True)
            audit("perm_del", uid, None, f"target={k}")
            await safe_answer_query(query, "🗑 دسترسی حذف شد")
            await admin_v9_admins_panel(query)
            return
        if action == "BKV" and len(parts) > 2:
            await admin_v9_backup_detail(query, parts[2])
            return
        if action == "BKDL" and len(parts) > 2:
            await admin_v9_backup_download(update, context, query, parts[2])
            return
        if action == "BKREST" and len(parts) > 2:
            await admin_v9_backup_restore(query, parts[2])
            return
        if action == "BKREST2" and len(parts) > 2:
            await admin_v9_backup_restore_apply(update, context, query, parts[2])
            return
        if action == "EXCSV" and len(parts) > 2:
            await admin_v9_export_csv(update, context, query, parts[2])
            return
        if action == "EXBK":
            await bank_export(update, context, query)
            return
        if action == "LOGQ":
            await admin_v9_logs_search(query)
            return
        if action == "MAINTSCH":
            await admin_v9_maint_schedule(query)
            return
        if action == "QRDEL" and len(parts) > 2:
            try:
                idx = int(parts[2])
            except Exception:
                idx = -1
            await admin_v9_qreport_delete(update, context, query, idx)
            return
        if action == "BG" and len(parts) > 2 and parts[2] == "CHK":
            await admin_v9_bank_guard_deep(query)
            return
        # --- مسیرهای داشبورد جدید ---
        if action == "HOME":
            await admin_dashboard_show(query)
            return
        if action == "ANALYTICS":
            await admin_analytics_show(query)
            return
        if action == "FEEDBACK":
            await admin_feedback_show(query)
            return
        if action == "MAINT":
            await admin_maintenance_toggle(query)
            return
        # --- مسیرهای اومگا ---
        if action == "VITALS":
            await admin_vitals_show(query)
            return
        if action == "BANKGUARD":
            await admin_bank_guard_show(query)
            return
        if action == "FBREPLY" and len(parts) > 2:
            try:
                fb_idx = int(parts[2])
            except Exception:
                fb_idx = -1
            feedbacks = DATA.get("feedback", [])
            if 0 <= fb_idx < len(feedbacks) and isinstance(feedbacks[fb_idx], dict):
                _FB_REPLY_INPUT["active"] = True
                _FB_REPLY_INPUT["idx"] = fb_idx
                await safe_answer_query(query, "✍️ متن پاسخ را بفرست")
                fb_txt = str(feedbacks[fb_idx].get("text", ""))[:120]
                await safe_edit(
                    query,
                    og_banner("پاسخ به بازخورد", "✍️") + "\n\n"
                    f"📨 بازخورد #{pnum(fb_idx + 1)}:\n"
                    f"┃ ▸ {escape(fb_txt)}\n\n"
                    "متن پاسخ‌ات را همین‌جا بفرست تا هم ثبت شود هم برای بازیکن ارسال گردد. 🚀",
                    kb([[btn("✖ انصراف", "A|FEEDBACK")]]),
                )
            else:
                await safe_answer_query(query, "⚠️ بازخورد پیدا نشد!", True)
            return
        if action == "FBDONE" and len(parts) > 2:
            try:
                fb_idx = int(parts[2])
            except Exception:
                fb_idx = -1
            feedbacks = DATA.get("feedback", [])
            if 0 <= fb_idx < len(feedbacks) and isinstance(feedbacks[fb_idx], dict):
                feedbacks[fb_idx]["status"] = "done"
                save_data(force=True)
                audit("fb_done", int(query.from_user.id), None, f"idx={fb_idx}")
                await safe_answer_query(query, "✅ رسیدگی شد")
            await admin_feedback_show(query)
            return
        # --- نسخه ۶: گزارش سوالات ---
        if action == "QREPORTS":
            await admin_qreports_show(query)
            return
        if action == "QRDONE" and len(parts) > 2:
            try:
                qr_idx = int(parts[2])
            except Exception:
                qr_idx = -1
            reports = DATA.get("question_reports", [])
            if 0 <= qr_idx < len(reports) and isinstance(reports[qr_idx], dict):
                reports[qr_idx]["status"] = "done"
                reports[qr_idx]["reviewed_by"] = int(query.from_user.id)
                save_data(force=True)
                audit("qr_done", int(query.from_user.id), None, f"idx={qr_idx}")
                await safe_answer_query(query, "✅ گزارش بررسی شد")
            await admin_qreports_show(query)
            return
        if action == "EXPORT":
            # (۹.۰) مرکز خروجی — همه‌ی فرمت‌ها یک‌جا
            await admin_export_data(query)
            return
        if action == "LOGS":
            lvl = parts[2] if len(parts) > 2 else "all"
            await admin_logs_show(query, lvl)
            return
        if action == "BACKUP":
            try:
                Path(BACKUP_DIR).mkdir(parents=True, exist_ok=True)
                save_data(force=True)
                path = backup_data("manual")
                if path:
                    backups = list_backups()
                    await safe_answer_query(query, f"✅ بکاپ ساخته شد! ({len(backups)} بکاپ کل)")
                    await admin_backup_manager_show(query)
                else:
                    await safe_answer_query(query, "❌ خطا در ساخت بکاپ — دوباره تلاش کن.")
                    await admin_backup_manager_show(query)
            except Exception as exc:
                log_event("error", "admin", f"Backup failed: {exc!r}", actor=int(query.from_user.id))
                await safe_answer_query(query, f"❌ خطا: {str(exc)[:100]}")
                await admin_backup_manager_show(query)
            return
        # --- فاز ۷: Admin Managers کامل ---
        if action == "USERS":
            page = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 0
            await admin_users_manager_show(query, page)
            return
        if action == "USER" and len(parts) > 2:
            target_uid = int(parts[2])
            await admin_user_detail_show(query, target_uid)
            return
        if action == "UMOD" and len(parts) > 3:
            target_uid = int(parts[2])
            mod_action = parts[3]
            await admin_user_modify(query, target_uid, mod_action)
            return
        if action == "GAMES":
            await admin_games_manager_show(query)
            return
        if action == "GAME" and len(parts) > 2:
            game_key = parts[2]
            await admin_game_detail_show(query, game_key)
            return
        if action == "GMOD" and len(parts) > 3:
            game_key = parts[2]
            mod_action = parts[3]
            if mod_action == "end":
                await admin_game_end_force(query, game_key)
            return
        if action == "ACHM":
            await admin_v9_ach_manager(query)
            return
        # ECON: اگر parts بیشتر از 2 باشه، یعنی اکشن اقتصادی هست (مثل ECON|infl8)
        if action == "ECON" and len(parts) > 2:
            econ_action = parts[2]
            await admin_economy_action(query, econ_action)
            return
        if action == "ECON":
            await admin_economy_manager_show(query)
            return
        if action == "ECONACT" and len(parts) > 2:
            econ_action = parts[2]
            await admin_economy_action(query, econ_action)
            return
        if action == "GROUPS":
            await admin_groups_manager_show(query)
            return
        if action == "SETTINGS":
            await admin_settings_show(query)
            return
        if action == "SETCH":
            await safe_answer_query(query, "📢 برای تغییر کانال اجباری، متغیر محیطی REQUIRED_CHANNEL را تنظیم کنید.")
            return
        if action == "USEARCH":
            await safe_answer_query(query, "🔍 آیدی عددی کاربر رو بفرست:")
            context.application.user_data[uid] = context.application.user_data.get(uid, {})
            context.application.user_data[uid]["await_admin_user_search"] = True
            return
        if action == "ACHNEW":
            await safe_answer_query(query, "🎖 ساخت دستاورد سفارشی به‌زودی!")
            return
        if action == "REWARD":
            await admin_reward_manager_show(query)
            return
        if action == "GIFT":
            await admin_v9_gift_home(query)
            return
        if action == "GIFTNEW":
            await admin_v9_gift_new_wizard(query)
            return
        if action == "GIFTLIST":
            await admin_v9_gift_list(query)
            return
        # --- نسخه ۶.۲: سیستم و ضداسپم ---
        if action == "SYSCFG":
            await admin_syscfg_show(query)
            return
        if action in ("SYST", "SYSN", "SYSNUM", "SYNOP", "SYSRESET"):
            await admin_syscfg_action(update, context, query, action, parts)
            return
        # مسیرهای قدیمی — ارسال به admin_callback اصلی
        # برای حفظ Backward Compatibility
        await admin_callback(update, context)
    except Exception as exc:
        log_event("error", "system", f"admin_callback_v11 failed: {action} {exc!r}", actor=uid)
        await safe_answer_query(query, UX_MSG["error_generic"])


async def route_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """یک روتر واحد برای همه‌ی دکمه‌های اینلاین."""
    query = update.callback_query
    if query is None:
        return
    uid = int(query.from_user.id)
    data = str(query.data or "")
    # محافظ Maintenance Mode — ادمین‌ها عبور می‌کنند
    if maintenance_active() and not bypass_maintenance(int(uid)):
        await safe_answer_query(query, UX_MSG["maintenance"], show_alert=True)
        return
    # محافظ اسپم
    if not rate_check(uid):
        await safe_answer_query(query, "آهسته‌تر! 🐢 چند ثانیه صبر کن...")
        return
    prefix = data.split("|")[0] if "|" in data else ""
    # 🧭 (۸.۰) ناوبری: پشته‌ی مسیر خصوصی + دکمه‌ی برگشت واقعی
    try:
        _nav_chat = query.message.chat if query.message else None
        _nav_private = bool(_nav_chat and getattr(_nav_chat, "type", "") == "private")
    except Exception:
        _nav_private = False
    if data == "NAV|BACK":
        if not _nav_private:
            await safe_answer_query(query, "🧭 برگشت فقط در چت خصوصی فعال است — از 🏠 استفاده کن")
            return
        data, prefix = await nav_back_handler(update, context, query, uid)
        # (۱۰.۰) تعمیر بحرانی: روی PTB واقعی آبجکت فروزن است — انتساب مستقیم
        # AttributeError می‌دهد و این دقیقاً علتِ «همه‌ی دکمه‌های برگشت خطا
        # می‌دادند» بود. حالا با لایه‌های دفاعی nav_retarget انجام می‌شود.
        if not nav_retarget(query, data):
            # مسیر جایگزین (بی‌نهایت نادر): هندلر مقصد خودش query.data را
            # می‌خواند؛ اگر retarget نشد، مستقیم خانه را نشان بده — هرگز خطا نه.
            await home_callback(update, context)
            return
    elif data == "H|HOME":
        nav_clear(uid)
    elif _nav_private and nav_is_panel(data):
        nav_push(uid, data)
    try:
        if prefix == "ON":
            await onb_callback(update, context)
        elif prefix == "H":
            await home_callback(update, context)
        elif prefix == "L":
            await lobby_callback(update, context)
        elif prefix == "G":
            await game_callback(update, context)
        elif prefix == "P":
            await profile_callback(update, context)
        elif prefix == "S":
            await shop_callback(update, context)
        elif prefix == "A":
            await admin_callback_v11(update, context)
        elif prefix == "BK":
            await bank_v9_callback(update, context)
            return
        elif prefix == "ED":
            await editor_callback(update, context, query, data.split("|"))
        elif prefix == "PN":
            await punish_callback(update, context)
        elif prefix == "D":
            await duel_callback(update, context)
        elif prefix == "FY":
            await fun_callback(update, context)
        elif prefix == "LV":
            await love_callback(update, context)
        elif prefix == "LV2":
            await love2_callback(update, context)
        elif prefix == "ST":
            await settings_callback(update, context)
        # --- 1.1.0 Callback Handlers ---
        elif prefix == "PM":
            await pm_callback(update, context)
        elif prefix == "FR":
            await fr_callback(update, context)
        elif prefix == "RV":
            await rv_callback(update, context)
        elif prefix == "RF":
            await rf_callback(update, context)
        elif prefix == "DM":
            await dm_callback(update, context)
        elif prefix == "TM":
            await tm_callback(update, context)
        elif prefix == "SE":
            await se_callback(update, context)
        elif prefix == "NT":
            await nt_callback(update, context)
        elif prefix == "US":
            await us_callback(update, context)
        elif prefix == "FB":
            await fb_callback(update, context)
        elif prefix == "QG":
            await qg_callback(update, context)
        elif prefix == "GD":
            await gd_callback(update, context)
        # --- 1.2.0 Callback Handlers ---
        elif prefix == "AI":
            await ai_callback(update, context)
        elif prefix == "SV":
            await sv_callback(update, context)
        elif prefix == "TB":
            await tb_callback(update, context)
        elif prefix == "DR":
            await dr_callback(update, context)
        # --- 1.2.0 Extended Callback Handlers ---
        elif prefix == "QS":
            await qs_callback(update, context)
        elif prefix == "SP":
            await sp_callback(update, context)
        elif prefix == "MM":
            await mm_callback(update, context)
        elif prefix == "GH":
            await gh_callback(update, context)
        elif prefix == "BA":
            await ba_callback(update, context)
        elif prefix == "MS":
            await ms_callback(update, context)
        elif prefix == "HF":
            await hf_callback(update, context)
        elif prefix == "SD":
            await sd_callback(update, context)
        elif prefix == "TT":
            await tt_callback(update, context)
        elif prefix == "VP":
            await vp_callback(update, context)
        # --- Ultimate Build Extended Callback Handlers ---
        elif prefix == "MG":
            await mg_callback(update, context)
        elif prefix == "TR":
            await tr_callback(update, context)
        elif prefix == "LN":
            await ln_callback(update, context)
        else:
            await safe_answer_query(query)
    except Exception as exc:
        audit("callback_error", uid, None, f"{data[:40]} {repr(exc)[:150]}")
        log_event("error", "system", f"callback_error: {data[:40]}", actor=uid,
                  details=repr(exc)[:200])
        await safe_answer_query(query, "خطایی پیش آمد؛ دوباره امتحان کن 🙏")


async def home_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    chat = query.message.chat if query.message else None
    # 🧹 نسخه ۶.۱ — منوی اصلی = درِ خروج: حالت «در حال نوشتن بازخورد» پاک شود
    try:
        ud = context.application.user_data.get(uid, {})
        ud.pop("await_feedback", None)
        ud.pop("await_feedback_ts", None)
    except Exception:
        pass

    if action == "CLOSE":
        await safe_answer_query(query)
        if chat is not None and chat.type in ("group", "supergroup"):
            await safe_edit(query, "✅ پنل بسته شد. برای بازی: /apex")
        else:
            try:
                await query.message.delete()
            except Exception:
                await safe_edit(query, "✅ بسته شد.")
        return

    if action == "GUIDE":
        page = 0
        if len(parts) > 2:
            try:
                page = int(parts[2])
            except Exception:
                page = 0
        await safe_answer_query(query)
        await guide_show(update, context, page, query=query)
        return

    if action == "HOME":
        await safe_answer_query(query)
        if chat is not None and chat.type in ("group", "supergroup"):
            await show_group_menu(update, context, int(chat.id), uid)
            try:
                await query.message.delete()
            except Exception:
                pass
        else:
            await safe_edit(query, private_home_text(uid), private_home_markup(uid))
            # 🎬 ۶.۵ — برگشت به خانه: منوی زنده دوباره فعال شود
            if chat is not None and query.message is not None:
                home_live_mark(uid, int(chat.id), int(query.message.message_id))
        return

    # --- 🗂 هاب‌های منوی ۸ دکمه‌ای (۶.۳) ---
    if action in HUB_VIEWS:
        await safe_answer_query(query)
        text, markup = HUB_VIEWS[action](uid)
        await safe_edit(query, text, markup)
        return

    if action == "ABOUT":
        # ℹ️ درباره ربات — به‌صورت کالبک برای هاب راهنما (۶.۳)
        await safe_answer_query(query)
        users = len(DATA.get("users", {}))
        groups = len(DATA.get("groups", {}))
        text = (
            f"{ds_top()}\n"
            f"│  ⚔️ <b>{BOT_NAME}</b>\n"
            f"│  <i>{DS_VER} — بازنویسی کامل · هزارلولی</i>\n"
            f"{ds_sep()}\n"
            + ds_row("📦 نسخه", f"{fa(VERSION)} نبض ⏱") + "\n"
            + ds_row("📚 بانک سوالات", f"{pnum(BANKS_TOTAL)} سوال در {pnum(len(BANKS))} بانک") + "\n"
            + ds_row("👥 کاربران", pnum(users)) + "\n"
            + ds_row("👥 گروه‌ها", pnum(groups)) + "\n"
            + ds_row("🛡 داده‌های قبلی", "سازگار کامل ✅") + "\n"
            + f"{ds_sep('⋆')}\n"
            + "│  💫 ساخته‌شده برای شب‌های بی‌خوابی گروه‌های فارسی‌زبان 🌙\n"
            + ds_close()
        )
        await safe_edit(query, text, kb([
            [btn("🎓 راهنما", "H|HELP")],
            [btn("🏠 منوی اصلی", "H|HOME")],
        ]))
        return

    if action == "MORE":
        # ۶.۳ — دکمه‌ی «بیشتر...» بازنشسته شد؛ همه‌ی بخش‌ها زیرمجموعه‌ی ۸ دکمه‌ی اصلی‌اند.
        # پنل‌های قدیمی که هنوز این دکمه را دارند، به منوی جدید ۸ دکمه‌ای هدایت می‌شوند.
        await safe_answer_query(query)
        await safe_edit(query, private_home_text(uid), private_home_markup(uid))
        # 🎬 ۶.۵ — این مسیر هم منوی اصلی را برمی‌گرداند: منوی زنده فعال شود
        if chat is not None and query.message is not None:
            home_live_mark(uid, int(chat.id), int(query.message.message_id))
        return

    await safe_answer_query(query)


