async def cmd_apexriddle(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """🧩 معمای ایموجی — اولین جواب درست برنده است (گروه)."""
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or user is None:
        return
    try:
        if chat.type not in ("group", "supergroup"):
            await msg.reply_text("🧩 معمای ایموجی در <b>گروه</b> جواب می‌دهد — دوستات را ببرد کلاب!", parse_mode=ParseMode.HTML)
            return
        emojis, answer, options = random.choice(EMOJI_RIDDLES)
        code = v24_new_code()
        letters = ("🅰", "🅱", "🅲", "🅳")
        opts = list(options)
        random.shuffle(opts)
        store = context.application.bot_data.setdefault("riddle", {})
        store[str(code)] = {"answer": answer, "done": False, "ts": time.time()}
        rows = []
        pair = []
        for i, opt in enumerate(opts):
            pair.append(btn(f"{letters[i]} {opt}", f"FY|RID|{code}|{i}", "primary"))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)
        await msg.reply_text(
            f"🧩 <b>معمای ایموجی</b>\n━━━━━━━━━━━━━━━━━━\n\n"
            f"🎁 <b>{emojis}</b>\n\n"
            "اولین جواب درست <b>+۱۵ سکه</b> می‌برد — سریع باش!",
            parse_mode=ParseMode.HTML, reply_markup=kb(rows))
        v24_store()["stats"]["party_games"] = int(v24_store()["stats"].get("party_games", 0)) + 1
    except Exception as exc:
        log_event("error", "system", f"cmd_apexriddle failed: {exc!r}", actor=int(user.id))


async def cmd_apexroyale(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """👑 عدد سلطنتی — همه یک عدد می‌گیرند؛ نزدیک‌ترین به هدف سلطنت می‌کند (گروه)."""
    msg = update.message
    chat = update.effective_chat
    user = update.effective_user
    if msg is None or chat is None or user is None:
        return
    try:
        if chat.type not in ("group", "supergroup"):
            await msg.reply_text("👑 عدد سلطنتی در <b>گروه</b> جواب می‌دهد — جمع شوید!", parse_mode=ParseMode.HTML)
            return
        code = v24_new_code()
        rows = [[btn(f"🔢 {pnum(n)}", f"FY|NR|{code}|{n}", "primary") for n in (1, 2, 3, 4, 5)],
                [btn(f"🔢 {pnum(n)}", f"FY|NR|{code}|{n}", "primary") for n in (6, 7, 8, 9)]]
        await msg.reply_text(
            "👑 <b>عدد سلطنتی</b>\n━━━━━━━━━━━━━━━━━━\n"
            "همه یک عدد بین ۱ تا ۹ بردارند!\n"
            "🎯 عدد سلطنتی تصادفی اعلام می‌شود — نزدیک‌ترین نفر <b>+۳۰ سکه</b> و تاج می‌گیرد!",
            parse_mode=ParseMode.HTML, reply_markup=kb(rows))
        store = context.application.bot_data.setdefault("royale", {})
        store[str(code)] = {"picks": {}, "chat_id": int(chat.id), "ts": time.time()}
        v24_store()["stats"]["party_games"] = int(v24_store()["stats"].get("party_games", 0)) + 1
        # ⏱ اعلام نتیجه بعد از ۴۵ ثانیه
        async def _reveal():
            await asyncio.sleep(45)
            try:
                st = store.get(str(code))
                if not st or st.get("done"):
                    return
                st["done"] = True
                target = random.randint(1, 9)
                picks = st.get("picks", {})
                if not picks:
                    await context.bot.send_message(int(st["chat_id"]),
                        f"👑 عدد سلطنتی <b>{pnum(target)}</b> بود — کسی نگرفت! 👑گمش")
                    return
                best_uid, best_num, best_diff = None, None, 99
                for uid_s, num in picks.items():
                    diff = abs(int(num) - target)
                    if diff < best_diff:
                        best_diff, best_uid, best_num = diff, int(uid_s), int(num)
                winner = best_uid
                if winner:
                    add_coins(winner, 30)
                    add_xp(winner, 10)
                await context.bot.send_message(int(st["chat_id"]),
                    f"👑 <b>عدد سلطنتی: {pnum(target)}!</b>\n"
                    f"━━━━━━━━━━━━━━━━━━\n"
                    f"🏆 نزدیک‌ترین: {mention_user(winner, name_of(winner))} با عدد {pnum(best_num)}\n"
                    f"💰 جایزه: +۳۰ سکه · تاج سلطنت از آنِ شما! 👑",
                    parse_mode=ParseMode.HTML)
            except Exception:
                pass
        asyncio.get_event_loop().create_task(_reveal())
    except Exception as exc:
        log_event("error", "system", f"cmd_apexroyale failed: {exc!r}", actor=int(user.id))


async def fun_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """منوی بازی‌های مهمانی (خصوصی) و مدیریت کالبک‌های WYR/LIKELY."""
    query = update.callback_query
    if query is None:
        return
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    uid = int(query.from_user.id)
    # 🧩 (۸.۰) معمای ایموجی — اولین جواب درست
    if action == "RID" and len(parts) >= 4:
        code, idx_s = parts[2], parts[3]
        try:
            idx = int(idx_s) if idx_s.isdigit() else -1
            store = context.application.bot_data.setdefault("riddle", {})
            st = store.get(str(code))
            if not st or st.get("done"):
                await safe_answer_query(query, "❌ این معما تمام شده!")
                return
            # گزینه‌های نمایش هم‌ترتیبِ ارسال: از متن دکمه‌ها می‌خوانیم
            opts = [b.text.split(" ", 1)[-1] for r in query.message.reply_markup.inline_keyboard for b in r]
            chosen = opts[idx] if 0 <= idx < len(opts) else ""
            if chosen == st.get("answer"):
                st["done"] = True
                add_coins(int(uid), 15)
                add_xp(int(uid), 10)
                await safe_answer_query(query, f"🎉 درست! جواب: {st.get('answer')}\n+۱۵ سکه از آنِ تو!")
                try:
                    await query.edit_message_text(
                        f"🧩 <b>معمای ایموجی</b>\n━━━━━━━━━━━━━━━━━━\n\n🎁 حل شد!\n🏆 برنده: {mention_user(int(uid), name_of(int(uid)))}",
                        parse_mode=ParseMode.HTML)
                except Exception:
                    pass
            else:
                await safe_answer_query(query, "❌ نه! شانس دیگری نیست — فقط اولین جواب درست برنده است.")
        except Exception:
            await safe_answer_query(query, UX_MSG["error_generic"])
        return
    # 👑 (۸.۰) عدد سلطنتی — ثبت انتخاب عدد
    if action == "NR" and len(parts) >= 4:
        code, num_s = parts[2], parts[3]
        try:
            num = int(num_s) if num_s.isdigit() else 0
            store = context.application.bot_data.setdefault("royale", {})
            st = store.get(str(code))
            if not st or st.get("done"):
                await safe_answer_query(query, "❌ این دور تمام شده!")
                return
            picks = st.setdefault("picks", {})
            if str(uid) in picks:
                await safe_answer_query(query, "✅ عددت ثبت شده — منتظر اعلام باش!")
                return
            picks[str(uid)] = num
            await safe_answer_query(query, f"👑 عدد {pnum(num)} برداشتی! منتظر اعلام عدد سلطنتی...")
        except Exception:
            await safe_answer_query(query, UX_MSG["error_generic"])
        return
    # مدیریت رأی‌های WYR (می‌کردی؟)
    if action == "WYR" and len(parts) >= 4:
        poll_id = parts[2]
        choice = parts[3]  # "a" یا "b"
        # ثبت رأی در v24_store
        try:
            store = v24_store()
            polls = store.setdefault("wyr_polls", {})
            poll = polls.get(str(poll_id), {"a": 0, "b": 0, "voters": []})
            if int(uid) not in [int(x) for x in poll.get("voters", [])]:
                poll[choice] = int(poll.get(choice, 0)) + 1
                poll.setdefault("voters", []).append(int(uid))
                polls[str(poll_id)] = poll
                add_xp(int(uid), 2)
                bump_mission_progress(int(uid), "votes", 1)
                await safe_answer_query(query, "✅ رأی‌ت ثبت شد! +۲ ایکس‌پی")
            else:
                await safe_answer_query(query, "✅ قبلاً رأی دادی!")
        except Exception:
            await safe_answer_query(query, UX_MSG["error_generic"])
        return
    # مدیریت رأی‌های LIKELY (به احتمال زیاد کی؟)
    if action == "LIKELY" and len(parts) >= 4:
        poll_id = parts[2]
        target_uid = int(parts[3])
        try:
            store = v24_store()
            polls = store.setdefault("likely_polls", {})
            poll = polls.get(str(poll_id), {"votes": {}, "voters": []})
            if int(uid) not in [int(x) for x in poll.get("voters", [])]:
                votes = poll.setdefault("votes", {})
                votes[str(target_uid)] = int(votes.get(str(target_uid), 0)) + 1
                poll.setdefault("voters", []).append(int(uid))
                polls[str(poll_id)] = poll
                add_xp(int(uid), 2)
                bump_mission_progress(int(uid), "votes", 1)
                await safe_answer_query(query, "✅ رأی‌ت ثبت شد! +۲ ایکس‌پی")
            else:
                await safe_answer_query(query, "✅ قبلاً رأی دادی!")
        except Exception:
            await safe_answer_query(query, UX_MSG["error_generic"])
        return
    # منوی اصلی بازی‌های مهمانی — تایتان (۸.۰)
    if action == "HOME" or not action:
        await safe_answer_query(query)
        await safe_edit(
            query,
            f"{ds_top('🎉')}\n"
            "│  🎉 <b>بازی‌های مهمانی</b>\n"
            f"{ds_sep()}\n"
            "│  این‌ها همه در <b>گروه</b> اجرا می‌شوند — با دوستات!:\n\n"
            "│  🎰 <code>/apexspin</code> — گردونه‌ی بطری\n"
            "│  🤔 <code>/apexwyr</code> — می‌کردی؟ (رأی زنده)\n"
            "│  🙈 <code>/apexnhie</code> — هرگز نشده\n"
            "│  🎯 <code>/apexlikely</code> — به احتمال زیاد کی؟\n"
            "│  👑 <code>/apexroyale</code> — عدد سلطنتی (جدید!)\n"
            "│  🧩 <code>/apexriddle</code> — معمای ایموجی (جدید!)\n"
            "│  🎭 <code>/apexpersona</code> — کارت شخصیت (جدید!)\n\n"
            "│  🤺 <code>/apexduel</code> — دوئل دو نفره\n"
            "│  🛒 <code>/apexteambattle</code> — نبرد تیمی\n\n"
            "│  💡 دستور را در گروه بفرست و جادو را ببین ✨",
            kb([
                [btn("🎲 بازی‌های بیشتر", "FY|MORE")],
                [btn("❓ راهنمای این بخش", "GD|PARTY")],
                nav_footer(),
            ]),
        )
        return
    if action == "MORE":
        await safe_answer_query(query)
        await safe_edit(
            query,
            f"{ds_top('🎮')}\n"
            "│  🎮 <b>بازی‌های بیشتر</b>\n"
            f"{ds_sep()}\n"
            "🎲 <code>/apexdice</code> — تاس\n"
            "🪙 <code>/apexcoin</code> — شیر یا خط\n"
            "🎱 <code>/apex8ball</code> — هشت‌گوی جادویی\n"
            "🍀 <code>/apexluck</code> — گردونه‌ی شانس\n"
            "🧮 <code>/apexquiz</code> — مسابقه‌ی ریاضی\n"
            "❤️ <code>/apexlove</code> — عشق‌سنج\n"
            "💌 <code>/apexlove2</code> — عشق‌سنج دو نفره\n\n"
            "💡 برای اجرا، در گروه یا خصوصی دستور رو بفرست.",
            kb([
                [btn("⬅️ بازگشت", "FY|HOME")],
                nav_footer(),
            ]),
        )
        return
    await safe_answer_query(query)


# ================================================================
#  موتور پیام‌های متنی عمومی
# ================================================================

async def route_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """اولویت‌بندی پیام‌های متنی غیر-دستوری."""
    # ۰) ✏️ (۸.۰) بیوی پروفایل — حالت ورود متن
    try:
        _bio_chat = update.effective_chat
        _bio_user = update.effective_user
        _bio_msg = update.message
        if _bio_chat is not None and _bio_chat.type == "private" and _bio_user and _bio_msg and _bio_msg.text:
            if DATA.get("_await_bio", {}).get(str(_bio_user.id)):
                bio_text = str(_bio_msg.text or "").strip()[:120]
                DATA.get("_await_bio", {}).pop(str(_bio_user.id), None)
                if bio_text:
                    get_user(int(_bio_user.id))["bio"] = bio_text
                    await _bio_msg.reply_text("✅ بیوی جدید ثبت شد!")
                else:
                    await _bio_msg.reply_text("❌ بیوی خالی است!")
                await _bio_msg.reply_text(profile_text(int(_bio_user.id)), parse_mode=ParseMode.HTML,
                    reply_markup=kb([
                        [btn("✏️ تغییر بایو", "P|BIO"), btn("🖼 ویترین", "P|SHOWCASE")],
                        nav_footer(),
                    ]))
                return
    except Exception:
        pass
    # ۰.۵) 🎁 (۹.۰) کد هدیه — حالت ورود متن
    try:
        if (_bio_chat is not None and _bio_chat.type == "private" and _bio_user
                and _bio_msg and _bio_msg.text
                and DATA.get("_await_gift", {}).get(str(_bio_user.id))):
            DATA.get("_await_gift", {}).pop(str(_bio_user.id), None)
            ok, message = v9_gift_redeem(int(_bio_user.id), str(_bio_msg.text or "").strip())
            await _bio_msg.reply_text(message)
            if ok:
                u_self = get_user(int(_bio_user.id))
                await _bio_msg.reply_text(
                    ds_top("🪙") + "\n" + ds_head("🪙", "کیف پول",
                    f"موجودی جدید: {pnum(int(u_self.get('coins', 0)))} سکه") + "\n" + ds_close("🪙"),
                    reply_markup=kb([[btn("🛍 فروشگاه", "S|HOME", "primary")], nav_footer()]),
                    parse_mode=ParseMode.HTML)
            return
    except Exception:
        pass
    # ۱) ادمین: ویزاردها
    try:
        if await admin_text_router(update, context):
            return
    except Exception:
        pass
    # ۱.۲) 🪄 نسخه ۶.۲ — هوشمندِ ریپلای «خصوصی»: بعد از ویزاردهای ادمین.
    #      (در گروه، بعد از موتور پاسخ بازی می‌آید تا «گزارش» روی کارت سوالِ فعال
    #       توسط همان موتور تخصصی مدیریت شود — رجوع به گام ۵.۵)
    try:
        _chat_early = update.effective_chat
        if _chat_early is None or _chat_early.type == "private":
            if await universal_reply_router(update, context):
                return
    except Exception:
        pass
    # ۱.۵) 1.1.0 — حالت‌های ورودی کاربر (افزودن دوست، رقیب، بازخورد)
    try:
        if await user_input_router_v11(update, context):
            return
    except Exception:
        pass
    # ۲) عشق‌سنج دو نفره (خصوصی)
    try:
        if await love2_handle_text(update, context):
            return
    except Exception:
        pass
    # ۳) دوئل (خصوصی)
    try:
        if await duel_handle_text(update, context):
            return
    except Exception:
        pass
    # ۴) کوییز فعال (خصوصی یا گروه — هر جا کوییز ساخته شده)
    try:
        if await quiz_check_answer(update, context):
            return
    except Exception:
        pass
    chat = update.effective_chat
    if chat is None or chat.type not in ("group", "supergroup"):
        # ۶) 🧠 نسخه ۶ — fallback هوشمند PV: هیچ متنی بی‌جواب نمی‌مونه
        if chat is not None and chat.type == "private":
            try:
                _free_txt = str(update.message.text or "").strip() if update.message is not None else ""
                await pv_free_text_helper(update, context, _free_txt)
            except Exception:
                pass
        return
    # ۵) جواب نوبت بازی
    try:
        if await handle_game_reply(update, context):
            return
    except Exception:
        pass
    # ۵.۵) 🪄 نسخه ۶.۲ — هوشمندِ ریپلای در گروه (بعد از موتور پاسخ بازی:
    #      ریپلایِ «گزارش» روی کارت سوالِ فعال توسط موتور بازی مدیریت می‌شود)
    try:
        if await universal_reply_router(update, context):
            return
    except Exception:
        pass
    # ۶) تریگرهای متنی گروه
    try:
        await group_text_triggers(update, context)
    except Exception:
        pass


# ================================================================
#  روتر ورودی‌های کاربر نسخه‌ی ۱.۱.۰
# ================================================================
async def user_input_router_v11(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """پردازش ورودی‌های کاربر در حالت‌های خاص (Friends Add، Rival Add، Feedback)."""
    try:
        msg = update.message
        user = update.effective_user
        if msg is None or user is None:
            return False
        # فقط در PV
        chat = update.effective_chat
        if chat is None or chat.type != "private":
            return False
        uid = int(user.id)
        text = str(msg.text or "").strip()
        if not text:
            return False
        user_data = context.application.user_data.get(uid, {})
        # حالت افزودن دوست
        if user_data.get("await_friend_add"):
            user_data.pop("await_friend_add", None)
            # تلاش برای parse کردن آیدی
            target_uid = 0
            try:
                # ممکن است آیدی عددی یا لینک tg://user?id=X باشد
                if text.lstrip("-").isdigit():
                    target_uid = int(text)
                else:
                    # استخراج از لینک
                    import re as _re
                    m = _re.search(r"id=(\d+)", text)
                    if m:
                        target_uid = int(m.group(1))
            except Exception:
                pass
            if not target_uid or target_uid == uid:
                await msg.reply_text("❌ آیدی نامعتبر. لطفاً آیدی عددی تلگرام رو بفرست.")
                return True
            ok = friend_request_send(int(uid), int(target_uid))
            if ok:
                await msg.reply_text(f"✅ درخواست دوستی به {name_of(int(target_uid))} ارسال شد!")
            else:
                await msg.reply_text("❌ درخواست ارسال نشد. شاید قبلاً دوست هستید.")
            return True
        # حالت افزودن رقیب
        if user_data.get("await_rival_add"):
            user_data.pop("await_rival_add", None)
            target_uid = 0
            try:
                if text.lstrip("-").isdigit():
                    target_uid = int(text)
                else:
                    import re as _re
                    m = _re.search(r"id=(\d+)", text)
                    if m:
                        target_uid = int(m.group(1))
            except Exception:
                pass
            if not target_uid or target_uid == uid:
                await msg.reply_text("❌ آیدی نامعتبر.")
                return True
            ok = rival_add(int(uid), int(target_uid))
            if ok:
                await msg.reply_text(f"⚔️ {name_of(int(target_uid))} به رقبایت اضافه شد!")
            else:
                await msg.reply_text("❌ اضافه نشد.")
            return True
        # حالت بازخورد (نسخه ۶ — مهلت، تلاش مجدد و کارت تأیید)
        if user_data.get("await_feedback"):
            ts_fb = float(user_data.get("await_feedback_ts") or 0)
            if ts_fb and (time.time() - ts_fb) > FB_INPUT_TIMEOUT:
                user_data.pop("await_feedback", None)
                user_data.pop("await_feedback_ts", None)
                await msg.reply_text("⌛ فرصت نوشتن بازخورد تموم شد — از منوی 📮 بازخورد دوباره شروع کن.")
                return True
            if len(text) < 5:
                # حالت فعال می‌مونه تا دوباره بنویسه
                await msg.reply_text(
                    "✍️ بازخورد کمی کوتاهه! کمی بیشتر توضیح بده (حداقل ۵ حرف).\n"
                    "⏳ هنوز تو حالت نوشتن هستی — همین الان دوباره بفرست ✅"
                )
                return True
            user_data.pop("await_feedback", None)
            user_data.pop("await_feedback_ts", None)
            entry = fb_submit(int(uid), text)
            if entry:
                await fb_confirm_card(int(uid), entry, message=msg)
            else:
                await msg.reply_text("❌ خطا در ثبت بازخورد — لطفاً چند لحظه بعد دوباره بفرست.")
            return True
        # 1.2.0 — حالت جستجوی کاربر توسط ادمین
        if user_data.get("await_admin_user_search"):
            user_data.pop("await_admin_user_search", None)
            if not has_permission(int(uid), "admin"):
                await msg.reply_text("⛔ دسترسی نداری!")
                return True
            target_uid = 0
            try:
                if text.lstrip("-").isdigit():
                    target_uid = int(text)
                else:
                    # جستجو بر اساس نام
                    for k, u in DATA.get("users", {}).items():
                        if isinstance(u, dict) and text.lower() in str(u.get("name", "")).lower():
                            target_uid = int(k)
                            break
            except Exception:
                pass
            if not target_uid or str(target_uid) not in DATA.get("users", {}):
                await msg.reply_text("❌ کاربر پیدا نشد. آیدی عددی یا بخشی از نام رو بفرست.")
                return True
            # ساخت fake query برای نمایش جزئیات کاربر
            fq = _FakeQuery(msg, user)
            await admin_user_detail_show(fq, int(target_uid))
            return True
        # 1.2.0 Extended — حالت درخواست لغو مسدودیت
        if user_data.get("await_ban_appeal"):
            user_data.pop("await_ban_appeal", None)
            if len(text) < 10:
                await msg.reply_text("❌ دلیل خیلی کوتاه است. حداقل ۱۰ حرف بنویس.")
                return True
            ok = ban_appeal_submit(int(uid), text)
            if ok:
                await msg.reply_text("⚖️ درخواستت ثبت شد! ادمین‌ها بررسی می‌کنن.")
            else:
                await msg.reply_text("❌ خطا در ثبت درخواست.")
            return True
    except Exception as exc:
        log_event("error", "system", f"user_input_router_v11 failed: {exc!r}")
    return False


# ================================================================
#  مدیریت خطا + بکاپ خودکار + ذخیره‌ی دوره‌ای
# ================================================================

async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE) -> None:
    """ثبت خطا بدون کرش؛ پیام شفاف برای کاربر."""
    try:
        err = context.error
        audit("error", 0, None, repr(err)[:400])
        # 1.1.0 — ثبت ساختاریافته
        actor_uid = 0
        if isinstance(update, Update) and update.effective_user:
            try:
                actor_uid = int(update.effective_user.id)
            except Exception:
                pass
        log_event("error", "system", f"Unhandled: {repr(err)[:150]}", actor=actor_uid,
                  details=repr(err)[:300])
        print(f"ApexRival error: {err!r}")
        # تعارض getUpdates (دو نسخه از ربات همزمان روشن)
        text = str(err)
        if "Conflict" in text and "getUpdates" in text:
            print("=" * 60)
            print("  ⚠️ هشدار: تعارض getUpdates!")
            print("  به نظر می‌رسد دو نسخه از این ربات همزمان روشن است.")
            print("  یکی را خاموش کن (مثلاً نسخه‌ی لوکال یا دپلوی قدیمی).")
            print("=" * 60)
        if isinstance(update, Update) and update.effective_chat:
            try:
                await context.bot.send_message(
                    update.effective_chat.id,
                    UX_MSG["error_generic"],
                )
            except Exception:
                pass
    except Exception:
        pass


async def _legacy_refresh_group_panels(context: ContextTypes.DEFAULT_TYPE) -> None:
    """رفرش خودکار پنل‌های گروه (لابی و بازی) هر ۳۰ ثانیه.
    نسخه‌ی قدیمی — نسخه‌ی فعال، تعریف پایین‌تر است."""
    try:
        # پنل‌های ثبت‌شده در panel_register
        registry = DATA.get("_panel_registry", {})
        if not isinstance(registry, dict) or not registry:
            return
        now = now_ts()
        for panel_key, panel_info in list(registry.items()):
            try:
                if not isinstance(panel_info, dict):
                    continue
                # انقضای پنل (۱۲ ساعت)
                if now - float(panel_info.get("ts", 0)) > 43200:
                    registry.pop(panel_key, None)
                    continue
                chat_id = int(panel_info.get("chat_id", 0))
                message_id = int(panel_info.get("message_id", 0))
                uid = int(panel_info.get("uid", 0))
                tag = str(panel_info.get("tag", ""))
                if not chat_id or not message_id:
                    continue
                # فقط در گروه
                if chat_id > 0:
                    continue
                # رفرش بر اساس نوع پنل
                if tag == "lobby" or tag == "game":
                    game = active_game(chat_id)
                    if game and str(game.get("status")) == "active":
                        # پنل بازی فعال
                        text = game_home_text(game)
                        markup = game_home_markup(game, uid)
                    elif game:
                        # پنل لابی
                        text = lobby_text(game)
                        markup = lobby_markup(game, uid)
                    else:
                        # بازی تمام شده — منوی گروه
                        text = (
                            "╭" + "━" * 22 + "╮\n"
                            "│  ⚔️ <b>منوی گروه</b>\n"
                            "├" + "━" * 22 + "┤\n"
                            "│  🎯 بازی تمام شد!\n"
                            "│  🎮 برای بازی جدید: /apex\n"
                            "╰" + "━" * 22 + "╯"
                        )
                        markup = kb([
                            [btn("🎮 ساخت لابی", "L|CREATE"), btn("⚡ بازی سریع", "L|QUICK")],
                            [btn("🔞 +۱۸", "L|ADULT"), btn("📊 آمار", "L|STATS")],
                        ])
                    try:
                        await context.bot.edit_message_text(
                            chat_id=chat_id,
                            message_id=message_id,
                            text=text,
                            parse_mode=ParseMode.HTML,
                            reply_markup=markup,
                            disable_web_page_preview=True,
                        )
                    except Exception:
                        pass
            except Exception:
                continue
    except Exception:
        pass


# ---- ⏱🫀 موتور نبض هوشمند (۱۱.۰ «نبض») ----
PANEL_TICK_EDIT_CAP = 12          # حداکثر ویرایش پنل در هر تیکِ ۱ ثانیه (ضد محدودیت نرخ تلگرام)
_panel_tick_cursor = 0            # نشانگر گردشی برای انصاف بین گروه‌ها
PANEL_SPIN_ICONS = "◐◓◑◒"         # آیکون چرخان ثانیه‌شمار
PANEL_HOLD_SECONDS = 12           # تعامل-نگه‌دار: بعد از هر کلیک، پنل این‌قدر آرام می‌گیرد
PANEL_QUESTION_MIN_INTERVAL = 15  # فاز سوال: تازه‌سازی کندتر — پنل در انتظار جواب است
_PANEL_FLOOD_UNTIL = 0.0

# آمار زنده‌ی موتور نبض — نمایش در اتاق کنترل ادمین (A|PULSE)
PULSE_STATS = {
    "sent": 0,        # ویرایش‌های ارسالی به تلگرام
    "skipped": 0,     # ویرایش‌های صرفه‌جویی‌شده (هش یکسان)
    "held": 0,        # تیک‌هایی که به تعامل کاربر احترام گذاشتند
    "floods": 0,      # دفعات فلود (RetryAfter)
    "last_flood": 0.0,
    "forced": 0,      # رفرش‌های فوری (دست ادمین)
    "cleaned": 0,     # پنل‌های مرده‌ی پاک‌شده
    "ticks": 0,       # کل تیک‌های اجرا شده
}


def pulse_stats_bump(key: str, n: int = 1) -> None:
    """شمارنده‌ی آمار موتور — امن در برابر هر خطا."""
    try:
        PULSE_STATS[key] = int(PULSE_STATS.get(key, 0)) + int(n)
    except Exception:
        pass


def panel_group_cfg(game: dict) -> dict:
    """تنظیم اختصاصی پنلِ همین گروه (از اتاق فرمان ادمین — A|GPC).
    {'on': bool, 'interval': int (۰ = جهانی), 'counter': bool}
    """
    try:
        g = get_group(int(game.get("chat_id", 0)))
        cfg = g.get("panel")
        return cfg if isinstance(cfg, dict) else {}
    except Exception:
        return {}


def _panel_counter_line(remaining: int, interval: int = 5) -> str:
    """سطر ثانیه‌شمار زنده — نوار پیشرفت ▰▱ + ثانیه‌ی فارسی + آیکون چرخان (۱۱.۰)."""
    spin = PANEL_SPIN_ICONS[int(time.time()) % 4]
    rem = max(0, int(remaining))
    iv = max(1, int(interval))
    filled = int(round(min(1.0, rem / float(iv)) * 10))
    bar = "▰" * filled + "▱" * (10 - filled)
    return f"┃  ⏱ {bar} <b>{pnum(rem)}</b> ثانیه {spin}"


def panel_reset_timer(game: dict) -> None:
    """ریست شمارنده‌ی رفرش + فعال‌سازی «تعامل-نگه‌دار» (۱۱.۰).

    بعد از هر تعامل کاربر با پنل، موتور تا PANEL_HOLD_SECONDS ثانیه
    هیچ ویرایشی نمی‌کند تا با دستِ کاربر «نجنگد» و دکمه زیر انگشتش
    عوض نشود. بعد از آن، با شمارش تازه ادامه می‌دهد.
    """
    try:
        try:
            interval = int(syscfg().get("panel_interval", 5))
        except Exception:
            interval = 5
        try:
            giv = int(panel_group_cfg(game).get("interval", 0) or 0)
        except Exception:
            giv = 0
        if giv >= 3:
            interval = giv
        now = time.time()
        game["_panel_next_full"] = now + max(3, interval)
        game["_panel_hold_until"] = now + PANEL_HOLD_SECONDS
    except Exception:
        pass


def panel_waiting_view(game: dict) -> tuple:
    """نمای «در انتظار پاسخ» — وقتی کارت سوال فعال است، پنل گروه چه نشان دهد (۶.۲)."""
    prompt = game.get("reply_prompt") if isinstance(game.get("reply_prompt"), dict) else {}
    target_uid = int(prompt.get("target_uid", 0) or 0)
    questioner = int(prompt.get("questioner_uid", 0) or 0)
    sent_ts = float(prompt.get("sent_ts", 0) or 0)
    elapsed = max(0, int(time.time() - sent_ts)) if sent_ts else 0
    clock = f"{elapsed // 60:02d}:{elapsed % 60:02d}"
    heat_info = game_heat_advanced(game)
    heat_name = heat_info.get("name", "🟢 آرام")
    scores = game.get("round_scores", {})
    players = [int(x) for x in game.get("players", [])]
    top = sorted(players, key=lambda p: -int(scores.get(str(p), 0)))[:3]
    medals = ["🥇", "🥈", "🥉"]
    board_parts = []
    for p, medal in zip(top, medals):
        board_parts.append(f"{medal}{escape(name_of(p, game))} {pnum(int(scores.get(str(p), 0)))}")
    board = "  ".join(board_parts) if board_parts else "هنوز امتیازی نیست"
    lines = [
        og_top("🎯"),
        og_head("🎯", "در انتظار پاسخ...", "کارت سوال فعال است — پاسخ با Reply به همان کارت"),
        og_sep(),
        f"┃  🎤 پرسشگر: {mention_user(questioner, name_of(questioner, game))}" if questioner else "┃  🎤 پرسشگر: —",
        f"┃  🎯 در حال پاسخ: {mention_user(target_uid, name_of(target_uid, game))}" if target_uid else "┃  🎯 در حال پاسخ: —",
        og_row("⏱ زمان پاسخ", pnum(clock)),
        og_row("🌡 گرما", heat_name),
        og_sep("◈"),
        "┃  ▎🏆 <b>جدول زنده</b>",
        f"┃  {board}",
        og_close("🎯"),
    ]
    rows = [[btn("📊 امتیازها", "G|SCORES")]]
    try:
        if game.get("leader_id"):
            rows.append([btn("🏁 پایان بازی", "G|END")])
    except Exception:
        pass
    return "\n".join(lines), kb(rows)


def _panel_views_for(game: dict) -> tuple:
    """نمای درست برای وضعیت فعلی بازی — آگاه از فاز «و» نمای فرعی (۱۱.۰).

    FIX بحرانی (۶.۲): رفرش قدیمی همیشه نمای «وضعیت» می‌ساخت و دکمه‌های
    انتخاب موضوعِ پرسشگر را روی کارت نوبت می‌بلعید!
    FIX بحرانی‌تر (۶.۳): چک فاز لابی هم اضافه شد.
    FIX ریشه‌ای (۱۱.۰): نمای فرعی (موضوعات بیشتر / امتیازها) که کاربر با
    دکمه باز کرده، حالا داخل خود بازی ثبت می‌شود و موتور همین نما را
    رندر می‌کند — دیگر هیچ نمای باز‌شده‌ای با رفرش بلعیده نمی‌شود.
    """
    sub = panel_subview_active(game)
    if sub == "moremodes":
        return moremodes_view(game)
    if sub == "scores":
        return scores_view(game)
    status = str(game.get("status", ""))
    phase = str(game.get("phase", ""))
    if status == "lobby" or phase == "lobby":
        return lobby_text(game), lobby_markup(game)
    q = current_questioner(game)
    if phase == "topic" and q is not None:
        # کارت نوبت با دکمه‌های خودش — مجوزها در لحظه‌ی کلیک چک می‌شوند
        return turn_announcement(game, int(q)), turn_markup(game, int(q))
    if phase == "target":
        return targets_view(game)
    if phase == "question":
        return panel_waiting_view(game)
    return game_home_text(game), game_home_markup(game, 0)


def _panel_hash(text: str, markup) -> int:
    """اثر انگشت محتوای پنل — برای تشخیص «ویرایش بی‌فایده» (۱۱.۰)."""
    try:
        parts = [str(text)]
        try:
            kb_rows = markup.inline_keyboard if markup is not None else None
            if kb_rows:
                for row in kb_rows:
                    for b in row:
                        parts.append(str(getattr(b, "text", "")))
                        parts.append(str(getattr(b, "callback_data", None) or getattr(b, "url", None) or ""))
        except Exception:
            pass
        return hash("\x1f".join(parts))
    except Exception:
        return 0


async def _panel_apply_edit(bot, game: dict, chat_id: int, message_id: int,
                           counter_remaining=None, interval: int = 5,
                           force: bool = False) -> bool:
    """اعمال ویرایش پنل — هش‌آگاه + بک‌آف پن‌محور (۱۱.۰).

    • هش محتوا: اگر متن و دکمه‌ها تغییری نکرده‌اند، به تلگرام چیزی
      نمی‌فرستیم — نه فلیکر، نه خطای «message is not modified».
    • RetryAfter: فقط «همین پنل» برای چند ثانیه می‌ایستد؛ بقیه‌ی
      گروه‌ها سالم به کارشان ادامه می‌دهند (قبلاً کل موتور می‌مرد!).
    """
    fp = 0
    try:
        if not force and time.time() < float(game.get("_panel_backoff_until", 0) or 0):
            return False
        text, markup = _panel_views_for(game)
        if counter_remaining is not None:
            text = text + "\n" + _panel_counter_line(counter_remaining, interval)
        fp = _panel_hash(text, markup)
        if not force and fp and fp == game.get("_panel_hash"):
            pulse_stats_bump("skipped")
            return True   # محتوا یکسان — ویرایش بی‌فایده
        await bot.edit_message_text(
            chat_id=chat_id,
            message_id=message_id,
            text=text,
            parse_mode=ParseMode.HTML,
            reply_markup=markup,
            disable_web_page_preview=True,
        )
        game["_panel_hash"] = fp
        pulse_stats_bump("sent")
        return True
    except RetryAfter as ra:
        # (۱۱.۰) فقط همین پنل مکث می‌کند — بقیه‌ی گروه‌ها سالم می‌مانند
        try:
            wait_s = float(getattr(ra, "retry_after", 5) or 5)
        except Exception:
            wait_s = 5.0
        try:
            game["_panel_backoff_until"] = time.time() + wait_s + 2.0
        except Exception:
            pass
        pulse_stats_bump("floods")
        PULSE_STATS["last_flood"] = time.time()
        return False
    except Exception as exc:
        msg = str(exc).lower()
        if "not modified" in msg:
            if fp:
                game["_panel_hash"] = fp
            pulse_stats_bump("skipped")
            return True  # محتوا یکی بود — عادی است
        if ("message to edit not found" in msg or "message id is invalid" in msg
                or "message to edit not found" in msg or "chat not found" in msg
                or "message can't be edited" in msg or "have no rights" in msg):
            # پنل مرده — دیگر مزاحم نشو
            game["_panel_msg_id"] = 0
            game["_panel_next_full"] = 0
            pulse_stats_bump("cleaned")
            return False
        return False


async def auto_refresh_group_panels(context: ContextTypes.DEFAULT_TYPE) -> None:
    """⏱🫀 موتور نبض هوشمند پنل‌های گروه (۱۱.۰ «نبض").

    • هر تیک ۱ ثانیه؛ محتوا هر «فاصله‌ی تنظیمی» کامل تازه می‌شود.
    • تعامل-نگه‌دار: بعد از هر کلیک، پنل ۱۲ ثانیه ساکت می‌ماند تا موتور
      با دست کاربر نجنگد (رفع ریشه‌ای «دکمه‌ها زیر انگشت عوض می‌شدند").
    • نمای فرعی (موضوعات بیشتر / امتیازها) هرگز بلعیده نمی‌شود.
    • هش محتوا: ویرایش تکراری = صفر (نه فلیکر، نه خطای not modified).
    • بک‌آف پن‌محور: RetryAfter فقط همان پنل را می‌ایستاند — نه کل موتور.
    • فاز سوال: خودکار آرام‌تر (حداقل ۱۵ ثانیه).
    • تنظیم اختصاصی هر گروه (اتاق فرمان ادمین — A|GPC) رعایت می‌شود.
    """
    global _panel_tick_cursor
    try:
        pulse_stats_bump("ticks")
        # فلود-کنترل سراسری فقط در بدترین حالت (تنظیم دستی/خطای غیرپن‌محور)
        if time.time() < _PANEL_FLOOD_UNTIL:
            return
        cfg = syscfg()
        if not cfg.get("panel_refresh", True):
            return
        g_interval = max(3, int(cfg.get("panel_interval", 5)))
        show_counter = bool(cfg.get("panel_countdown", True))
        # جمع‌آوری پنل‌های واجد شرایط (با تنظیم اختصاصی گروه)
        eligible: list = []
        for gid, game in list(DATA.get("games", {}).items()):
            if not isinstance(game, dict):
                continue
            status = str(game.get("status", ""))
            if status not in ("lobby", "active"):
                continue
            chat_id = int(game.get("chat_id", 0))
            panel_msg_id = int(game.get("_panel_msg_id", 0))
            if not chat_id or not panel_msg_id:
                continue
            if panel_group_cfg(game).get("on") is False:
                continue   # (۱۱.۰) این گروه از اتاق فرمان خاموش شده
            eligible.append((game, chat_id, panel_msg_id))
        if not eligible:
            return
        # انصاف بین گروه‌ها: گردشی + سقف هر تیک (ضد محدودیت نرخ)
        if len(eligible) > PANEL_TICK_EDIT_CAP:
            start = _panel_tick_cursor % len(eligible)
            rotated = eligible[start:] + eligible[:start]
            eligible = rotated[:PANEL_TICK_EDIT_CAP]
            _panel_tick_cursor = (start + PANEL_TICK_EDIT_CAP) % len(eligible) \
                if len(rotated) > PANEL_TICK_EDIT_CAP else 0
        now = time.time()
        for game, chat_id, panel_msg_id in eligible:
            try:
                # (۱۱.۰) تعامل-نگه‌دار: کاربر دارد با پنل کار می‌کند
                if now < float(game.get("_panel_hold_until", 0) or 0):
                    pulse_stats_bump("held")
                    continue
                # (۱۱.۰) تنظیم اختصاصی گروه: فاصله و ثانیه‌شمار
                pcfg = panel_group_cfg(game)
                try:
                    giv = int(pcfg.get("interval", 0) or 0)
                except Exception:
                    giv = 0
                interval = giv if giv >= 3 else g_interval
                counter_on = show_counter
                if isinstance(pcfg.get("counter"), bool):
                    counter_on = bool(pcfg["counter"])
                # (۱۱.۰) فاز سوال: آرام‌تر — پنل در انتظار جواب است
                if str(game.get("phase", "")) == "question":
                    interval = max(interval, PANEL_QUESTION_MIN_INTERVAL)
                sub = panel_subview_active(game)
                nxt = float(game.get("_panel_next_full", 0) or 0)
                if now >= nxt or nxt <= 0:
                    # رفرش کامل + شروع شمارش جدید (نمای فرعی بدون ثانیه‌شمار)
                    await _panel_apply_edit(context.bot, game, chat_id, panel_msg_id,
                                            counter_remaining=interval if (counter_on and sub is None) else None,
                                            interval=interval)
                    game["_panel_next_full"] = now + interval
                    game["_last_auto_refresh"] = now_ts()
                elif counter_on and sub is None:
                    # فقط ثانیه‌شمار جلو برود (هش داخل apply چک می‌شود)
                    remaining = max(0, int(round(nxt - now)))
                    await _panel_apply_edit(context.bot, game, chat_id, panel_msg_id,
                                            counter_remaining=remaining, interval=interval)
            except Exception:
                continue
    except Exception:
        pass


async def pulse_force_refresh(context, game: dict | None = None) -> int:
    """⚡ رفرش فوری پنل(ها) — دست ادمین از اتاق کنترل (A|PULSE / A|GPC)."""
    ok = 0
    try:
        games: list = []
        if game is not None:
            games = [game]
        else:
            games = [g for g in DATA.get("games", {}).values()
                     if isinstance(g, dict) and str(g.get("status", "")) in ("lobby", "active")
                     and int(g.get("_panel_msg_id", 0) or 0)]
        for g in games:
            try:
                chat_id = int(g.get("chat_id", 0))
                msg_id = int(g.get("_panel_msg_id", 0))
                if not chat_id or not msg_id:
                    continue
                g["_panel_hold_until"] = 0.0
                g["_panel_next_full"] = 0.0
                if await _panel_apply_edit(context.bot, g, chat_id, msg_id,
                                           counter_remaining=None, force=True):
                    ok += 1
            except Exception:
                continue
        pulse_stats_bump("forced", ok)
    except Exception:
        pass
    return ok


def pulse_cleanup_dead_panels() -> int:
    """🧹 پاک‌سازی پنل‌های مرده/بازی‌های تمام‌شده (۱۱.۰)."""
    n = 0
    try:
        reg = DATA.get("_panel_registry", {})
        if isinstance(reg, dict):
            now = now_ts()
            for k, info in list(reg.items()):
                if not isinstance(info, dict):
                    reg.pop(k, None)
                    n += 1
                    continue
                if now - float(info.get("ts", 0) or 0) > 43200:
                    reg.pop(k, None)
                    n += 1
        for g in DATA.get("games", {}).values():
            if isinstance(g, dict) and str(g.get("status", "")) not in ("lobby", "active"):
                if int(g.get("_panel_msg_id", 0) or 0):
                    g["_panel_msg_id"] = 0
                    n += 1
        pulse_stats_bump("cleaned", n)
    except Exception:
        pass
    return n


def pulse_live_panels() -> list:
    """فهرست (کلید، بازی)های دارای پنل زنده — برای مدیر پنل گروه‌ها (A|GPANELS)."""
    out = []
    try:
        for gid, g in DATA.get("games", {}).items():
            if not isinstance(g, dict):
                continue
            if str(g.get("status", "")) not in ("lobby", "active"):
                continue
            if not int(g.get("_panel_msg_id", 0) or 0):
                continue
            out.append((gid, g))
    except Exception:
        pass
    return out


async def home_living_tick(context: ContextTypes.DEFAULT_TYPE) -> None:
    """🎬 موتور منوی زنده (۶.۵) — پالس آیکون‌های منوی خصوصی.

    • هر تیک ۱ ثانیه اجرا می‌شود؛ هر «فاصله‌ی تنظیمی» (پیش‌فرض ۵ ثانیه)
      فریم آیکون‌های منوی اصلی جلو می‌رود (مثلاً 🎮↔🕹️).
    • رنگ‌های واقعی دکمه‌ها (۶.۶ — Bot API 9.4) ثابت می‌مانند — هویت بخش‌ها همیشه پایدار است.
    • فقط پیامِ منوی اصلیِ «همین حالا باز» را ویرایش می‌کند؛ به محض
      خروج کاربر از خانه، نگهبانِ home_live_guard آن را از فهرست خارج
      کرده و موتور دیگر به پیام دست نمی‌زند (سازگار با سیستم تک‌پیام).
    • فلود-کنترل تلگرام: در مکثِ سراسری هیچ ویرایشی نمی‌کند؛ RetryAfter
      مکث هوشمند می‌دهد؛ پیام مرده خودکار از فهرست پاک می‌شود.
    """
    global _PANEL_FLOOD_UNTIL
    try:
        if time.time() < _PANEL_FLOOD_UNTIL:
            return
        cfg = syscfg()
        if not cfg.get("home_anim", True):
            return
        interval = max(3, min(60, int(cfg.get("home_anim_interval", 5))))
        now = time.time()
        for uid, info in list(_home_live.items()):
            try:
                if now < float(info.get("due", 0)):
                    continue  # هنوز وقت فریم بعدی نرسیده
                info["due"] = now + interval
                frame = int(info.get("frame", 1)) % 4
                info["frame"] = (frame + 1) % 4
                # (۹.۰) رندر تطبیقی: فریمِ هر کاربر با حالت نمایش خودش
                RENDER_MODE.set(user_display_mode(int(uid)))
                await context.bot.edit_message_text(
                    chat_id=info["chat_id"],
                    message_id=info["msg_id"],
                    text=private_home_text(uid, frame),
                    parse_mode=ParseMode.HTML,
                    reply_markup=private_home_markup(uid, frame),
                    disable_web_page_preview=True,
                )
            except RetryAfter as exc:
                # فلود-کنترل تلگرام: مکث هوشمند کل موتور
                _PANEL_FLOOD_UNTIL = time.time() + float(getattr(exc, "retry_after", 3) or 3) + 1.5
                break
            except BadRequest as exc:
                msg = str(exc).lower()
                if "not modified" in msg:
                    continue  # محتوا تفاوتی نکرده — بی‌صدا رد شو
                # پیام حذف شده / قدیمی / غیرقابل ویرایش → از فهرست پاک شو
                _home_live.pop(uid, None)
            except Exception:
                _home_live.pop(uid, None)
    except Exception:
        pass


async def periodic_maintenance(context: ContextTypes.DEFAULT_TYPE) -> None:
    """هر ۳ دقیقه: ذخیره + نگهبان نوبت + بازیابی بازی گیرکرده + چالش روزانه."""
    try:
        save_data()
    except Exception:
        pass
    # (۹.۰) زمان‌بندی تعمیرات — فعال‌سازی خودکار
    try:
        sched = DATA.get("v9_maint_scheduled", 0)
        if sched and not maintenance_active() and now_ts() >= int(sched):
            DATA["maintenance_mode"] = True
            DATA.pop("v9_maint_scheduled", None)
            save_data(force=True)
            log_event("warn", "admin", "Scheduled maintenance activated automatically")
    except Exception:
        pass
    try:
        await stall_guard_job(context)
    except Exception:
        pass
    try:
        await stuck_recovery_job(context)
    except Exception:
        pass
    try:
        # جایزه‌ی چالش روزانه: اگر claimed تازه شده، جشن بده
        for gk, group in DATA.get("groups", {}).items():
            try:
                gid = int(gk)
            except Exception:
                continue
            e = v20_store()["daily"].get(gk)
            if isinstance(e, dict) and e.get("claimed") and not e.get("celebrated"):
                e["celebrated"] = True
                await daily_celebrate(context, gid)
    except Exception:
        pass
    # --- 1.1.0 — Crash Recovery برای Private Matches ---
    try:
        now = now_ts()
        for mid, m in list(DATA.get("private_matches", {}).items()):
            if not isinstance(m, dict):
                continue
            status = str(m.get("status", ""))
            created = int(m.get("created_at", 0))
            # مسابقات waiting بیش از ۳۰ دقیقه → لغو
            if status == "waiting" and created and (now - created) > 1800:
                m["status"] = "cancelled"
                m["finished_at"] = now
                m["finish_reason"] = "timeout_no_opponent"
                log_event("info", "system", f"PM {mid} auto-cancelled (no opponent)")
            # مسابقات active بیش از ۲۴ ساعت → پایان با وضعیت مساوی
            elif status == "active":
                started = int(m.get("started_at", 0))
                if started and (now - started) > 86400:
                    m["status"] = "finished"
                    m["finished_at"] = now
                    m["finish_reason"] = "timeout_inactivity"
                    m["winner"] = 0
                    log_event("info", "system", f"PM {mid} auto-ended (inactivity)")
    except Exception:
        pass
    # --- 1.1.0 — پایان فصل‌های منقضی ---
    try:
        sid = str(DATA.get("season_current", "") or "")
        if sid:
            s = DATA.get("seasons", {}).get(sid)
            if isinstance(s, dict) and int(s.get("end", 0)) <= now_ts() and not s.get("finalized"):
                finalize_season(sid)
                # ساخت فصل جدید در فراخوانی بعدی current_season_id
                DATA["season_current"] = ""
    except Exception:
        pass
    # --- 1.1.0 — پاکسازی Event های منقضی ---
    try:
        for eid, ev in list(DATA.get("events", {}).items()):
            if not isinstance(ev, dict):
                continue
            if int(ev.get("end", 0)) and now > int(ev.get("end", 0)):
                # Event را نگه می‌داریم برای تاریخچه ولی فعال نیست
                ev["active"] = False
    except Exception:
        pass
    # --- 1.2.0 — Crash Recovery برای Games اصلی ---
    try:
        fixes = crash_recovery_games()
        if fixes:
            for fix in fixes:
                log_event("info", "system", f"Game {fix.get('game')} {fix.get('action')}")
    except Exception:
        pass
    # --- 1.2.0 — پاکسازی Survival Sessions قدیمی ---
    try:
        # Session های قدیمی (>2 ساعت) را پاک کن
        cutoff = now_ts() - 2 * 3600
        for sid in list(SURVIVAL_SESSIONS.keys()):
            s = SURVIVAL_SESSIONS.get(sid)
            if isinstance(s, dict):
                started = int(s.get("started_at", 0))
                if started and started < cutoff:
                    SURVIVAL_SESSIONS.pop(sid, None)
    except Exception:
        pass
    # --- 1.2.0 — آپدیت Player of the Day ---
    try:
        # پاکسازی _active_uids قدیمی (>2 روز)
        cutoff_day = (now_ts() - 2 * 86400) // 86400
        for d_key in list(DATA.get("analytics_daily", {}).keys()):
            try:
                # parse YYYY-MM-DD
                from datetime import datetime as _dt
                d_dt = _dt.strptime(d_key, "%Y-%m-%d")
                d_ts = int(d_dt.timestamp())
                if d_ts < cutoff_day * 86400:
                    # نگه‌داری آمار ولی پاک‌سازی active_uids
                    d_data = DATA["analytics_daily"].get(d_key, {})
                    d_data.pop("_active_uids", None)
            except Exception:
                pass
    except Exception:
        pass
    # --- 1.2.0 Extended — بررسی Birthday و Anniversary ---
    try:
        # فقط کاربران فعال امروز رو بررسی کن
        today = today_key()
        d = DATA.get("analytics_daily", {}).get(today, {})
        active_uids = d.get("_active_uids", [])
        for uid in active_uids:
            try:
                check_birthday_reward(int(uid))
                check_anniversary_reward(int(uid))
                check_milestones(int(uid))
            except Exception:
                pass
    except Exception:
        pass
    # --- 1.2.0 Extended — آپدیت Hall of Fame (هر ۳۰ دقیقه) ---
    try:
        if (now_ts() // 180) % 10 == 0:  # هر ~30 دقیقه
            hall_of_fame_update()
    except Exception:
        pass
    # --- 1.2.0 Extended — پاکسازی Matchmaking Queue قدیمی ---
    try:
        queue = DATA.get("matchmaking_queue", [])
        cutoff = now_ts() - 600  # 10 دقیقه
        DATA["matchmaking_queue"] = [e for e in queue
                                       if isinstance(e, dict) and int(e.get("joined_at", 0)) > cutoff]
    except Exception:
        pass


